INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u2-C6','kor',4,1,'u2',2,'글쓴이의 의견 찾기 — 글쓴이가 우리에게 어떻게 하자고 바라는지 찾음 — 걱정한 내용이나 지나치게 넓힌 말이 아님',ARRAY['[4국01-06]·[4국02-04](차시 머리 표기 — 단원 도입)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
