INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u2-C11','kor',4,1,'u2',2,'의견의 뜻 — 어떤 일에 대해 가지는 생각 — 의견을 말할 때에는 뒷받침하는 이유도 함께 말함',ARRAY['[4국01-06](차시 머리 표기 — 토의하기)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
