INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u2-C13','kor',4,1,'u2',2,'의견을 마련하는 차례 — 의견 떠올리기 → 실천 가능성 생각하기 → 이유 마련하기 → 단점도 생각해 보기',ARRAY['[4국01-06](차시 머리 표기 — 토의하기)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u2-C14','kor',4,1,'u2',2,'실천 가능성 — 모든 친구가 해낼 수 있는 의견인지 따져 봄',ARRAY['[4국01-06](차시 머리 표기 — 토의하기)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
