INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u2-C60','kor',4,1,'u2',11,'넓은 무리와 그 안에 드는 말 — 「곤충」 안에 「메뚜기 · 모기」가 들듯이 더 넓은 무리를 나타내는 말과 그 안에 드는 말이 있음',ARRAY['낱말의 넓은 무리와 그 안에 드는 말(성취기준 번호 확인 필요)']::text[],60) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u2-C61','kor',4,1,'u2',11,'넓은 무리는 정해져 있지 않음 — 「새」는 「동물」 안에 들면서 「참새」를 품는 넓은 무리이기도 함',ARRAY['낱말의 넓은 무리와 그 안에 드는 말(성취기준 번호 확인 필요)']::text[],61) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u2-C62','kor',4,1,'u2',11,'단원 정리 — 절차를 지키며 토의하기 · 사실과 의견 가르기 · 글쓴이의 의견 파악 → 비교 → 평가',ARRAY['배운 내용 실천하기(성취기준 번호 확인 필요)']::text[],62) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X01','kor',4,'u2',ARRAY['K4-1-u2-C1','K4-1-u2-C62']::text[],'이 단원에서 배울 것을 토의 · 의견 파악 · 비교 · 평가가 아닌 것(빨리 읽기 · 외우기 · 셈하기)으로 여긴다','토의 · 의견') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X02','kor',4,'u2',ARRAY['K4-1-u2-C2']::text[],'서로 다른 의견이 나오면 다툼이 생긴 것이라 여겨 피해야 한다고 생각한다','다름은 열쇠') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X03','kor',4,'u2',ARRAY['K4-1-u2-C3']::text[],'여럿이 의견을 나누면 언제나 가장 빨리 끝난다고 여긴다','더 많은 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X04','kor',4,'u2',ARRAY['K4-1-u2-C5']::text[],'혼자 정하면 되는 일도 토의가 필요하다고 여긴다','함께 정할 일인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X05','kor',4,'u2',ARRAY['K4-1-u2-C4','K4-1-u2-C2']::text[],'토의를 이기고 지는 말싸움으로 여긴다','함께 답 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X06','kor',4,'u2',ARRAY['K4-1-u2-C6','K4-1-u2-C35']::text[],'글쓴이의 의견을 글에 나온 걱정이나 상황, 또는 지나치게 넓힌 말로 읽는다','어떻게 하자고 했나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X07','kor',4,'u2',ARRAY['K4-1-u2-C7','K4-1-u2-C41']::text[],'글쓴이의 의견은 내 생각과 견주지 않고 그대로 받아들이면 된다고 여긴다','내 생각과 견주어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X08','kor',4,'u2',ARRAY['K4-1-u2-C9','K4-1-u2-C8']::text[],'우리 힘으로 해결할 수 없는 일도 토의 주제로 고른다','우리가 바꿀 수 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X09','kor',4,'u2',ARRAY['K4-1-u2-C10','K4-1-u2-C8']::text[],'된다 · 안 된다 두 의견만 나오는 물음을 토의 주제로 고른다','여러 방법이 나오나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X10','kor',4,'u2',ARRAY['K4-1-u2-C8','K4-1-u2-C5']::text[],'모두와 관련 없는 내 취향 물음을 토의 주제로 고른다','모두와 관련 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X11','kor',4,'u2',ARRAY['K4-1-u2-C12']::text[],'의견과 이어지지 않는 말(꾸미기 · 재미 · 상관없는 사실)을 이유로 든다','실천하면 무엇이 좋아지나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X12','kor',4,'u2',ARRAY['K4-1-u2-C12','K4-1-u2-C11']::text[],'「왜냐하면」만 붙이면 무엇이든 이유가 된다고 여긴다','말이 이어지나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X13','kor',4,'u2',ARRAY['K4-1-u2-C14']::text[],'모든 친구가 해낼 수 있는지 따지지 않고 의견을 낸다','모두 할 수 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X14','kor',4,'u2',ARRAY['K4-1-u2-C15']::text[],'단점이 하나라도 있으면 그 의견은 버려야 한다고 여긴다','고치면 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X15','kor',4,'u2',ARRAY['K4-1-u2-C13','K4-1-u2-C15']::text[],'의견을 마련할 때 단점은 생각하지 않아도 된다고 여긴다','단점도 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X16','kor',4,'u2',ARRAY['K4-1-u2-C13']::text[],'의견을 마련하는 단계와 할 일을 엇갈리게 잇는다','단계마다 할 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X17','kor',4,'u2',ARRAY['K4-1-u2-C16']::text[],'토의 절차의 차례를 바꾼다(결정을 먼저 하거나 주제를 나중에 정함)','주제 → 마련 → 모으기 → 결정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X18','kor',4,'u2',ARRAY['K4-1-u2-C17']::text[],'시간이 걸린다고 의견 모으기를 건너뛰어도 된다고 여긴다','건너뛰지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X19','kor',4,'u2',ARRAY['K4-1-u2-C20']::text[],'사회자가 자기 의견을 가장 좋은 의견으로 정해도 된다고 여긴다','사회자는 이끄는 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X20','kor',4,'u2',ARRAY['K4-1-u2-C19']::text[],'사회자는 말을 잘하는 친구에게만 기회를 주거나 주제에서 벗어나도 그냥 둔다고 여긴다','고르게 · 주제 안에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X21','kor',4,'u2',ARRAY['K4-1-u2-C21']::text[],'친구가 말하는 중간에 끼어들어 반박해도 된다고 여긴다','끝까지 들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X22','kor',4,'u2',ARRAY['K4-1-u2-C21','K4-1-u2-C2']::text[],'내 의견이 아니면 무조건 반대한다','다른 의견도 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X23','kor',4,'u2',ARRAY['K4-1-u2-C23']::text[],'다른 의견을 따져 보는 것을 흠잡기로 여겨 피하거나, 까닭 없이 「별로야」라고만 말한다','까닭도 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X24','kor',4,'u2',ARRAY['K4-1-u2-C24']::text[],'누가 냈는지(목소리가 큰 친구 · 친한 친구)로 의견을 판단한다','누가 아니라 무엇을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X25','kor',4,'u2',ARRAY['K4-1-u2-C26']::text[],'가장 먼저 말한 의견으로 정해야 한다고 여긴다','먼저보다 알맞음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X26','kor',4,'u2',ARRAY['K4-1-u2-C26','K4-1-u2-C18']::text[],'좋은 의견이 여럿이어도 꼭 한 가지만 골라야 한다고 여긴다','합쳐도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X27','kor',4,'u2',ARRAY['K4-1-u2-C25','K4-1-u2-C18']::text[],'까닭 없이 뽑기나 가위바위보로 의견을 정한다','기준을 세워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X28','kor',4,'u2',ARRAY['K4-1-u2-C29','K4-1-u2-C30']::text[],'글쓴이의 생각을 나타낸 문장을 사실로 여긴다','생각인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X29','kor',4,'u2',ARRAY['K4-1-u2-C28','K4-1-u2-C30']::text[],'실제로 있었던 일을 알려 주는 문장을 의견으로 여긴다','있었던 일인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X30','kor',4,'u2',ARRAY['K4-1-u2-C28','K4-1-u2-C29']::text[],'의견도 사실처럼 맞다 · 틀리다로 따진다','의견은 알맞은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X31','kor',4,'u2',ARRAY['K4-1-u2-C30']::text[],'문장 끝말과 그 끝말이 주로 나타내는 것을 엇갈리게 잇는다','끝말을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X32','kor',4,'u2',ARRAY['K4-1-u2-C31']::text[],'글의 길이나 가장 어려운 낱말 하나로 글쓴이의 의견을 찾으려 한다','되풀이 · 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X33','kor',4,'u2',ARRAY['K4-1-u2-C32']::text[],'글쓴이의 의견은 언제나 마지막 문장에만 있다고 여긴다','첫 문장도 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X34','kor',4,'u2',ARRAY['K4-1-u2-C33']::text[],'의견을 파악하는 까닭을 낱말 외우기나 글자 세기로 여긴다','비교 · 평가로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X35','kor',4,'u2',ARRAY['K4-1-u2-C36','K4-1-u2-C37']::text[],'의견과 상관없는 사실을 뒷받침 내용으로 고른다','왜 하자는 걸까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X36','kor',4,'u2',ARRAY['K4-1-u2-C38']::text[],'글쓴이와 다른 의견을 고를 때 글쓴이의 뒷받침을 되풀이한 말을 고른다','어긋나는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X37','kor',4,'u2',ARRAY['K4-1-u2-C39']::text[],'두 의견을 견주면 같은 점이나 다른 점 가운데 하나만 나온다고 여긴다','함께 나와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X38','kor',4,'u2',ARRAY['K4-1-u2-C40']::text[],'의견을 비교할 때 같다 · 다르다 한마디로 끝내고 뒷받침은 견주지 않는다','왜 같고 다른가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X39','kor',4,'u2',ARRAY['K4-1-u2-C41','K4-1-u2-C50']::text[],'비교나 평가를 글쓴이를 이기거나 틀렸다고 말하려는 일로 여긴다','이기기가 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X40','kor',4,'u2',ARRAY['K4-1-u2-C42']::text[],'내 의견만 말하고 받쳐 줄 뒷받침 내용은 세우지 않는다','왜냐하면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X41','kor',4,'u2',ARRAY['K4-1-u2-C43']::text[],'남의 의견이 알맞은지 따져 보지 않고 그대로 따른다','당나귀 이야기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X42','kor',4,'u2',ARRAY['K4-1-u2-C44']::text[],'개방 · 보존 · 훼손의 뜻을 엇갈리게 안다','열기 · 지키기 · 망가뜨리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X43','kor',4,'u2',ARRAY['K4-1-u2-C45']::text[],'뒷받침 내용이 의견과 이어지는지 살피지 않는다','의견과 이어지나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X44','kor',4,'u2',ARRAY['K4-1-u2-C46']::text[],'「누가 그러는데」 같은 소문도 믿을 수 있는 뒷받침으로 여긴다','확인할 수 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X45','kor',4,'u2',ARRAY['K4-1-u2-C47']::text[],'의견대로 했을 때 생길 다른 문제는 따지지 않는다','다른 문제는 없나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X46','kor',4,'u2',ARRAY['K4-1-u2-C48']::text[],'글의 길이나 글쓴이와 친한 정도를 평가 기준으로 삼는다','길이 · 친함은 상관없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X47','kor',4,'u2',ARRAY['K4-1-u2-C49']::text[],'준비한 뒤 열자는 글의 의견을 「무조건 막자」로 지나치게 넓혀 읽는다','마지막 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X48','kor',4,'u2',ARRAY['K4-1-u2-C50']::text[],'의견 평가에는 답이 하나로 정해져 있다고 여기거나, 까닭 없이 아무렇게나 평가해도 된다고 여긴다','까닭이 중요해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X49','kor',4,'u2',ARRAY['K4-1-u2-C53']::text[],'누리집에서는 얼굴이 보이지 않으니 놀리는 댓글을 달거나 찬성한 친구에게만 답해도 된다고 여긴다','읽는 사람도 마음이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X50','kor',4,'u2',ARRAY['K4-1-u2-C54']::text[],'돈이 많이 드는 의견이나 먼저 올라온 의견을 더 좋은 의견으로 고른다','모두 · 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X51','kor',4,'u2',ARRAY['K4-1-u2-C55']::text[],'의견을 정하기만 하고 왜 그렇게 정했는지는 남기지 않는다','정한 까닭도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X52','kor',4,'u2',ARRAY['K4-1-u2-C56']::text[],'광고의 의견을 광고가 권하지 않는 쪽이나 지나친 말로 읽는다','어느 쪽을 권하나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X53','kor',4,'u2',ARRAY['K4-1-u2-C58']::text[],'-(으)ㄴ · -(으)ㄹ 뒤의 만큼 · 대로 · 뿐을 붙여 쓴다','「-ㄴ · -ㄹ」 뒤는 띄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X54','kor',4,'u2',ARRAY['K4-1-u2-C59']::text[],'이름을 나타내는 말 뒤의 만큼 · 대로 · 뿐을 띄어 쓴다','이름 뒤는 붙여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X55','kor',4,'u2',ARRAY['K4-1-u2-C58','K4-1-u2-C59']::text[],'낱말의 가운데를 띄어 쓴다(뿌 린만큼 · 선생 님만큼)','낱말은 나누지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X56','kor',4,'u2',ARRAY['K4-1-u2-C60']::text[],'넓은 무리에 들지 않는 낱말을 그 무리에 넣는다','그 무리에 드나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u2-X57','kor',4,'u2',ARRAY['K4-1-u2-C61','K4-1-u2-C60']::text[],'넓은 무리와 그 안에 드는 말의 자리를 바꾸거나, 한 낱말은 언제나 한 자리에만 있다고 여긴다','더 넓은 쪽은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#1','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C4',1,'mc','auto','어떤 일을 해결하려고 여러 사람이 의견을 나누어 가장 알맞은 방법을 찾는 말하기를 무엇이라고 하나요?',ARRAY['K4-1-u2-X05','K4-1-u2-X04','K4-1-u2-X01']::text[],false,'{"seq":1,"concept":"K4-1-u2-C4","difficulty":1,"kind":"mc","stem":"어떤 일을 해결하려고 여러 사람이 의견을 나누어 가장 알맞은 방법을 찾는 말하기를 무엇이라고 하나요?","options":[{"t":"토의","correct":true},{"t":"말싸움","mis":"K4-1-u2-X05"},{"t":"혼잣말","mis":"K4-1-u2-X04"},{"t":"받아쓰기","mis":"K4-1-u2-X01"}],"explanation":["여러 사람이 함께해요.","가장 알맞은 방법을 찾아요.","토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#2','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C5',1,'mc','auto','토의가 필요한 상황으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X04','K4-1-u2-X10']::text[],false,'{"seq":2,"concept":"K4-1-u2-C5","difficulty":1,"kind":"mc","stem":"토의가 필요한 상황으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 반 청소 구역을 어떻게 나눌까","correct":true},{"t":"오늘 내 필통에 연필을 몇 자루 넣을까","mis":"K4-1-u2-X04"},{"t":"내가 좋아하는 색깔은 무엇일까","mis":"K4-1-u2-X10"},{"t":"내 공책 표지를 무슨 색으로 할까","mis":"K4-1-u2-X04"}],"explanation":["혼자 정할 일인가요?","여럿이 함께 정할 일을 찾아요.","청소 구역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#3','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C6',1,'mc','auto','알림판에 붙은 글에서 글쓴이의 의견은 무엇인가요?',ARRAY['K4-1-u2-X06']::text[],false,'{"seq":3,"concept":"K4-1-u2-C6","difficulty":1,"kind":"mc","stem":"알림판에 붙은 글에서 글쓴이의 의견은 무엇인가요?","options":[{"t":"공은 넣어서 들고 걸어 나가자","correct":true},{"t":"점심시간에는 공놀이를 하지 말자","mis":"K4-1-u2-X06"},{"t":"운동장에 가장 먼저 나가자","mis":"K4-1-u2-X06"},{"t":"공을 들고 복도를 뛰어가자","mis":"K4-1-u2-X06"}],"explanation":["④를 다시 읽어요.","어떻게 하자고 했나요?","넣고 걸어 나가자예요."],"asset":{"type":"passage","lines":["① 점심시간에 공을 들고 복도를 지나가는 친구들이 있습니다.","② 운동장으로 빨리 나가고 싶은 마음은 저도 잘 압니다.","③ 그렇지만 공이 손에서 빠지면 지나가는 친구가 다칠 수 있습니다.","④ 공은 가방이나 주머니에 넣고 걸어서 나갔으면 좋겠습니다."],"title":"알림판에 붙은 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#4','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C11',1,'mc','auto','어떤 일에 대해 가지는 생각을 무엇이라고 하나요?',ARRAY['K4-1-u2-X29','K4-1-u2-X32','K4-1-u2-X17']::text[],false,'{"seq":4,"concept":"K4-1-u2-C11","difficulty":1,"kind":"mc","stem":"어떤 일에 대해 가지는 생각을 무엇이라고 하나요?","options":[{"t":"의견","correct":true},{"t":"사실","mis":"K4-1-u2-X29"},{"t":"제목","mis":"K4-1-u2-X32"},{"t":"차례","mis":"K4-1-u2-X17"}],"explanation":["「생각」이에요.","이유와 함께 말해요.","의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#5','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C3',2,'mc','auto','여러 사람이 의견을 나누면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X03','K4-1-u2-X05','K4-1-u2-X24']::text[],false,'{"seq":5,"concept":"K4-1-u2-C3","difficulty":2,"kind":"mc","stem":"여러 사람이 의견을 나누면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"문제를 푸는 방법을 더 많이 찾을 수 있다","correct":true},{"t":"언제나 가장 빨리 끝낼 수 있다","mis":"K4-1-u2-X03"},{"t":"말을 하지 않아도 되어서 편하다","mis":"K4-1-u2-X05"},{"t":"한 사람의 생각대로 정할 수 있다","mis":"K4-1-u2-X24"}],"explanation":["혼자 vs 여럿","생각이 모이면?","방법이 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#6','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C8',2,'match','auto','토의 주제의 세 조건과 그것을 묻는 질문을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-1-u2-C8","difficulty":2,"kind":"match","stem":"토의 주제의 세 조건과 그것을 묻는 질문을 알맞게 이으세요.","pairs":[{"l":"모두와 관련","r":"우리 모두에게 해당하는 일인가?"},{"l":"여러 의견","r":"여러 가지 방법이 나올 수 있는가?"},{"l":"해결 가능","r":"우리 힘으로 해결 방법을 찾을 수 있는가?"}],"mis":"K4-1-u2-X09","explanation":["세 가지를 대어 봐요.","하나씩 걸러요.","셋 다 갖춰야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#7','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C9',2,'mc','auto','「우리 반 교실을 더 넓힐 수 있을까」가 토의 주제로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-1-u2-X10','K4-1-u2-X09','K4-1-u2-X11']::text[],false,'{"seq":7,"concept":"K4-1-u2-C9","difficulty":2,"kind":"mc","stem":"「우리 반 교실을 더 넓힐 수 있을까」가 토의 주제로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"우리 힘으로 해결할 수 없는 일이기 때문에","correct":true},{"t":"우리 모두와 관련이 없기 때문에","mis":"K4-1-u2-X10"},{"t":"여러 가지 의견이 나오기 때문에","mis":"K4-1-u2-X09"},{"t":"교실이 이미 넓기 때문에","mis":"K4-1-u2-X11"}],"explanation":["교실 벽을 누가 옮길 수 있나요?","우리가 바꿀 수 없어요.","해결할 수 없는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#8','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C12',2,'mc','auto','「빌려 쓴 물건에 이름표를 붙이자」라는 의견에 알맞은 이유는 무엇인가요?',ARRAY['K4-1-u2-X11','K4-1-u2-X12']::text[],false,'{"seq":8,"concept":"K4-1-u2-C12","difficulty":2,"kind":"mc","stem":"「빌려 쓴 물건에 이름표를 붙이자」라는 의견에 알맞은 이유는 무엇인가요?","options":[{"t":"누가 빌려 갔는지 알 수 있어 더 조심해서 쓰기 때문에","correct":true},{"t":"이름표를 예쁘게 꾸미는 것이 재미있기 때문에","mis":"K4-1-u2-X11"},{"t":"쉬는 시간이 십 분밖에 되지 않기 때문에","mis":"K4-1-u2-X12"},{"t":"이름표는 문구점에서 팔기 때문에","mis":"K4-1-u2-X11"}],"explanation":["그렇게 하면 무엇이 좋아지나요?","의견과 이어져야 해요.","조심해서 쓰게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#9','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C12',2,'match','auto','사물함 토의에서 의견과 그 이유를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u2-C12","difficulty":2,"kind":"match","stem":"사물함 토의에서 의견과 그 이유를 알맞게 이으세요.","pairs":[{"l":"매주 한 명씩 돌아가며 살피자","r":"살피는 친구가 있으면 모두 조심해서 쓴다"},{"l":"날마다 정리하는 시간을 정하자","r":"함께 정리하며 물건을 아끼는 마음이 생긴다"},{"l":"정리하는 방법을 붙여 두자","r":"방법을 모르는 친구도 보고 따라 할 수 있다"}],"mis":"K4-1-u2-X11","explanation":["그 의견대로 하면?","좋아지는 점이 이유예요.","짝을 맞춰요."],"asset":{"type":"speech","turns":[{"who":"주제","text":"함께 쓰는 사물함이 어질러지는 문제를 어떻게 해결할까"},{"who":"하린","text":"매주 한 명씩 돌아가며 사물함을 살피면 좋겠습니다."},{"who":"하린","text":"왜냐하면 살피는 친구가 있으면 모두 조심해서 쓸 것이기 때문입니다."},{"who":"도윤","text":"날마다 정리하는 시간을 따로 정하면 좋겠습니다."},{"who":"도윤","text":"왜냐하면 다 함께 정리하며 물건을 아끼는 마음이 생기기 때문입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_basic#10','kor',4,1,'u2','L02','g4_1_kor_u2_L02_basic','lesson_basic','K4-1-u2-C10',3,'mc','auto','「교실에서 만화책을 읽어도 될까」가 토의 주제로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-1-u2-X08','K4-1-u2-X02','K4-1-u2-X04']::text[],false,'{"seq":10,"concept":"K4-1-u2-C10","difficulty":3,"kind":"mc","stem":"「교실에서 만화책을 읽어도 될까」가 토의 주제로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"된다 · 안 된다 두 가지 의견만 나오기 때문에","correct":true},{"t":"우리 힘으로 해결할 수 없는 일이기 때문에","mis":"K4-1-u2-X08"},{"t":"만화책은 읽으면 안 되는 책이기 때문에","mis":"K4-1-u2-X02"},{"t":"혼자 정하면 되는 일이기 때문에","mis":"K4-1-u2-X04"}],"explanation":["답이 몇 가지 나오나요?","된다, 안 된다","여러 방법이 나오지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#1','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C2',2,'mc','auto','모둠에서 서로 다른 의견이 나왔어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u2-X02','K4-1-u2-X24','K4-1-u2-X22']::text[],false,'{"seq":1,"concept":"K4-1-u2-C2","difficulty":2,"kind":"mc","stem":"모둠에서 서로 다른 의견이 나왔어요. 알맞은 생각은 무엇인가요?","options":[{"t":"다른 의견을 견주어 보면 더 좋은 답을 찾을 수 있다","correct":true},{"t":"다른 의견이 나오면 다툼이 생긴 것이니 그만 말한다","mis":"K4-1-u2-X02"},{"t":"목소리가 큰 친구의 의견을 따르면 된다","mis":"K4-1-u2-X24"},{"t":"다른 의견을 낸 친구는 틀린 것이다","mis":"K4-1-u2-X22"}],"explanation":["다름은 다툼일까요?","견주어 보면?","더 좋은 답의 열쇠예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#2','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C1',2,'mc','auto','「서로 다른 의견」 단원에서 배울 것으로 알맞게 묶은 것은 무엇인가요?',ARRAY['K4-1-u2-X01','K4-1-u2-X39']::text[],false,'{"seq":2,"concept":"K4-1-u2-C1","difficulty":2,"kind":"mc","stem":"「서로 다른 의견」 단원에서 배울 것으로 알맞게 묶은 것은 무엇인가요?","options":[{"t":"절차를 지키며 토의하기 · 글쓴이의 의견을 내 의견과 견주어 평가하기","correct":true},{"t":"빨리 읽기 · 글자 수 세기","mis":"K4-1-u2-X01"},{"t":"낱말 외우기 · 받아쓰기","mis":"K4-1-u2-X01"},{"t":"토의에서 이기기 · 글쓴이 틀린 곳 찾기","mis":"K4-1-u2-X39"}],"explanation":["말하기와 읽기","토의와 의견","두 가지를 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#3','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C7',3,'mc','auto','알림판 글을 「내 생각과 견주어」 읽은 것은 무엇인가요?',ARRAY['K4-1-u2-X07','K4-1-u2-X32','K4-1-u2-X24']::text[],false,'{"seq":3,"concept":"K4-1-u2-C7","difficulty":3,"kind":"mc","stem":"알림판 글을 「내 생각과 견주어」 읽은 것은 무엇인가요?","options":[{"t":"공을 넣어 가자는 말에 찬성해. 나도 복도에서 공에 맞을 뻔한 적이 있거든.","correct":true},{"t":"글쓴이가 그렇게 말했으니 그대로 따르면 돼.","mis":"K4-1-u2-X07"},{"t":"글이 네 줄이라서 짧아.","mis":"K4-1-u2-X32"},{"t":"글쓴이가 누구인지만 궁금해.","mis":"K4-1-u2-X24"}],"explanation":["내 생각은 어떤가요?","찬성 · 반대와 까닭","견주어 읽은 거예요."],"asset":{"type":"passage","lines":["① 점심시간에 공을 들고 복도를 지나가는 친구들이 있습니다.","② 운동장으로 빨리 나가고 싶은 마음은 저도 잘 압니다.","③ 그렇지만 공이 손에서 빠지면 지나가는 친구가 다칠 수 있습니다.","④ 공은 가방이나 주머니에 넣고 걸어서 나갔으면 좋겠습니다."],"title":"알림판에 붙은 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#4','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C8',3,'mc','auto','다음 가운데 토의 주제로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X08','K4-1-u2-X10','K4-1-u2-X09']::text[],false,'{"seq":4,"concept":"K4-1-u2-C8","difficulty":3,"kind":"mc","stem":"다음 가운데 토의 주제로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 반 친구들이 더 친해지려면 무엇을 할까","correct":true},{"t":"우리 학교 운동장을 몇 배로 넓힐까","mis":"K4-1-u2-X08"},{"t":"내가 가장 좋아하는 계절은 언제일까","mis":"K4-1-u2-X10"},{"t":"쉬는 시간에 복도에서 뛰어도 될까","mis":"K4-1-u2-X09"}],"explanation":["세 조건을 대어 봐요.","모두 · 여러 방법 · 우리가","친해지는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#5','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C14',3,'mc','auto','「반 친구 모두가 날마다 아침 7시에 학교에 와서 청소하자」라는 의견을 살폈어요. 무엇이 가장 걱정되나요?',ARRAY['K4-1-u2-X12','K4-1-u2-X24','K4-1-u2-X11']::text[],false,'{"seq":5,"concept":"K4-1-u2-C14","difficulty":3,"kind":"mc","stem":"「반 친구 모두가 날마다 아침 7시에 학교에 와서 청소하자」라는 의견을 살폈어요. 무엇이 가장 걱정되나요?","options":[{"t":"모든 친구가 해낼 수 있는지","correct":true},{"t":"이유가 너무 짧은지","mis":"K4-1-u2-X12"},{"t":"의견을 누가 냈는지","mis":"K4-1-u2-X24"},{"t":"청소가 재미있는지","mis":"K4-1-u2-X11"}],"explanation":["모두가 그 시간에 올 수 있나요?","실천 가능성","해낼 수 있는지 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#6','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C15',3,'mc','auto','「빌린 물건에 이름표를 붙이자」는 의견에 「이름표를 챙기기 번거롭다」는 단점이 있어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u2-X14','K4-1-u2-X15','K4-1-u2-X11']::text[],false,'{"seq":6,"concept":"K4-1-u2-C15","difficulty":3,"kind":"mc","stem":"「빌린 물건에 이름표를 붙이자」는 의견에 「이름표를 챙기기 번거롭다」는 단점이 있어요. 알맞은 생각은 무엇인가요?","options":[{"t":"단점을 고쳐 사물함 옆에 빌린 사람 알림판을 두자고 한다","correct":true},{"t":"단점이 있으니 이 의견은 버린다","mis":"K4-1-u2-X14"},{"t":"단점은 신경 쓰지 않고 그대로 말한다","mis":"K4-1-u2-X15"},{"t":"이름표를 더 예쁘게 만들자고 한다","mis":"K4-1-u2-X11"}],"explanation":["단점은 버리는 까닭일까요?","고칠 자리예요.","고친 의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#7','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C13',3,'match','auto','의견을 마련하는 단계와 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-1-u2-C13","difficulty":3,"kind":"match","stem":"의견을 마련하는 단계와 할 일을 알맞게 이으세요.","pairs":[{"l":"실천 가능성 생각하기","r":"모든 친구가 해낼 수 있는지 따져 본다"},{"l":"이유 마련하기","r":"실천했을 때 좋아지는 점을 찾아 쓴다"},{"l":"단점도 생각해 보기","r":"불편해지는 점은 없는지 살펴본다"}],"mis":"K4-1-u2-X16","explanation":["단계마다 확인할 것","해낼 수 있나 · 좋아지는 점 · 불편한 점","차례대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#8','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C12',4,'essay','teacher','「복도에서는 오른쪽으로 걷자」라는 의견에 알맞은 이유를 하나 쓰고, 「왜냐하면 오른쪽이 왼쪽보다 멋있기 때문입니다」가 이유로 알맞지 않은 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u2-C12","difficulty":4,"kind":"essay","stem":"「복도에서는 오른쪽으로 걷자」라는 의견에 알맞은 이유를 하나 쓰고, 「왜냐하면 오른쪽이 왼쪽보다 멋있기 때문입니다」가 이유로 알맞지 않은 까닭을 쓰세요.","answer_guide":{"answer":"예: 이유 — 오가는 사람이 부딪히지 않아 다치지 않기 때문입니다. 「오른쪽이 멋있다」는 그렇게 걸었을 때 좋아지는 점이 아니라 의견과 이어지지 않는 말이라서 이유가 될 수 없다.","scoring_points":["의견대로 했을 때 좋아지는 점을 이유로 썼는가","멋있다는 말이 의견과 이어지지 않음을 썼는가","「왜냐하면」을 붙여도 이유가 되지 않음을 알았는가"]},"explanation":["좋아지는 점","이어지나요?","왜냐하면만으로는"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#9','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C8',4,'essay','teacher','「우리 반 교실을 더 넓힐 수 있을까」를 토의 주제의 세 조건에 맞게 고쳐 쓰고, 고친 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u2-C8","difficulty":4,"kind":"essay","stem":"「우리 반 교실을 더 넓힐 수 있을까」를 토의 주제의 세 조건에 맞게 고쳐 쓰고, 고친 까닭을 쓰세요.","answer_guide":{"answer":"예: 「좁은 교실을 넓게 쓰려면 어떻게 할까」 — 교실을 넓히는 일은 우리 힘으로 할 수 없지만, 넓게 쓰는 방법은 우리 모두와 관련 있고 여러 가지 방법이 나오며 우리가 해결할 수 있기 때문이다.","scoring_points":["우리가 해결할 수 있는 주제로 고쳤는가","여러 의견이 나올 수 있게 고쳤는가","세 조건을 들어 까닭을 썼는가"]},"explanation":["우리가 할 수 있는 일로","여러 방법이 나오게","세 조건으로 설명"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L02_challenge#10','kor',4,1,'u2','L02','g4_1_kor_u2_L02_challenge','lesson_challenge','K4-1-u2-C13',4,'essay','teacher','「우리 반 화분이 자꾸 시드는 문제를 어떻게 해결할까」에 대해 의견을 마련하는 차례에 따라 의견 · 이유 · 단점 · 고친 의견을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u2-C13","difficulty":4,"kind":"essay","stem":"「우리 반 화분이 자꾸 시드는 문제를 어떻게 해결할까」에 대해 의견을 마련하는 차례에 따라 의견 · 이유 · 단점 · 고친 의견을 쓰세요.","answer_guide":{"answer":"예: 의견 — 요일마다 물 주는 당번을 정하자. 이유 — 당번이 있으면 물 주는 것을 잊지 않기 때문이다. 단점 — 당번이 결석하면 물을 주지 못한다. 고친 의견 — 당번 다음 번호 친구가 함께 확인하자.","scoring_points":["주제에 알맞은 의견을 썼는가","실천했을 때 좋아지는 점을 이유로 썼는가","단점을 찾고 고친 의견을 썼는가"]},"explanation":["의견 → 이유","단점도 살펴요.","고쳐서 더 좋게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#1','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C16',1,'mc','auto','토의 절차에서 가장 먼저 하는 일은 무엇인가요?',ARRAY['K4-1-u2-X17']::text[],false,'{"seq":1,"concept":"K4-1-u2-C16","difficulty":1,"kind":"mc","stem":"토의 절차에서 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"토의 주제 정하기","correct":true},{"t":"의견 결정하기","mis":"K4-1-u2-X17"},{"t":"의견 모으기","mis":"K4-1-u2-X17"},{"t":"결정한 까닭 남기기","mis":"K4-1-u2-X17"}],"explanation":["무엇에 대해 말할지부터","주제가 있어야 의견이 나와요.","주제 정하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#2','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C19',1,'mc','auto','토의에서 사회자가 해야 할 일은 무엇인가요?',ARRAY['K4-1-u2-X19','K4-1-u2-X18','K4-1-u2-X20']::text[],false,'{"seq":2,"concept":"K4-1-u2-C19","difficulty":1,"kind":"mc","stem":"토의에서 사회자가 해야 할 일은 무엇인가요?","options":[{"t":"아직 말하지 않은 친구에게 말할 기회를 준다","correct":true},{"t":"자기 의견을 가장 좋은 의견으로 정해 버린다","mis":"K4-1-u2-X19"},{"t":"시간이 걸리니 의견 모으기를 건너뛴다","mis":"K4-1-u2-X18"},{"t":"말을 잘하는 친구에게만 말을 시킨다","mis":"K4-1-u2-X20"}],"explanation":["사회자는 이끄는 사람","기회를 고르게","말하지 않은 친구에게도"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#3','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C21',1,'mc','auto','바람직한 토의 태도는 무엇인가요?',ARRAY['K4-1-u2-X21','K4-1-u2-X22','K4-1-u2-X02']::text[],false,'{"seq":3,"concept":"K4-1-u2-C21","difficulty":1,"kind":"mc","stem":"바람직한 토의 태도는 무엇인가요?","options":[{"t":"나와 생각이 달라도 끝까지 듣는다","correct":true},{"t":"친구가 말하는 중간에 끼어들어 반박한다","mis":"K4-1-u2-X21"},{"t":"내 의견이 아니면 무조건 반대한다","mis":"K4-1-u2-X22"},{"t":"다른 의견이 나오면 말하지 않는다","mis":"K4-1-u2-X02"}],"explanation":["존중하며 들어요.","끝까지","다른 생각도 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#4','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C18',1,'mc','auto','「의견 결정하기」 단계에서 하는 일은 무엇인가요?',ARRAY['K4-1-u2-X17','K4-1-u2-X25']::text[],false,'{"seq":4,"concept":"K4-1-u2-C18","difficulty":1,"kind":"mc","stem":"「의견 결정하기」 단계에서 하는 일은 무엇인가요?","options":[{"t":"기준을 세워 가장 알맞은 의견을 고른다","correct":true},{"t":"함께 해결해야 할 일을 찾아 정한다","mis":"K4-1-u2-X17"},{"t":"차례로 말하고 친구의 의견을 정리한다","mis":"K4-1-u2-X17"},{"t":"가장 먼저 말한 의견을 그대로 정한다","mis":"K4-1-u2-X25"}],"explanation":["마지막 단계예요.","기준이 필요해요.","알맞은 의견을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#5','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C16',2,'match','auto','토의 절차의 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u2-C16","difficulty":2,"kind":"match","stem":"토의 절차의 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"토의 주제 정하기","r":"함께 해결해야 할 일을 찾아 정한다"},{"l":"의견 모으기","r":"차례로 말하고 친구의 의견을 정리한다"},{"l":"의견 결정하기","r":"기준을 세워 가장 알맞은 의견을 고른다"}],"mis":"K4-1-u2-X17","explanation":["처음 · 가운데 · 끝","모으고 나서 결정","차례를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#6','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C17',2,'mc','auto','서준이와 나윤이가 의견을 말한 단계는 토의 절차 가운데 어느 것인가요?',ARRAY['K4-1-u2-X17']::text[],false,'{"seq":6,"concept":"K4-1-u2-C17","difficulty":2,"kind":"mc","stem":"서준이와 나윤이가 의견을 말한 단계는 토의 절차 가운데 어느 것인가요?","options":[{"t":"의견 모으기","correct":true},{"t":"토의 주제 정하기","mis":"K4-1-u2-X17"},{"t":"의견 결정하기","mis":"K4-1-u2-X17"},{"t":"토의 되돌아보기","mis":"K4-1-u2-X17"}],"explanation":["두 사람이 차례로 말했어요.","아직 정하지 않았어요.","의견 모으기예요."],"asset":{"type":"speech","turns":[{"who":"주제","text":"학급 일인일역을 어떻게 정하면 좋을까"},{"who":"서준","text":"일인일역을 가장 열심히 한 친구를 뽑아 칭찬하면 좋겠습니다."},{"who":"서준","text":"왜냐하면 칭찬을 받으면 보람이 생겨 더 열심히 하기 때문입니다."},{"who":"나윤","text":"학급에 필요한 일을 적어 두고 신청을 받으면 좋겠습니다."},{"who":"나윤","text":"왜냐하면 모두가 스스로 고른 일을 맡을 수 있기 때문입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#7','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C22',2,'mc','auto','모은 의견이 알맞은지 판단할 때 살필 점이 아닌 것은 무엇인가요?',ARRAY['K4-1-u2-X24']::text[],false,'{"seq":7,"concept":"K4-1-u2-C22","difficulty":2,"kind":"mc","stem":"모은 의견이 알맞은지 판단할 때 살필 점이 아닌 것은 무엇인가요?","options":[{"t":"목소리가 큰 친구가 낸 의견인가요","correct":true},{"t":"토의 주제에 알맞은 의견인가요","mis":"K4-1-u2-X24"},{"t":"우리 모두가 실천할 수 있는 의견인가요","mis":"K4-1-u2-X24"},{"t":"의견을 뒷받침하는 이유가 알맞은가요","mis":"K4-1-u2-X24"}],"explanation":["누가 냈는지는?","의견의 내용을 봐요.","목소리는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#8','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C26',2,'mc','auto','의견을 결정할 때 알맞은 방법은 무엇인가요?',ARRAY['K4-1-u2-X25','K4-1-u2-X27','K4-1-u2-X26']::text[],false,'{"seq":8,"concept":"K4-1-u2-C26","difficulty":2,"kind":"mc","stem":"의견을 결정할 때 알맞은 방법은 무엇인가요?","options":[{"t":"좋은 의견을 합쳐 새로운 의견으로 정해도 된다","correct":true},{"t":"가장 먼저 말한 의견으로 정해야 한다","mis":"K4-1-u2-X25"},{"t":"까닭 없이 뽑기로 정해야 한다","mis":"K4-1-u2-X27"},{"t":"꼭 한 가지 의견만 골라야 한다","mis":"K4-1-u2-X26"}],"explanation":["하나만 골라야 할까요?","합칠 수도 있어요.","새 의견도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#9','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C25',2,'mc','auto','의견을 결정하는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X24','K4-1-u2-X25','K4-1-u2-X27']::text[],false,'{"seq":9,"concept":"K4-1-u2-C25","difficulty":2,"kind":"mc","stem":"의견을 결정하는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"단점보다 좋은 점이 더 큰가","correct":true},{"t":"의견을 낸 친구와 내가 친한가","mis":"K4-1-u2-X24"},{"t":"의견이 가장 먼저 나왔는가","mis":"K4-1-u2-X25"},{"t":"가위바위보에서 이긴 친구의 의견인가","mis":"K4-1-u2-X27"}],"explanation":["의견의 내용을 봐요.","좋은 점과 단점","견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_basic#10','kor',4,1,'u2','L04','g4_1_kor_u2_L04_basic','lesson_basic','K4-1-u2-C23',3,'mc','auto','나윤이의 의견이 알맞지 않다고 생각할 때 말하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X23','K4-1-u2-X21']::text[],false,'{"seq":10,"concept":"K4-1-u2-C23","difficulty":3,"kind":"mc","stem":"나윤이의 의견이 알맞지 않다고 생각할 때 말하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「신청한 일이 겹치면 어떻게 할지 정해야 할 것 같아요.」처럼 까닭을 들어 말한다","correct":true},{"t":"「그 의견은 별로예요.」라고만 말한다","mis":"K4-1-u2-X23"},{"t":"흠을 잡는 것 같으니 아무 말도 하지 않는다","mis":"K4-1-u2-X23"},{"t":"나윤이가 말하는 중간에 「아니에요!」라고 끼어든다","mis":"K4-1-u2-X21"}],"explanation":["알맞지 않다고 할 때","까닭도 함께","흠잡기가 아니에요."],"asset":{"type":"speech","turns":[{"who":"주제","text":"학급 일인일역을 어떻게 정하면 좋을까"},{"who":"서준","text":"일인일역을 가장 열심히 한 친구를 뽑아 칭찬하면 좋겠습니다."},{"who":"서준","text":"왜냐하면 칭찬을 받으면 보람이 생겨 더 열심히 하기 때문입니다."},{"who":"나윤","text":"학급에 필요한 일을 적어 두고 신청을 받으면 좋겠습니다."},{"who":"나윤","text":"왜냐하면 모두가 스스로 고른 일을 맡을 수 있기 때문입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#1','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C19',2,'mc','auto','「책꽂이 토의」에서 사회자 시온이가 한 일로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X19','K4-1-u2-X18','K4-1-u2-X21']::text[],false,'{"seq":1,"concept":"K4-1-u2-C19","difficulty":2,"kind":"mc","stem":"「책꽂이 토의」에서 사회자 시온이가 한 일로 알맞은 것은 무엇인가요?","options":[{"t":"아직 말하지 않은 친구도 차례대로 말하게 했다","correct":true},{"t":"자기 의견을 가장 좋은 의견으로 정했다","mis":"K4-1-u2-X19"},{"t":"유진이의 의견만 듣고 끝냈다","mis":"K4-1-u2-X18"},{"t":"말하는 중간에 끼어들어 반박했다","mis":"K4-1-u2-X21"}],"explanation":["마지막 말을 봐요.","차례대로 더 들어 보겠다고 했어요.","기회를 나누었어요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"오늘 주제는 「학급 책꽂이의 책이 자꾸 없어지는 문제를 어떻게 해결할까」입니다. 유진이부터 말해 주세요."},{"who":"유진","text":"빌려 가는 사람이 공책에 이름과 날짜를 적으면 좋겠습니다. 누가 가져갔는지 알 수 있기 때문입니다."},{"who":"지민","text":"책마다 반 이름 붙임딱지를 붙이면 좋겠습니다. 다른 반에 섞여도 찾아올 수 있기 때문입니다."},{"who":"예준","text":"책꽂이를 예쁘게 칠하면 좋겠습니다. 왜냐하면 저는 초록색을 좋아하기 때문입니다."},{"who":"시온","text":"아직 말하지 않은 친구도 있으니 차례대로 더 들어 보겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#2','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C16',2,'mc','auto','토의 절차를 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['K4-1-u2-X17']::text[],false,'{"seq":2,"concept":"K4-1-u2-C16","difficulty":2,"kind":"mc","stem":"토의 절차를 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"주제 정하기 → 의견 마련하기 → 의견 모으기 → 의견 결정하기","correct":true},{"t":"의견 결정하기 → 주제 정하기 → 의견 모으기 → 의견 마련하기","mis":"K4-1-u2-X17"},{"t":"의견 모으기 → 의견 마련하기 → 주제 정하기 → 의견 결정하기","mis":"K4-1-u2-X17"},{"t":"주제 정하기 → 의견 결정하기 → 의견 모으기 → 의견 마련하기","mis":"K4-1-u2-X17"}],"explanation":["주제가 먼저예요.","모아야 정할 수 있어요.","결정이 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#3','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C22',3,'mc','auto','「책꽂이 토의」에서 예준이의 의견이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-1-u2-X25','K4-1-u2-X24','K4-1-u2-X45']::text[],false,'{"seq":3,"concept":"K4-1-u2-C22","difficulty":3,"kind":"mc","stem":"「책꽂이 토의」에서 예준이의 의견이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"이유가 책이 없어지는 문제를 해결하는 것과 이어지지 않기 때문에","correct":true},{"t":"예준이가 가장 늦게 말했기 때문에","mis":"K4-1-u2-X25"},{"t":"예준이의 목소리가 작았기 때문에","mis":"K4-1-u2-X24"},{"t":"책꽂이를 칠하는 데 물감이 들기 때문에","mis":"K4-1-u2-X45"}],"explanation":["주제는 무엇인가요?","초록색을 좋아하는 것과 책이 없어지는 것","이어지지 않아요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"오늘 주제는 「학급 책꽂이의 책이 자꾸 없어지는 문제를 어떻게 해결할까」입니다. 유진이부터 말해 주세요."},{"who":"유진","text":"빌려 가는 사람이 공책에 이름과 날짜를 적으면 좋겠습니다. 누가 가져갔는지 알 수 있기 때문입니다."},{"who":"지민","text":"책마다 반 이름 붙임딱지를 붙이면 좋겠습니다. 다른 반에 섞여도 찾아올 수 있기 때문입니다."},{"who":"예준","text":"책꽂이를 예쁘게 칠하면 좋겠습니다. 왜냐하면 저는 초록색을 좋아하기 때문입니다."},{"who":"시온","text":"아직 말하지 않은 친구도 있으니 차례대로 더 들어 보겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#4','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C20',3,'mc','auto','사회자가 자기 의견을 가장 좋은 의견으로 정해 버리면 안 되는 까닭은 무엇인가요?',ARRAY['K4-1-u2-X19','K4-1-u2-X30','K4-1-u2-X03']::text[],false,'{"seq":4,"concept":"K4-1-u2-C20","difficulty":3,"kind":"mc","stem":"사회자가 자기 의견을 가장 좋은 의견으로 정해 버리면 안 되는 까닭은 무엇인가요?","options":[{"t":"사회자는 토의를 이끄는 사람이고 결정은 기준에 따라 함께 해야 하기 때문에","correct":true},{"t":"사회자는 의견이 없어야 하기 때문에","mis":"K4-1-u2-X19"},{"t":"사회자의 의견은 언제나 틀리기 때문에","mis":"K4-1-u2-X30"},{"t":"사회자가 정하면 가장 빨리 끝나기 때문에","mis":"K4-1-u2-X03"}],"explanation":["사회자의 몫은?","이끄는 사람","함께 기준으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#5','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C26',3,'mc','auto','「책꽂이 토의」에서 유진이와 지민이의 의견이 모두 좋다면 어떻게 정할 수 있나요?',ARRAY['K4-1-u2-X25','K4-1-u2-X26','K4-1-u2-X19']::text[],false,'{"seq":5,"concept":"K4-1-u2-C26","difficulty":3,"kind":"mc","stem":"「책꽂이 토의」에서 유진이와 지민이의 의견이 모두 좋다면 어떻게 정할 수 있나요?","options":[{"t":"공책에 빌린 사람을 적고 책마다 붙임딱지도 붙이자고 합친다","correct":true},{"t":"먼저 말한 유진이의 의견으로 정한다","mis":"K4-1-u2-X25"},{"t":"둘 가운데 하나만 골라야 하니 뽑기를 한다","mis":"K4-1-u2-X26"},{"t":"사회자 시온이가 좋아하는 쪽으로 정한다","mis":"K4-1-u2-X19"}],"explanation":["하나만 골라야 할까요?","둘을 합칠 수 있어요.","새 의견이에요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"오늘 주제는 「학급 책꽂이의 책이 자꾸 없어지는 문제를 어떻게 해결할까」입니다. 유진이부터 말해 주세요."},{"who":"유진","text":"빌려 가는 사람이 공책에 이름과 날짜를 적으면 좋겠습니다. 누가 가져갔는지 알 수 있기 때문입니다."},{"who":"지민","text":"책마다 반 이름 붙임딱지를 붙이면 좋겠습니다. 다른 반에 섞여도 찾아올 수 있기 때문입니다."},{"who":"예준","text":"책꽂이를 예쁘게 칠하면 좋겠습니다. 왜냐하면 저는 초록색을 좋아하기 때문입니다."},{"who":"시온","text":"아직 말하지 않은 친구도 있으니 차례대로 더 들어 보겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#6','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C24',3,'mc','auto','「반에서 가장 인기 있는 친구가 낸 의견이니까 좋은 의견이야.」라는 말에 대해 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u2-X24','K4-1-u2-X23','K4-1-u2-X25']::text[],false,'{"seq":6,"concept":"K4-1-u2-C24","difficulty":3,"kind":"mc","stem":"「반에서 가장 인기 있는 친구가 낸 의견이니까 좋은 의견이야.」라는 말에 대해 알맞은 생각은 무엇인가요?","options":[{"t":"누가 냈는지가 아니라 의견의 내용으로 판단해야 한다","correct":true},{"t":"인기 있는 친구의 의견은 언제나 알맞다","mis":"K4-1-u2-X24"},{"t":"인기 있는 친구의 의견이니 따져 보면 안 된다","mis":"K4-1-u2-X23"},{"t":"가장 먼저 낸 의견이 더 좋다","mis":"K4-1-u2-X25"}],"explanation":["누가 아니라 무엇을","내용을 살펴요.","주제 · 실천 · 이유 · 단점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#7','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C27',3,'mc','auto','토의를 마치고 스스로 되돌아볼 점으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u2-X05']::text[],false,'{"seq":7,"concept":"K4-1-u2-C27","difficulty":3,"kind":"mc","stem":"토의를 마치고 스스로 되돌아볼 점으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"내 의견이 이겼나요?","correct":true},{"t":"말차례를 지키며 토의에 참여했나요?","mis":"K4-1-u2-X05"},{"t":"친구들의 의견을 존중하며 들었나요?","mis":"K4-1-u2-X05"},{"t":"토의 주제에 알맞은 의견과 이유를 말했나요?","mis":"K4-1-u2-X05"}],"explanation":["토의는 이기기일까요?","함께 답을 찾아요.","이기기는 점검할 점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#8','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C25',4,'essay','teacher','「책꽂이 토의」에서 유진이와 지민이의 의견 가운데 하나를 고르고, 의견을 결정하는 기준(시간과 힘 · 모두 실천 · 좋은 점과 단점) 가운데 두 가지를 들어 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u2-C25","difficulty":4,"kind":"essay","stem":"「책꽂이 토의」에서 유진이와 지민이의 의견 가운데 하나를 고르고, 의견을 결정하는 기준(시간과 힘 · 모두 실천 · 좋은 점과 단점) 가운데 두 가지를 들어 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 유진이의 의견. 공책과 연필만 있으면 되어 시간과 힘이 많이 들지 않고, 빌릴 때 이름만 적으면 되니 모든 친구가 실천할 수 있다.","scoring_points":["한 의견을 골랐는가","결정 기준 두 가지를 들었는가","기준에 맞춰 까닭을 썼는가"]},"explanation":["하나를 골라요.","기준 두 가지","까닭을 써요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"오늘 주제는 「학급 책꽂이의 책이 자꾸 없어지는 문제를 어떻게 해결할까」입니다. 유진이부터 말해 주세요."},{"who":"유진","text":"빌려 가는 사람이 공책에 이름과 날짜를 적으면 좋겠습니다. 누가 가져갔는지 알 수 있기 때문입니다."},{"who":"지민","text":"책마다 반 이름 붙임딱지를 붙이면 좋겠습니다. 다른 반에 섞여도 찾아올 수 있기 때문입니다."},{"who":"예준","text":"책꽂이를 예쁘게 칠하면 좋겠습니다. 왜냐하면 저는 초록색을 좋아하기 때문입니다."},{"who":"시온","text":"아직 말하지 않은 친구도 있으니 차례대로 더 들어 보겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#9','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C21',4,'essay','teacher','토의에서 바람직한 태도 두 가지와 바람직하지 않은 태도 한 가지를 쓰고, 바람직하지 않은 태도가 토의를 어떻게 방해하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u2-C21","difficulty":4,"kind":"essay","stem":"토의에서 바람직한 태도 두 가지와 바람직하지 않은 태도 한 가지를 쓰고, 바람직하지 않은 태도가 토의를 어떻게 방해하는지 쓰세요.","answer_guide":{"answer":"예: 바람직한 태도 — 말할 기회를 얻어 차례를 지켜 말한다. 생각이 달라도 끝까지 듣는다. 바람직하지 않은 태도 — 말하는 중간에 끼어들어 반박한다. 끼어들면 친구가 의견을 끝까지 말하지 못해 좋은 의견을 놓칠 수 있다.","scoring_points":["바람직한 태도 두 가지를 썼는가","바람직하지 않은 태도를 썼는가","그 태도가 토의를 방해하는 까닭을 썼는가"]},"explanation":["차례 · 듣기 · 묻기","끼어들기 · 무조건 반대","좋은 의견을 놓쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L04_challenge#10','kor',4,1,'u2','L04','g4_1_kor_u2_L04_challenge','lesson_challenge','K4-1-u2-C18',4,'essay','teacher','「일인일역 토의」에서 서준이와 나윤이의 의견을 합쳐 새 의견을 만들고, 그 의견이 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u2-C18","difficulty":4,"kind":"essay","stem":"「일인일역 토의」에서 서준이와 나윤이의 의견을 합쳐 새 의견을 만들고, 그 의견이 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 필요한 일을 적어 두고 신청을 받아 일을 맡긴 뒤, 한 달에 한 번 열심히 한 친구를 칭찬하자. 스스로 고른 일을 맡으면서 칭찬으로 보람도 느낄 수 있기 때문이다.","scoring_points":["두 의견을 모두 담았는가","하나의 새 의견으로 썼는가","좋은 까닭을 썼는가"]},"explanation":["신청 + 칭찬","하나로 합쳐요.","두 좋은 점"],"asset":{"type":"speech","turns":[{"who":"주제","text":"학급 일인일역을 어떻게 정하면 좋을까"},{"who":"서준","text":"일인일역을 가장 열심히 한 친구를 뽑아 칭찬하면 좋겠습니다."},{"who":"서준","text":"왜냐하면 칭찬을 받으면 보람이 생겨 더 열심히 하기 때문입니다."},{"who":"나윤","text":"학급에 필요한 일을 적어 두고 신청을 받으면 좋겠습니다."},{"who":"나윤","text":"왜냐하면 모두가 스스로 고른 일을 맡을 수 있기 때문입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#1','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C28',1,'mc','auto','실제로 있었던 일이나 지금 있는 일을 무엇이라고 하나요?',ARRAY['K4-1-u2-X28','K4-1-u2-X12','K4-1-u2-X10']::text[],false,'{"seq":1,"concept":"K4-1-u2-C28","difficulty":1,"kind":"mc","stem":"실제로 있었던 일이나 지금 있는 일을 무엇이라고 하나요?","options":[{"t":"사실","correct":true},{"t":"의견","mis":"K4-1-u2-X28"},{"t":"이유","mis":"K4-1-u2-X12"},{"t":"주제","mis":"K4-1-u2-X10"}],"explanation":["있었던 일 · 있는 일","맞는지 따져 봐요.","사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#2','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C29',1,'mc','auto','「한번 산 물건을 오래 쓰는 버릇이 필요합니다.」는 사실과 의견 가운데 무엇인가요?',ARRAY['K4-1-u2-X28','K4-1-u2-X30']::text[],false,'{"seq":2,"concept":"K4-1-u2-C29","difficulty":1,"kind":"mc","stem":"「한번 산 물건을 오래 쓰는 버릇이 필요합니다.」는 사실과 의견 가운데 무엇인가요?","options":[{"t":"의견 — 글쓴이의 생각이 담겨 있다","correct":true},{"t":"사실 — 실제로 있었던 일이다","mis":"K4-1-u2-X28"},{"t":"사실도 의견도 아니다","mis":"K4-1-u2-X28"},{"t":"사실 — 맞는지 틀리는지 따질 수 있다","mis":"K4-1-u2-X30"}],"explanation":["「필요합니다」","글쓴이의 생각","의견이에요."],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#3','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C28',1,'mc','auto','「오래 쓸수록 좋아요」에서 사실을 나타낸 문장은 무엇인가요?',ARRAY['K4-1-u2-X29']::text[],false,'{"seq":3,"concept":"K4-1-u2-C28","difficulty":1,"kind":"mc","stem":"「오래 쓸수록 좋아요」에서 사실을 나타낸 문장은 무엇인가요?","options":[{"t":"② 물병이나 장바구니가 그러한 물건입니다.","correct":true},{"t":"⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다.","mis":"K4-1-u2-X29"},{"t":"⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","mis":"K4-1-u2-X29"},{"t":"없다 — 이 글은 모두 의견이다","mis":"K4-1-u2-X29"}],"explanation":["있는 것을 알려 주나요?","물병 · 장바구니","②예요."],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#4','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C31',1,'mc','auto','글쓴이의 의견을 찾을 때 알맞은 방법은 무엇인가요?',ARRAY['K4-1-u2-X32','K4-1-u2-X34']::text[],false,'{"seq":4,"concept":"K4-1-u2-C31","difficulty":1,"kind":"mc","stem":"글쓴이의 의견을 찾을 때 알맞은 방법은 무엇인가요?","options":[{"t":"되풀이되는 낱말과 제목을 함께 살핀다","correct":true},{"t":"글의 길이가 얼마나 긴지 센다","mis":"K4-1-u2-X32"},{"t":"가장 어려운 낱말 하나만 찾는다","mis":"K4-1-u2-X32"},{"t":"문장이 모두 몇 개인지 센다","mis":"K4-1-u2-X34"}],"explanation":["자꾸 나오는 말","제목에도 생각이","되풀이 · 제목"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#5','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C30',2,'match','auto','문장 끝말과 그 끝말이 주로 나타내는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u2-C30","difficulty":2,"kind":"match","stem":"문장 끝말과 그 끝말이 주로 나타내는 것을 알맞게 이으세요.","pairs":[{"l":"…해야 합니다","r":"해야 할 일에 대한 글쓴이의 생각(의견)"},{"l":"…이 있습니다","r":"있는 일을 알려 줌(사실)"},{"l":"…라고 생각합니다","r":"글쓴이가 가진 생각(의견)"}],"mis":"K4-1-u2-X31","explanation":["끝말을 봐요.","생각인가, 있는 일인가?","끝말이 열쇠예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#6','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C29',2,'mc','auto','사실과 의견을 따지는 방법을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X30','K4-1-u2-X07']::text[],false,'{"seq":6,"concept":"K4-1-u2-C29","difficulty":2,"kind":"mc","stem":"사실과 의견을 따지는 방법을 바르게 말한 것은 무엇인가요?","options":[{"t":"사실은 맞는지 따지고, 의견은 알맞은지 따진다","correct":true},{"t":"사실과 의견 모두 맞는지 틀리는지만 따진다","mis":"K4-1-u2-X30"},{"t":"의견은 따져 볼 필요가 없다","mis":"K4-1-u2-X07"},{"t":"사실은 따질 필요가 없고 의견만 따진다","mis":"K4-1-u2-X30"}],"explanation":["사실은 맞는지","의견은 알맞은지","따지는 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
