INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#8','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C31',2,'mc','auto','「오래 쓸수록 좋아요」에서 글쓴이의 생각을 알려 주는 되풀이 표현은 무엇인가요?',ARRAY['K4-1-u2-X32']::text[],false,'{"seq":8,"concept":"K4-1-u2-C31","difficulty":2,"kind":"mc","stem":"「오래 쓸수록 좋아요」에서 글쓴이의 생각을 알려 주는 되풀이 표현은 무엇인가요?","options":[{"t":"오래 쓰다","correct":true},{"t":"물병","mis":"K4-1-u2-X32"},{"t":"장바구니","mis":"K4-1-u2-X32"},{"t":"재료","mis":"K4-1-u2-X32"}],"explanation":["제목에도 있어요.","⑥ · ⑦에도 나와요.","「오래 쓰다」예요."],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#9','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C33',2,'mc','auto','글쓴이의 의견을 파악하면 좋은 점은 무엇인가요?',ARRAY['K4-1-u2-X34','K4-1-u2-X07']::text[],false,'{"seq":9,"concept":"K4-1-u2-C33","difficulty":2,"kind":"mc","stem":"글쓴이의 의견을 파악하면 좋은 점은 무엇인가요?","options":[{"t":"글쓴이의 의견과 내 의견을 비교하고 알맞은지 평가할 수 있다","correct":true},{"t":"글의 낱말을 모두 외울 수 있다","mis":"K4-1-u2-X34"},{"t":"글자 수를 빨리 셀 수 있다","mis":"K4-1-u2-X34"},{"t":"글쓴이의 의견을 그대로 따를 수 있다","mis":"K4-1-u2-X07"}],"explanation":["파악한 다음에는?","비교 · 평가","첫걸음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_basic#10','kor',4,1,'u2','L06','g4_1_kor_u2_L06_basic','lesson_basic','K4-1-u2-C32',3,'mc','auto','「쉬는 시간에는 창문을 열어 두어야 합니다. 교실 공기가 금방 탁해지기 때문입니다. 창문을 열면 맑은 공기가 들어옵니다.」에서 글쓴이의 의견은 어디에 있나요?',ARRAY['K4-1-u2-X33','K4-1-u2-X32','K4-1-u2-X28']::text[],false,'{"seq":10,"concept":"K4-1-u2-C32","difficulty":3,"kind":"mc","stem":"「쉬는 시간에는 창문을 열어 두어야 합니다. 교실 공기가 금방 탁해지기 때문입니다. 창문을 열면 맑은 공기가 들어옵니다.」에서 글쓴이의 의견은 어디에 있나요?","options":[{"t":"첫 문장","correct":true},{"t":"마지막 문장 — 의견은 언제나 마지막에 있다","mis":"K4-1-u2-X33"},{"t":"가운데 문장 — 가장 긴 문장이다","mis":"K4-1-u2-X32"},{"t":"없다 — 모두 사실이다","mis":"K4-1-u2-X28"}],"explanation":["「해야 합니다」가 어디 있나요?","첫 문장에도 의견이 와요.","첫 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#1','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C30',2,'mc','auto','다음 가운데 의견을 나타낸 문장은 무엇인가요?',ARRAY['K4-1-u2-X29']::text[],false,'{"seq":1,"concept":"K4-1-u2-C30","difficulty":2,"kind":"mc","stem":"다음 가운데 의견을 나타낸 문장은 무엇인가요?","options":[{"t":"우리 반 화분에 물을 더 자주 주어야 합니다.","correct":true},{"t":"우리 반 창가에는 화분이 세 개 있습니다.","mis":"K4-1-u2-X29"},{"t":"어제 화분에 물을 주었습니다.","mis":"K4-1-u2-X29"},{"t":"화분 하나에 새싹이 났습니다.","mis":"K4-1-u2-X29"}],"explanation":["「해야 합니다」","생각을 나타내요.","의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#2','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C28',2,'mc','auto','다음 가운데 사실을 나타낸 문장은 무엇인가요?',ARRAY['K4-1-u2-X28']::text[],false,'{"seq":2,"concept":"K4-1-u2-C28","difficulty":2,"kind":"mc","stem":"다음 가운데 사실을 나타낸 문장은 무엇인가요?","options":[{"t":"우리 학교 도서관은 오후 네 시에 문을 닫습니다.","correct":true},{"t":"도서관은 더 늦게까지 열어야 합니다.","mis":"K4-1-u2-X28"},{"t":"도서관이 가장 좋은 곳이라고 생각합니다.","mis":"K4-1-u2-X28"},{"t":"도서관에 책이 더 있었으면 좋겠습니다.","mis":"K4-1-u2-X28"}],"explanation":["있는 일을 알려 주나요?","확인할 수 있어요.","닫는 시간은 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#3','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C31',3,'mc','auto','「오래 쓸수록 좋아요」를 쓴 목적으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X06','K4-1-u2-X32']::text[],false,'{"seq":3,"concept":"K4-1-u2-C31","difficulty":3,"kind":"mc","stem":"「오래 쓸수록 좋아요」를 쓴 목적으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"한번 산 물건을 오래 쓰자고 권하려고","correct":true},{"t":"물병과 장바구니를 팔려고","mis":"K4-1-u2-X06"},{"t":"여러 번 쓰는 물건을 많이 사자고 권하려고","mis":"K4-1-u2-X06"},{"t":"환경이라는 낱말을 가르치려고","mis":"K4-1-u2-X32"}],"explanation":["⑦을 봐요.","무엇을 바라나요?","오래 쓰자예요."],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#4','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C34',3,'mc','auto','「오래 쓸수록 좋아요」의 내용과 맞는 것은 무엇인가요?',ARRAY['K4-1-u2-X06','K4-1-u2-X29']::text[],false,'{"seq":4,"concept":"K4-1-u2-C34","difficulty":3,"kind":"mc","stem":"「오래 쓸수록 좋아요」의 내용과 맞는 것은 무엇인가요?","options":[{"t":"여러 번 쓰는 물건도 한두 번만 쓰고 두면 환경을 지키는 힘이 크지 않다","correct":true},{"t":"여러 번 쓰는 물건은 언제나 환경을 지킨다","mis":"K4-1-u2-X06"},{"t":"여러 번 쓰는 물건은 만들 때 힘이 덜 든다","mis":"K4-1-u2-X29"},{"t":"물건은 여러 개 모을수록 좋다","mis":"K4-1-u2-X06"}],"explanation":["③ · ⑤ · ⑥","오래 써야 뜻이 있어요.","한두 번은 소용이 적어요."],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#5','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C32',3,'mc','auto','글쓴이의 의견을 찾는 방법을 바르게 말한 친구는 누구인가요?',ARRAY['K4-1-u2-X33','K4-1-u2-X32']::text[],false,'{"seq":5,"concept":"K4-1-u2-C32","difficulty":3,"kind":"mc","stem":"글쓴이의 의견을 찾는 방법을 바르게 말한 친구는 누구인가요?","options":[{"t":"하린 — 첫 문장이나 가운데에도 의견이 있을 수 있으니 글 전체를 살펴.","correct":true},{"t":"도윤 — 의견은 언제나 마지막 문장에 있으니 거기만 읽으면 돼.","mis":"K4-1-u2-X33"},{"t":"서준 — 가장 긴 문장이 글쓴이의 의견이야.","mis":"K4-1-u2-X32"},{"t":"나윤 — 어려운 낱말이 나온 문장이 의견이야.","mis":"K4-1-u2-X32"}],"explanation":["의견의 자리는?","정해져 있지 않아요.","글 전체를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#6','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C29',3,'mc','auto','「우리 반 화분이 세 개입니다.」와 「화분을 더 들여놓으면 좋겠습니다.」를 따지는 방법을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X30','K4-1-u2-X07','K4-1-u2-X29']::text[],false,'{"seq":6,"concept":"K4-1-u2-C29","difficulty":3,"kind":"mc","stem":"「우리 반 화분이 세 개입니다.」와 「화분을 더 들여놓으면 좋겠습니다.」를 따지는 방법을 바르게 말한 것은 무엇인가요?","options":[{"t":"앞 문장은 맞는지 세어 보고, 뒤 문장은 알맞은지 까닭을 따져 본다","correct":true},{"t":"두 문장 모두 맞는지 틀리는지만 따진다","mis":"K4-1-u2-X30"},{"t":"뒤 문장은 생각이니 따지지 않는다","mis":"K4-1-u2-X07"},{"t":"앞 문장은 생각이니 알맞은지 따진다","mis":"K4-1-u2-X29"}],"explanation":["앞은 사실 · 뒤는 의견","사실 → 맞는지","의견 → 알맞은지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#7','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C33',3,'mc','auto','「오래 쓸수록 좋아요」의 의견을 파악한 뒤 할 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X34','K4-1-u2-X07']::text[],false,'{"seq":7,"concept":"K4-1-u2-C33","difficulty":3,"kind":"mc","stem":"「오래 쓸수록 좋아요」의 의견을 파악한 뒤 할 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"나는 물건을 오래 쓰는지 견주어 보고, 그 의견이 알맞은지 따져 본다","correct":true},{"t":"글에 나온 물건 이름을 외운다","mis":"K4-1-u2-X34"},{"t":"글이 몇 줄인지 센다","mis":"K4-1-u2-X34"},{"t":"글쓴이가 말한 대로 물건을 더 산다","mis":"K4-1-u2-X07"}],"explanation":["파악 → 비교 → 평가","내 생활과 견주어요.","알맞은지 따져요."],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#8','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C30',4,'essay','teacher','「오래 쓸수록 좋아요」에서 사실 문장 하나와 의견 문장 하나를 골라 번호를 쓰고, 그렇게 가른 까닭을 문장 끝말을 들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u2-C30","difficulty":4,"kind":"essay","stem":"「오래 쓸수록 좋아요」에서 사실 문장 하나와 의견 문장 하나를 골라 번호를 쓰고, 그렇게 가른 까닭을 문장 끝말을 들어 쓰세요.","answer_guide":{"answer":"예: 사실 — ② 물병이나 장바구니가 그러한 물건입니다. 「…입니다」로 있는 것을 알려 준다. 의견 — ⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다. 「…필요합니다」로 글쓴이의 생각을 나타낸다.","scoring_points":["사실 문장을 바르게 골랐는가","의견 문장을 바르게 골랐는가","문장 끝말을 들어 까닭을 썼는가"]},"explanation":["있는 일 vs 생각","끝말을 봐요.","번호와 까닭"],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#9','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C31',4,'essay','teacher','「오래 쓸수록 좋아요」에서 글쓴이의 의견을 한 문장으로 쓰고, 그 의견을 찾는 데 도움이 된 방법 두 가지(중요한 문장 · 되풀이 표현 · 제목 · 목적)를 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u2-C31","difficulty":4,"kind":"essay","stem":"「오래 쓸수록 좋아요」에서 글쓴이의 의견을 한 문장으로 쓰고, 그 의견을 찾는 데 도움이 된 방법 두 가지(중요한 문장 · 되풀이 표현 · 제목 · 목적)를 들어 설명하세요.","answer_guide":{"answer":"예: 의견 — 한번 산 물건을 오래 쓰자. 제목 「오래 쓸수록 좋아요」에 생각이 담겨 있고, 「오래」라는 말이 ⑥과 ⑦에 되풀이되어 나오기 때문이다.","scoring_points":["글쓴이의 의견을 바르게 썼는가","찾는 방법 두 가지를 들었는가","방법을 글의 내용과 이어 설명했는가"]},"explanation":["의견 한 문장","제목 · 되풀이","글에서 찾아 설명"],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L06_challenge#10','kor',4,1,'u2','L06','g4_1_kor_u2_L06_challenge','lesson_challenge','K4-1-u2-C32',4,'essay','teacher','의견이 첫 문장에 오는 짧은 글을 세 문장으로 쓰고, 어느 문장이 의견인지 밝히세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u2-C32","difficulty":4,"kind":"essay","stem":"의견이 첫 문장에 오는 짧은 글을 세 문장으로 쓰고, 어느 문장이 의견인지 밝히세요.","answer_guide":{"answer":"예: 계단에서는 한 칸씩 걸어야 합니다. 두 칸씩 뛰면 발을 헛디딜 수 있습니다. 지난주에도 한 친구가 계단에서 넘어졌습니다. — 의견은 첫 문장 「계단에서는 한 칸씩 걸어야 합니다」이다.","scoring_points":["세 문장으로 썼는가","첫 문장에 의견을 썼는가","어느 문장이 의견인지 밝혔는가"]},"explanation":["첫 문장에 생각을","뒤에 까닭과 있는 일","의견을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#1','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C35',1,'mc','auto','「마을에 밥집을 만들어요」에서 글쓴이의 의견은 무엇인가요?',ARRAY['K4-1-u2-X06']::text[],false,'{"seq":1,"concept":"K4-1-u2-C35","difficulty":1,"kind":"mc","stem":"「마을에 밥집을 만들어요」에서 글쓴이의 의견은 무엇인가요?","options":[{"t":"마을에 고양이 밥집을 만들자","correct":true},{"t":"고양이를 모두 집에서 기르자","mis":"K4-1-u2-X06"},{"t":"쓰레기봉투를 두 겹으로 묶자","mis":"K4-1-u2-X06"},{"t":"골목에서 고양이를 쫓아내자","mis":"K4-1-u2-X06"}],"explanation":["③ · ⑦을 봐요.","무엇을 만들자고 했나요?","고양이 밥집이에요."],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#2','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C36',1,'mc','auto','글쓴이의 의견을 뒷받침하는 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X35']::text[],false,'{"seq":2,"concept":"K4-1-u2-C36","difficulty":1,"kind":"mc","stem":"글쓴이의 의견을 뒷받침하는 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어든다","correct":true},{"t":"골목에는 가로등이 많이 서 있다","mis":"K4-1-u2-X35"},{"t":"고양이는 털 색깔이 여러 가지이다","mis":"K4-1-u2-X35"},{"t":"우리 마을에는 가게가 많다","mis":"K4-1-u2-X35"}],"explanation":["왜 밥집을 만들자는 걸까?","그 물음에 답해요.","④예요."],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#3','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C38',1,'mc','auto','글쓴이와 다른 의견은 무엇인가요?',ARRAY['K4-1-u2-X36']::text[],false,'{"seq":3,"concept":"K4-1-u2-C38","difficulty":1,"kind":"mc","stem":"글쓴이와 다른 의견은 무엇인가요?","options":[{"t":"치울 사람이 없으면 밥집을 두지 않는 편이 낫다","correct":true},{"t":"밥집을 두면 쓰레기를 헤집는 일이 줄어든다","mis":"K4-1-u2-X36"},{"t":"밥집이 있으면 아픈 고양이를 빨리 찾는다","mis":"K4-1-u2-X36"},{"t":"사람과 동물이 함께 살아가는 마을이 좋다","mis":"K4-1-u2-X36"}],"explanation":["글쓴이는 밥집을 만들자고 했어요.","어긋나는 말을 찾아요.","두지 말자예요."],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#4','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C41',1,'mc','auto','글쓴이의 의견과 내 의견을 비교하면 좋은 점은 무엇인가요?',ARRAY['K4-1-u2-X39','K4-1-u2-X07']::text[],false,'{"seq":4,"concept":"K4-1-u2-C41","difficulty":1,"kind":"mc","stem":"글쓴이의 의견과 내 의견을 비교하면 좋은 점은 무엇인가요?","options":[{"t":"글에 대한 내 생각을 또렷하게 알 수 있다","correct":true},{"t":"글쓴이가 틀렸다고 말할 수 있다","mis":"K4-1-u2-X39"},{"t":"글쓴이를 이길 수 있다","mis":"K4-1-u2-X39"},{"t":"글을 읽지 않아도 된다","mis":"K4-1-u2-X07"}],"explanation":["비교는 이기기일까요?","내 생각이 또렷해져요.","깊이 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#5','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C36',2,'match','auto','글쓴이의 의견과 그것을 뒷받침하는 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u2-C36","difficulty":2,"kind":"match","stem":"글쓴이의 의견과 그것을 뒷받침하는 내용을 알맞게 이으세요.","pairs":[{"l":"정해진 곳에 밥집을 두자","r":"쓰레기를 헤집는 일이 줄어든다"},{"l":"밥집으로 고양이가 모이게 하자","r":"아픈 고양이를 일찍 찾아 돌볼 수 있다"},{"l":"함께 사는 마을을 만들자","r":"동물도 배고픔과 아픔을 느끼는 생명이다"}],"mis":"K4-1-u2-X35","explanation":["왜 그렇게 하자는지","짝을 찾아요.","받침돌이에요."],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#6','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C37',2,'mc','auto','의견에 뒷받침 내용이 필요한 까닭은 무엇인가요?',ARRAY['K4-1-u2-X46','K4-1-u2-X32','K4-1-u2-X06']::text[],false,'{"seq":6,"concept":"K4-1-u2-C37","difficulty":2,"kind":"mc","stem":"의견에 뒷받침 내용이 필요한 까닭은 무엇인가요?","options":[{"t":"읽는 사람이 그 의견이 왜 필요한지 받아들일 수 있기 때문에","correct":true},{"t":"글을 더 길게 쓸 수 있기 때문에","mis":"K4-1-u2-X46"},{"t":"어려운 낱말을 쓸 수 있기 때문에","mis":"K4-1-u2-X32"},{"t":"의견을 숨길 수 있기 때문에","mis":"K4-1-u2-X06"}],"explanation":["의견만 있으면?","흔들려요.","고개를 끄덕이게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#7','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C39',2,'mc','auto','「마을에 밥집을 만들어요」와 유진이의 말을 견주었어요. 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X37','K4-1-u2-X39']::text[],false,'{"seq":7,"concept":"K4-1-u2-C39","difficulty":2,"kind":"mc","stem":"「마을에 밥집을 만들어요」와 유진이의 말을 견주었어요. 알맞은 것은 무엇인가요?","options":[{"t":"같은 점과 다른 점이 함께 있다","correct":true},{"t":"같은 점만 있다","mis":"K4-1-u2-X37"},{"t":"다른 점만 있다","mis":"K4-1-u2-X37"},{"t":"둘은 견줄 수 없다","mis":"K4-1-u2-X39"}],"explanation":["둘 다 고양이를 돌보려 해요.","방법은 조금 달라요.","함께 나와요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"밥집 둘레에 고양이가 모여 밤에 시끄러울 수 있어요."},{"who":"지민","text":"밥그릇을 치울 사람이 없으면 오히려 지저분해져요."},{"who":"유진","text":"돌볼 사람을 정하고 자리를 잘 고르면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#8','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C40',2,'mc','auto','두 의견을 비교하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X38','K4-1-u2-X46','K4-1-u2-X25']::text[],false,'{"seq":8,"concept":"K4-1-u2-C40","difficulty":2,"kind":"mc","stem":"두 의견을 비교하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"무엇이 왜 같고 다른지 뒷받침 내용까지 견준다","correct":true},{"t":"같다 · 다르다 한마디로 끝낸다","mis":"K4-1-u2-X38"},{"t":"글이 더 긴 쪽이 맞다고 정한다","mis":"K4-1-u2-X46"},{"t":"먼저 쓴 글이 맞다고 정한다","mis":"K4-1-u2-X25"}],"explanation":["한마디로 끝내면?","왜 같고 다른가요?","뒷받침까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
