INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_basic#10','kor',4,1,'u2','L07','g4_1_kor_u2_L07_basic','lesson_basic','K4-1-u2-C38',3,'mc','auto','예준이의 말 「밥집 둘레에 고양이가 모여 밤에 시끄러울 수 있어요.」는 글쓴이의 의견과 어떤 관계인가요?',ARRAY['K4-1-u2-X36','K4-1-u2-X35','K4-1-u2-X39']::text[],false,'{"seq":10,"concept":"K4-1-u2-C38","difficulty":3,"kind":"mc","stem":"예준이의 말 「밥집 둘레에 고양이가 모여 밤에 시끄러울 수 있어요.」는 글쓴이의 의견과 어떤 관계인가요?","options":[{"t":"밥집을 두면 생길 걱정을 말해 글쓴이와 다르게 본다","correct":true},{"t":"글쓴이의 뒷받침을 되풀이해 같은 생각을 말한다","mis":"K4-1-u2-X36"},{"t":"글쓴이와 아무 상관 없는 말이다","mis":"K4-1-u2-X35"},{"t":"글쓴이가 틀렸다고 이긴 말이다","mis":"K4-1-u2-X39"}],"explanation":["밥집을 두면 어떻게 된다고 했나요?","걱정을 말했어요.","다르게 본 거예요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"밥집 둘레에 고양이가 모여 밤에 시끄러울 수 있어요."},{"who":"지민","text":"밥그릇을 치울 사람이 없으면 오히려 지저분해져요."},{"who":"유진","text":"돌볼 사람을 정하고 자리를 잘 고르면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#1','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C36',2,'mc','auto','「마을에 밥집을 만들어요」에서 뒷받침 내용이 아닌 문장은 무엇인가요?',ARRAY['K4-1-u2-X35']::text[],false,'{"seq":1,"concept":"K4-1-u2-C36","difficulty":2,"kind":"mc","stem":"「마을에 밥집을 만들어요」에서 뒷받침 내용이 아닌 문장은 무엇인가요?","options":[{"t":"① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","correct":true},{"t":"④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","mis":"K4-1-u2-X35"},{"t":"⑤ 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","mis":"K4-1-u2-X35"},{"t":"⑥ 동물도 배고픔과 아픔을 느끼는 생명입니다.","mis":"K4-1-u2-X35"}],"explanation":["「왜 하자는 걸까?」에 답하나요?","①은 상황을 알려 줘요.","뒷받침이 아니에요."],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#2','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C35',2,'mc','auto','「마을에 밥집을 만들어요」에서 의견이 담긴 문장을 모두 고른 것은 무엇인가요?',ARRAY['K4-1-u2-X29','K4-1-u2-X36','K4-1-u2-X28']::text[],false,'{"seq":2,"concept":"K4-1-u2-C35","difficulty":2,"kind":"mc","stem":"「마을에 밥집을 만들어요」에서 의견이 담긴 문장을 모두 고른 것은 무엇인가요?","options":[{"t":"③ · ⑦","correct":true},{"t":"① · ②","mis":"K4-1-u2-X29"},{"t":"④ · ⑤","mis":"K4-1-u2-X36"},{"t":"⑥만","mis":"K4-1-u2-X28"}],"explanation":["「좋겠습니다」를 찾아요.","두 번 나와요.","③과 ⑦이에요."],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#3','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C40',3,'mc','auto','글쓴이와 지민이의 생각을 뒷받침까지 견준 것은 무엇인가요?',ARRAY['K4-1-u2-X38','K4-1-u2-X39']::text[],false,'{"seq":3,"concept":"K4-1-u2-C40","difficulty":3,"kind":"mc","stem":"글쓴이와 지민이의 생각을 뒷받침까지 견준 것은 무엇인가요?","options":[{"t":"글쓴이는 밥집이 쓰레기를 줄인다고 보지만, 지민이는 치울 사람이 없으면 오히려 지저분해진다고 본다","correct":true},{"t":"글쓴이와 지민이는 생각이 다르다","mis":"K4-1-u2-X38"},{"t":"둘 다 고양이 이야기를 했으니 같다","mis":"K4-1-u2-X38"},{"t":"지민이가 글쓴이를 이겼다","mis":"K4-1-u2-X39"}],"explanation":["무엇이 다른가요?","쓰레기에 대한 눈이 달라요.","까닭까지 견줘요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"밥집 둘레에 고양이가 모여 밤에 시끄러울 수 있어요."},{"who":"지민","text":"밥그릇을 치울 사람이 없으면 오히려 지저분해져요."},{"who":"유진","text":"돌볼 사람을 정하고 자리를 잘 고르면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#4','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C39',3,'mc','auto','글쓴이와 유진이의 생각에서 같은 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X47','K4-1-u2-X06','K4-1-u2-X37']::text[],false,'{"seq":4,"concept":"K4-1-u2-C39","difficulty":3,"kind":"mc","stem":"글쓴이와 유진이의 생각에서 같은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"고양이를 돌보는 방법을 마련하자고 본다","correct":true},{"t":"밥집은 절대 두면 안 된다고 본다","mis":"K4-1-u2-X47"},{"t":"고양이는 시끄러우니 쫓아내자고 본다","mis":"K4-1-u2-X06"},{"t":"같은 점은 하나도 없다","mis":"K4-1-u2-X37"}],"explanation":["유진이도 돌볼 방법을 말했어요.","자리와 사람을 정하자고 했어요.","돌보자는 점이 같아요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"밥집 둘레에 고양이가 모여 밤에 시끄러울 수 있어요."},{"who":"지민","text":"밥그릇을 치울 사람이 없으면 오히려 지저분해져요."},{"who":"유진","text":"돌볼 사람을 정하고 자리를 잘 고르면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#5','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C41',3,'mc','auto','친구가 「글쓴이랑 생각이 다르니까 글쓴이가 틀렸어.」라고 말했어요. 알맞은 대답은 무엇인가요?',ARRAY['K4-1-u2-X39','K4-1-u2-X07','K4-1-u2-X38']::text[],false,'{"seq":5,"concept":"K4-1-u2-C41","difficulty":3,"kind":"mc","stem":"친구가 「글쓴이랑 생각이 다르니까 글쓴이가 틀렸어.」라고 말했어요. 알맞은 대답은 무엇인가요?","options":[{"t":"생각이 다른 것은 틀린 것이 아니야. 왜 다르게 보는지 견주어 보자.","correct":true},{"t":"맞아. 다르면 틀린 거야.","mis":"K4-1-u2-X39"},{"t":"글쓴이 생각을 그대로 따르면 돼.","mis":"K4-1-u2-X07"},{"t":"비교는 할 필요가 없어.","mis":"K4-1-u2-X38"}],"explanation":["다름 = 틀림일까요?","비교는 이기기가 아니에요.","왜 다른지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#6','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C42',3,'mc','auto','「밥집을 두자」에 찬성하는 내 의견을 바르게 세운 것은 무엇인가요?',ARRAY['K4-1-u2-X40','K4-1-u2-X12','K4-1-u2-X07']::text[],false,'{"seq":6,"concept":"K4-1-u2-C42","difficulty":3,"kind":"mc","stem":"「밥집을 두자」에 찬성하는 내 의견을 바르게 세운 것은 무엇인가요?","options":[{"t":"밥집에 찬성해. 정해진 곳에서 먹으면 골목이 깨끗해지기 때문이야.","correct":true},{"t":"밥집에 찬성해.","mis":"K4-1-u2-X40"},{"t":"밥집에 찬성해. 왜냐하면 나는 고양이 그림을 좋아하기 때문이야.","mis":"K4-1-u2-X12"},{"t":"글쓴이가 그렇게 말했으니까 찬성해.","mis":"K4-1-u2-X07"}],"explanation":["의견 + 뒷받침","이어지는 까닭","골목이 깨끗해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#7','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C37',3,'mc','auto','「마을에 밥집을 만들어요」에서 ④ · ⑤ · ⑥이 모두 빠진다면 어떻게 될까요?',ARRAY['K4-1-u2-X37','K4-1-u2-X46','K4-1-u2-X35']::text[],false,'{"seq":7,"concept":"K4-1-u2-C37","difficulty":3,"kind":"mc","stem":"「마을에 밥집을 만들어요」에서 ④ · ⑤ · ⑥이 모두 빠진다면 어떻게 될까요?","options":[{"t":"읽는 사람이 왜 밥집이 필요한지 알기 어렵다","correct":true},{"t":"글쓴이의 의견이 더 또렷해진다","mis":"K4-1-u2-X37"},{"t":"글이 짧아져서 더 믿을 만해진다","mis":"K4-1-u2-X46"},{"t":"아무 차이가 없다","mis":"K4-1-u2-X35"}],"explanation":["④ · ⑤ · ⑥은 무엇이었나요?","뒷받침이에요.","빠지면 흔들려요."],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#8','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C40',4,'essay','teacher','글쓴이와 예준이 · 지민이의 생각을 견주어 같은 점 한 가지와 다른 점 한 가지를 쓰고, 다른 점은 무엇 때문에 생기는지 뒷받침 내용을 들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u2-C40","difficulty":4,"kind":"essay","stem":"글쓴이와 예준이 · 지민이의 생각을 견주어 같은 점 한 가지와 다른 점 한 가지를 쓰고, 다른 점은 무엇 때문에 생기는지 뒷받침 내용을 들어 쓰세요.","answer_guide":{"answer":"예: 같은 점 — 모두 마을의 고양이와 골목을 걱정한다. 다른 점 — 글쓴이는 밥집을 두면 쓰레기를 헤집는 일이 줄어든다고 보지만, 지민이는 치울 사람이 없으면 오히려 지저분해진다고 본다. 밥집이 골목을 깨끗하게 할지 더럽힐지를 다르게 보았기 때문이다.","scoring_points":["같은 점을 썼는가","다른 점을 썼는가","다른 까닭을 뒷받침 내용을 들어 썼는가"]},"explanation":["같은 점","다른 점","뒷받침까지"],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#9','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C42',4,'essay','teacher','「마을에 밥집을 만들어요」에 대한 내 의견(찬성 · 반대 · 고쳐서 찬성)을 쓰고, 뒷받침 내용 두 가지를 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u2-C42","difficulty":4,"kind":"essay","stem":"「마을에 밥집을 만들어요」에 대한 내 의견(찬성 · 반대 · 고쳐서 찬성)을 쓰고, 뒷받침 내용 두 가지를 들어 쓰세요.","answer_guide":{"answer":"예: 고쳐서 찬성한다. 돌볼 사람을 정하면 밥그릇이 치워져 골목이 지저분해지지 않는다. 또 밥집을 집에서 떨어진 곳에 두면 밤에 시끄러운 문제도 줄일 수 있다.","scoring_points":["내 의견을 분명히 썼는가","뒷받침 내용 두 가지를 썼는가","뒷받침이 의견과 이어지는가"]},"explanation":["내 의견","뒷받침 둘","이어지게"],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L07_challenge#10','kor',4,1,'u2','L07','g4_1_kor_u2_L07_challenge','lesson_challenge','K4-1-u2-C41',4,'essay','teacher','글쓴이의 의견과 내 의견을 비교하면 좋은 점 두 가지를 쓰고, 「비교는 글쓴이를 이기려고 하는 것이다」라는 말이 알맞지 않은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u2-C41","difficulty":4,"kind":"essay","stem":"글쓴이의 의견과 내 의견을 비교하면 좋은 점 두 가지를 쓰고, 「비교는 글쓴이를 이기려고 하는 것이다」라는 말이 알맞지 않은 까닭을 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 글의 내용을 더 깊이 이해할 수 있다. 글에 대한 내 생각을 또렷하게 알 수 있다. 비교는 누가 이기는지 가리는 일이 아니라 같은 점과 다른 점을 따져 더 깊이 읽는 방법이기 때문이다.","scoring_points":["좋은 점 두 가지를 썼는가","이기려는 것이 아니라고 썼는가","비교의 쓸모를 까닭으로 들었는가"]},"explanation":["깊이 · 또렷이","이기기?","따져 읽는 방법"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#1','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C43',1,'mc','auto','「당나귀를 팔러 간 아버지와 아들」에서 당나귀를 물에 빠뜨린 까닭은 무엇인가요?',ARRAY['K4-1-u2-X41']::text[],false,'{"seq":1,"concept":"K4-1-u2-C43","difficulty":1,"kind":"mc","stem":"「당나귀를 팔러 간 아버지와 아들」에서 당나귀를 물에 빠뜨린 까닭은 무엇인가요?","options":[{"t":"남의 의견이 알맞은지 따져 보지 않고 그대로 따랐기 때문에","correct":true},{"t":"다리가 너무 좁았기 때문에","mis":"K4-1-u2-X41"},{"t":"당나귀가 힘이 세지 않았기 때문에","mis":"K4-1-u2-X41"},{"t":"장이 너무 멀었기 때문에","mis":"K4-1-u2-X41"}],"explanation":["③을 봐요.","말을 들을 때마다 어떻게 했나요?","따져 보지 않았어요."],"asset":{"type":"passage","lines":["① 아버지와 아들이 당나귀를 끌고 장으로 가고 있었다.","② \"당나귀를 두고 걸어가다니 어리석구나.\" 지나가던 사람이 말했다.","③ 말을 들을 때마다 둘은 타고, 바꾸어 타고, 함께 타기를 되풀이했다.","④ 끝내 당나귀를 메고 다리를 건너다 당나귀를 물에 빠뜨렸다."],"title":"당나귀를 팔러 간 아버지와 아들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#2','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C44',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-1-u2-C44","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"개방","r":"드나들고 쓸 수 있게 여는 것"},{"l":"보존","r":"잘 보살펴 그대로 남기는 것"},{"l":"훼손","r":"헐거나 상하게 해서 못 쓰게 만드는 것"}],"mis":"K4-1-u2-X42","explanation":["열기","지키기","망가뜨리기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#3','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C49',1,'mc','auto','「㉯ 준비한 뒤에 열어요」에서 글쓴이의 의견은 무엇인가요?',ARRAY['K4-1-u2-X47','K4-1-u2-X06']::text[],false,'{"seq":3,"concept":"K4-1-u2-C49","difficulty":1,"kind":"mc","stem":"「㉯ 준비한 뒤에 열어요」에서 글쓴이의 의견은 무엇인가요?","options":[{"t":"날과 시간을 정하고 살필 사람을 둔 뒤에 열자","correct":true},{"t":"운동장을 영원히 잠가 두자","mis":"K4-1-u2-X47"},{"t":"운동장을 없애고 다른 건물을 세우자","mis":"K4-1-u2-X47"},{"t":"주말마다 아무 때나 열자","mis":"K4-1-u2-X06"}],"explanation":["④를 다시 읽어요.","무엇을 갖춘 뒤에?","준비한 뒤 열자예요."],"asset":{"type":"passage","lines":["① 주말에 학교 운동장을 함부로 열면 안 됩니다.","② 사람이 많이 드나들면 시설이 상하거나 쓰레기가 늘어납니다.","③ 한번 망가진 시설을 되돌리는 데에는 많은 시간과 힘이 듭니다.","④ 여는 날과 시간을 정하고 살필 사람을 둔 뒤에 열어야 합니다."],"title":"㉯ 준비한 뒤에 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#4','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C45',1,'mc','auto','의견을 평가할 때 살필 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X46','K4-1-u2-X32']::text[],false,'{"seq":4,"concept":"K4-1-u2-C45","difficulty":1,"kind":"mc","stem":"의견을 평가할 때 살필 점으로 알맞은 것은 무엇인가요?","options":[{"t":"뒷받침하는 내용이 의견과 이어지는가","correct":true},{"t":"글이 얼마나 길게 쓰였는가","mis":"K4-1-u2-X46"},{"t":"글쓴이가 나와 친한 사이인가","mis":"K4-1-u2-X46"},{"t":"글에 어려운 낱말이 몇 개 있는가","mis":"K4-1-u2-X32"}],"explanation":["의견과 뒷받침","이어지나요?","평가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#5','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C46',2,'mc','auto','「㉰ 먹을 만큼 받아요」에서 믿기 어려운 뒷받침 내용은 무엇인가요?',ARRAY['K4-1-u2-X44']::text[],false,'{"seq":5,"concept":"K4-1-u2-C46","difficulty":2,"kind":"mc","stem":"「㉰ 먹을 만큼 받아요」에서 믿기 어려운 뒷받침 내용은 무엇인가요?","options":[{"t":"④ 누가 그러는데 남긴 음식은 모두 바다에 버린다고 합니다.","correct":true},{"t":"② 다 먹지 못하고 남긴 음식은 모두 버려집니다.","mis":"K4-1-u2-X44"},{"t":"③ 받은 만큼 다 먹으면 뿌듯함도 생깁니다.","mis":"K4-1-u2-X44"},{"t":"⑤ 모자라면 더 받으러 가면 됩니다.","mis":"K4-1-u2-X44"}],"explanation":["「누가 그러는데」","확인할 수 있나요?","소문이에요."],"asset":{"type":"passage","lines":["① 급식은 먹을 만큼만 받았으면 좋겠습니다.","② 다 먹지 못하고 남긴 음식은 모두 버려집니다.","③ 받은 만큼 다 먹으면 스스로 해냈다는 뿌듯함도 생깁니다.","④ 누가 그러는데 남긴 음식은 모두 바다에 버린다고 합니다.","⑤ 처음에는 조금 받고, 모자라면 더 받으러 가면 됩니다."],"title":"㉰ 먹을 만큼 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#6','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C47',2,'mc','auto','「주말에 운동장을 열자」는 의견을 평가할 때 「그대로 했을 때 다른 문제가 생기지 않는가」를 살피면 떠올릴 문제는 무엇인가요?',ARRAY['K4-1-u2-X45','K4-1-u2-X46']::text[],false,'{"seq":6,"concept":"K4-1-u2-C47","difficulty":2,"kind":"mc","stem":"「주말에 운동장을 열자」는 의견을 평가할 때 「그대로 했을 때 다른 문제가 생기지 않는가」를 살피면 떠올릴 문제는 무엇인가요?","options":[{"t":"시설이 상하거나 쓰레기가 늘어날 수 있다","correct":true},{"t":"운동장이 넓어서 좋다","mis":"K4-1-u2-X45"},{"t":"글쓴이가 운동을 좋아한다","mis":"K4-1-u2-X46"},{"t":"글이 여섯 문장이다","mis":"K4-1-u2-X46"}],"explanation":["열면 생길 일","다른 문제","시설과 쓰레기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#7','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C50',2,'match','auto','사람이 드나드는 일을 두 글은 어떻게 보았는지 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-1-u2-C50","difficulty":2,"kind":"match","stem":"사람이 드나드는 일을 두 글은 어떻게 보았는지 알맞게 이으세요.","pairs":[{"l":"㉮ 열자는 글","r":"눈길이 닿아 오히려 잘 살펴진다"},{"l":"㉯ 준비한 뒤 열자는 글","r":"시설이 상하고 쓰레기가 늘어날 수 있다"},{"l":"두 글 모두","r":"마을 사람들이 운동장을 쓰는 일을 다룬다"}],"mis":"K4-1-u2-X48","explanation":["같은 일, 다른 눈","㉮ ④ · ㉯ ②","평가가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#8','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C45',2,'mc','auto','「㉮ 주말에는 운동장을 열어요」에서 「② 마을에는 마음 놓고 뛸 만한 넓은 터가 없습니다.」가 알맞은 뒷받침인 까닭은 무엇인가요?',ARRAY['K4-1-u2-X46','K4-1-u2-X33','K4-1-u2-X32']::text[],false,'{"seq":8,"concept":"K4-1-u2-C45","difficulty":2,"kind":"mc","stem":"「㉮ 주말에는 운동장을 열어요」에서 「② 마을에는 마음 놓고 뛸 만한 넓은 터가 없습니다.」가 알맞은 뒷받침인 까닭은 무엇인가요?","options":[{"t":"운동장을 열어야 하는 까닭과 이어지기 때문에","correct":true},{"t":"문장이 짧기 때문에","mis":"K4-1-u2-X46"},{"t":"글의 두 번째 문장이기 때문에","mis":"K4-1-u2-X33"},{"t":"어려운 낱말이 없기 때문에","mis":"K4-1-u2-X32"}],"explanation":["열면 무엇이 생기나요?","뛸 곳이 생겨요.","의견과 이어져요."],"asset":{"type":"passage","lines":["① 주말에도 학교 운동장을 마을 사람들에게 열었으면 좋겠습니다.","② 우리 마을에는 아이들이 마음 놓고 뛸 만한 넓은 터가 없습니다.","③ 운동장을 열면 마을 사람들이 함께 운동할 곳이 생깁니다.","④ 사람이 자주 드나드는 곳은 오히려 눈길이 닿아 잘 살펴집니다.","⑤ 직접 써 본 곳에는 남다른 정이 들어 아끼는 사람이 늘어납니다.","⑥ 운동장을 여는 일은 학교와 마을이 함께 사는 길입니다."],"title":"㉮ 주말에는 운동장을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#9','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C48',2,'mc','auto','의견을 평가할 때 기준이 될 수 없는 것은 무엇인가요?',ARRAY['K4-1-u2-X46']::text[],false,'{"seq":9,"concept":"K4-1-u2-C48","difficulty":2,"kind":"mc","stem":"의견을 평가할 때 기준이 될 수 없는 것은 무엇인가요?","options":[{"t":"글쓴이가 나와 친한 사이인가","correct":true},{"t":"뒷받침하는 내용을 믿을 수 있는가","mis":"K4-1-u2-X46"},{"t":"그대로 했을 때 다른 문제가 생기지 않는가","mis":"K4-1-u2-X46"},{"t":"뒷받침하는 내용이 의견과 이어지는가","mis":"K4-1-u2-X46"}],"explanation":["세 기준을 떠올려요.","친한 정도는?","상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_basic#10','kor',4,1,'u2','L09','g4_1_kor_u2_L09_basic','lesson_basic','K4-1-u2-C50',3,'mc','auto','㉮와 ㉯를 읽고 평가한 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X48','K4-1-u2-X46']::text[],false,'{"seq":10,"concept":"K4-1-u2-C50","difficulty":3,"kind":"mc","stem":"㉮와 ㉯를 읽고 평가한 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사람이 드나드는 일을 다르게 보아 평가가 다를 수 있지만, 나는 시설을 지킬 방법이 있으면 여는 쪽이 낫다고 본다","correct":true},{"t":"두 글 가운데 하나는 반드시 틀렸으니 정답을 찾아야 한다","mis":"K4-1-u2-X48"},{"t":"둘 다 그럴듯하니 아무 쪽이나 고르면 된다","mis":"K4-1-u2-X48"},{"t":"글이 더 긴 ㉮가 더 알맞다","mis":"K4-1-u2-X46"}],"explanation":["답은 하나일까요?","그래도 까닭이 있어야 해요.","보는 눈 + 까닭"],"asset":{"type":"passage","lines":["① 주말에 학교 운동장을 함부로 열면 안 됩니다.","② 사람이 많이 드나들면 시설이 상하거나 쓰레기가 늘어납니다.","③ 한번 망가진 시설을 되돌리는 데에는 많은 시간과 힘이 듭니다.","④ 여는 날과 시간을 정하고 살필 사람을 둔 뒤에 열어야 합니다."],"title":"㉯ 준비한 뒤에 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#1','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C44',2,'mc','auto','「놀이터 미끄럼틀이 부서져 쓸 수 없게 되었다.」와 뜻이 가장 가까운 낱말은 무엇인가요?',ARRAY['K4-1-u2-X42']::text[],false,'{"seq":1,"concept":"K4-1-u2-C44","difficulty":2,"kind":"mc","stem":"「놀이터 미끄럼틀이 부서져 쓸 수 없게 되었다.」와 뜻이 가장 가까운 낱말은 무엇인가요?","options":[{"t":"훼손","correct":true},{"t":"개방","mis":"K4-1-u2-X42"},{"t":"보존","mis":"K4-1-u2-X42"},{"t":"결정","mis":"K4-1-u2-X42"}],"explanation":["부서져 못 쓰게 됨","망가뜨림","훼손이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#2','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C43',2,'mc','auto','「당나귀를 팔러 간 아버지와 아들」이 주는 가르침으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X41','K4-1-u2-X22']::text[],false,'{"seq":2,"concept":"K4-1-u2-C43","difficulty":2,"kind":"mc","stem":"「당나귀를 팔러 간 아버지와 아들」이 주는 가르침으로 알맞은 것은 무엇인가요?","options":[{"t":"남의 의견도 알맞은지 따져 본 뒤에 받아들여야 한다","correct":true},{"t":"남의 말은 언제나 그대로 따라야 한다","mis":"K4-1-u2-X41"},{"t":"남의 말은 언제나 듣지 말아야 한다","mis":"K4-1-u2-X22"},{"t":"당나귀는 타고 가야 한다","mis":"K4-1-u2-X41"}],"explanation":["그대로 따라서 어떻게 되었나요?","듣지 말라는 것일까요?","따져 보고 받아들여요."],"asset":{"type":"passage","lines":["① 아버지와 아들이 당나귀를 끌고 장으로 가고 있었다.","② \"당나귀를 두고 걸어가다니 어리석구나.\" 지나가던 사람이 말했다.","③ 말을 들을 때마다 둘은 타고, 바꾸어 타고, 함께 타기를 되풀이했다.","④ 끝내 당나귀를 메고 다리를 건너다 당나귀를 물에 빠뜨렸다."],"title":"당나귀를 팔러 간 아버지와 아들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#3','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C46',3,'mc','auto','「㉰ 먹을 만큼 받아요」를 평가했어요. 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X44','K4-1-u2-X46']::text[],false,'{"seq":3,"concept":"K4-1-u2-C46","difficulty":3,"kind":"mc","stem":"「㉰ 먹을 만큼 받아요」를 평가했어요. 가장 알맞은 것은 무엇인가요?","options":[{"t":"②와 ③은 의견을 잘 받치지만 ④는 소문이라 믿기 어려워 빼는 것이 좋다","correct":true},{"t":"④가 가장 놀라운 내용이라 가장 좋은 뒷받침이다","mis":"K4-1-u2-X44"},{"t":"뒷받침이 많을수록 믿을 만하니 그대로 두어도 된다","mis":"K4-1-u2-X44"},{"t":"글이 짧으니 알맞지 않은 글이다","mis":"K4-1-u2-X46"}],"explanation":["④는 어디서 들은 말인가요?","확인할 수 없어요.","믿을 수 있는지 따져요."],"asset":{"type":"passage","lines":["① 급식은 먹을 만큼만 받았으면 좋겠습니다.","② 다 먹지 못하고 남긴 음식은 모두 버려집니다.","③ 받은 만큼 다 먹으면 스스로 해냈다는 뿌듯함도 생깁니다.","④ 누가 그러는데 남긴 음식은 모두 바다에 버린다고 합니다.","⑤ 처음에는 조금 받고, 모자라면 더 받으러 가면 됩니다."],"title":"㉰ 먹을 만큼 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#4','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C47',3,'mc','auto','「㉰ 먹을 만큼 받아요」대로 했을 때 생길 수 있는 다른 문제를 말한 글은 무엇인가요?',ARRAY['K4-1-u2-X43','K4-1-u2-X45']::text[],false,'{"seq":4,"concept":"K4-1-u2-C47","difficulty":3,"kind":"mc","stem":"「㉰ 먹을 만큼 받아요」대로 했을 때 생길 수 있는 다른 문제를 말한 글은 무엇인가요?","options":[{"t":"㉱ — 두 번씩 줄을 서면 배식대 앞이 붐빈다","correct":true},{"t":"㉰ ② — 남긴 음식은 버려진다","mis":"K4-1-u2-X43"},{"t":"㉰ ③ — 다 먹으면 뿌듯하다","mis":"K4-1-u2-X43"},{"t":"없다 — 의견대로 하면 문제가 생기지 않는다","mis":"K4-1-u2-X45"}],"explanation":["그대로 했을 때?","줄이 어떻게 되나요?","㉱가 말했어요."],"asset":{"type":"passage","lines":["① 모두가 두 번씩 줄을 서면 배식대 앞이 붐빕니다.","② 그러면 늦게 받는 친구는 점심을 서둘러 먹어야 합니다.","③ 처음부터 알맞게 받을 수 있도록 양을 미리 말해 주면 좋겠습니다."],"title":"㉱ 처음부터 알맞게 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#5','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C49',3,'mc','auto','「㉯ 준비한 뒤에 열어요」의 의견을 지나치게 넓혀 읽은 것은 무엇인가요?',ARRAY['K4-1-u2-X47']::text[],false,'{"seq":5,"concept":"K4-1-u2-C49","difficulty":3,"kind":"mc","stem":"「㉯ 준비한 뒤에 열어요」의 의견을 지나치게 넓혀 읽은 것은 무엇인가요?","options":[{"t":"㉯는 운동장을 절대 열면 안 된다고 했다","correct":true},{"t":"㉯는 날과 시간을 정한 뒤에 열자고 했다","mis":"K4-1-u2-X47"},{"t":"㉯는 살필 사람을 두자고 했다","mis":"K4-1-u2-X47"},{"t":"㉯는 시설이 상할 것을 걱정했다","mis":"K4-1-u2-X47"}],"explanation":["④를 봐요.","열자는 걸까요, 막자는 걸까요?","절대는 지나쳐요."],"asset":{"type":"passage","lines":["① 주말에 학교 운동장을 함부로 열면 안 됩니다.","② 사람이 많이 드나들면 시설이 상하거나 쓰레기가 늘어납니다.","③ 한번 망가진 시설을 되돌리는 데에는 많은 시간과 힘이 듭니다.","④ 여는 날과 시간을 정하고 살필 사람을 둔 뒤에 열어야 합니다."],"title":"㉯ 준비한 뒤에 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#6','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C51',3,'mc','auto','㉮와 ㉯의 걱정을 함께 담은 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X45','K4-1-u2-X47','K4-1-u2-X25']::text[],false,'{"seq":6,"concept":"K4-1-u2-C51","difficulty":3,"kind":"mc","stem":"㉮와 ㉯의 걱정을 함께 담은 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"여는 날과 시간을 정하고, 쓴 사람이 함께 치우기로 약속한다","correct":true},{"t":"운동장을 날마다 아무 때나 연다","mis":"K4-1-u2-X45"},{"t":"운동장을 영원히 잠가 둔다","mis":"K4-1-u2-X47"},{"t":"먼저 쓴 글인 ㉮의 의견만 따른다","mis":"K4-1-u2-X25"}],"explanation":["열고 싶은 마음 + 지키고 싶은 마음","둘 다 담아요.","열면서도 지키기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#7','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C45',3,'mc','auto','「급식은 먹을 만큼만 받자」라는 의견의 뒷받침으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u2-X43']::text[],false,'{"seq":7,"concept":"K4-1-u2-C45","difficulty":3,"kind":"mc","stem":"「급식은 먹을 만큼만 받자」라는 의견의 뒷받침으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"급식실 벽은 하얀색이다","correct":true},{"t":"남긴 음식은 모두 버려진다","mis":"K4-1-u2-X43"},{"t":"다 먹으면 스스로 해냈다는 뿌듯함이 생긴다","mis":"K4-1-u2-X43"},{"t":"모자라면 더 받으러 가면 된다","mis":"K4-1-u2-X43"}],"explanation":["의견과 이어지나요?","벽 색깔은?","상관없어요."],"asset":{"type":"passage","lines":["① 급식은 먹을 만큼만 받았으면 좋겠습니다.","② 다 먹지 못하고 남긴 음식은 모두 버려집니다.","③ 받은 만큼 다 먹으면 스스로 해냈다는 뿌듯함도 생깁니다.","④ 누가 그러는데 남긴 음식은 모두 바다에 버린다고 합니다.","⑤ 처음에는 조금 받고, 모자라면 더 받으러 가면 됩니다."],"title":"㉰ 먹을 만큼 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#8','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C45',4,'essay','teacher','「㉰ 먹을 만큼 받아요」를 평가 기준 세 가지(뒷받침이 알맞은가 · 믿을 수 있는가 · 다른 문제는 없는가)에 따라 평가해 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u2-C45","difficulty":4,"kind":"essay","stem":"「㉰ 먹을 만큼 받아요」를 평가 기준 세 가지(뒷받침이 알맞은가 · 믿을 수 있는가 · 다른 문제는 없는가)에 따라 평가해 쓰세요.","answer_guide":{"answer":"예: 알맞은가 — 남긴 음식이 버려진다는 ②는 의견과 이어져 알맞다. 믿을 수 있는가 — ④는 「누가 그러는데」로 시작하는 소문이라 믿기 어렵다. 다른 문제 — 모두 두 번씩 줄을 서면 배식대 앞이 붐빌 수 있다.","scoring_points":["뒷받침이 알맞은지 평가했는가","믿을 수 없는 내용을 찾았는가","다른 문제를 찾았는가"]},"explanation":["이어지나?","믿을 만한가?","다른 문제는?"],"asset":{"type":"passage","lines":["① 급식은 먹을 만큼만 받았으면 좋겠습니다.","② 다 먹지 못하고 남긴 음식은 모두 버려집니다.","③ 받은 만큼 다 먹으면 스스로 해냈다는 뿌듯함도 생깁니다.","④ 누가 그러는데 남긴 음식은 모두 바다에 버린다고 합니다.","⑤ 처음에는 조금 받고, 모자라면 더 받으러 가면 됩니다."],"title":"㉰ 먹을 만큼 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#9','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C50',4,'essay','teacher','㉰와 ㉱를 읽고 내 평가를 쓰세요. 어느 쪽에 더 가까운지와 그렇게 본 까닭을 쓰고, 다른 쪽 글에서 받아들일 점도 하나 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u2-C50","difficulty":4,"kind":"essay","stem":"㉰와 ㉱를 읽고 내 평가를 쓰세요. 어느 쪽에 더 가까운지와 그렇게 본 까닭을 쓰고, 다른 쪽 글에서 받아들일 점도 하나 쓰세요.","answer_guide":{"answer":"예: ㉰에 더 가깝다. 음식을 남기면 버려지기 때문이다. 하지만 ㉱의 말처럼 두 번씩 줄을 서면 붐빌 수 있으니, 처음에 받을 양을 말할 수 있게 하는 방법도 함께 쓰면 좋겠다.","scoring_points":["한쪽을 골라 까닭을 썼는가","다른 쪽 글에서 받아들일 점을 썼는가","아무렇게나가 아니라 글 내용을 근거로 썼는가"]},"explanation":["어느 쪽?","까닭","다른 쪽에서 배울 점"],"asset":{"type":"passage","lines":["① 모두가 두 번씩 줄을 서면 배식대 앞이 붐빕니다.","② 그러면 늦게 받는 친구는 점심을 서둘러 먹어야 합니다.","③ 처음부터 알맞게 받을 수 있도록 양을 미리 말해 주면 좋겠습니다."],"title":"㉱ 처음부터 알맞게 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L09_challenge#10','kor',4,1,'u2','L09','g4_1_kor_u2_L09_challenge','lesson_challenge','K4-1-u2-C43',4,'essay','teacher','「당나귀를 팔러 간 아버지와 아들」에서 아버지와 아들이 지나가던 사람의 말을 들었을 때 어떻게 했으면 좋았을지 평가 기준을 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u2-C43","difficulty":4,"kind":"essay","stem":"「당나귀를 팔러 간 아버지와 아들」에서 아버지와 아들이 지나가던 사람의 말을 들었을 때 어떻게 했으면 좋았을지 평가 기준을 들어 쓰세요.","answer_guide":{"answer":"예: 「당나귀를 두고 걸어가다니 어리석구나」라는 말을 들었을 때, 당나귀를 타면 장에 가기 전에 당나귀가 지치지 않을지(다른 문제는 없는지) 따져 보고, 팔러 가는 당나귀이니 끌고 가는 것이 낫다고 스스로 정했으면 좋았다.","scoring_points":["남의 말을 따져 보아야 했다고 썼는가","평가 기준을 하나 이상 들었는가","어떻게 했으면 좋았을지 썼는가"]},"explanation":["그대로 따르지 말고","기준으로 따져요.","스스로 정해요."],"asset":{"type":"passage","lines":["① 아버지와 아들이 당나귀를 끌고 장으로 가고 있었다.","② \"당나귀를 두고 걸어가다니 어리석구나.\" 지나가던 사람이 말했다.","③ 말을 들을 때마다 둘은 타고, 바꾸어 타고, 함께 타기를 되풀이했다.","④ 끝내 당나귀를 메고 다리를 건너다 당나귀를 물에 빠뜨렸다."],"title":"당나귀를 팔러 간 아버지와 아들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#1','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C53',1,'mc','auto','학급 누리집에서 의견을 나눌 때 지킬 것은 무엇인가요?',ARRAY['K4-1-u2-X49','K4-1-u2-X12']::text[],false,'{"seq":1,"concept":"K4-1-u2-C53","difficulty":1,"kind":"mc","stem":"학급 누리집에서 의견을 나눌 때 지킬 것은 무엇인가요?","options":[{"t":"친구의 의견에서 좋은 점을 먼저 말한다","correct":true},{"t":"마음에 들지 않는 의견에는 놀리는 댓글을 단다","mis":"K4-1-u2-X49"},{"t":"내 의견에 찬성한 친구에게만 답을 단다","mis":"K4-1-u2-X49"},{"t":"까닭은 빼고 하고 싶은 것만 짧게 쓴다","mis":"K4-1-u2-X12"}],"explanation":["얼굴이 보이지 않아도","읽는 사람은 마음이 있어요.","좋은 점을 먼저"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#2','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C56',1,'mc','auto','「찾지 말고, 읽으세요.」 광고를 만든 사람의 의견은 무엇인가요?',ARRAY['K4-1-u2-X52']::text[],false,'{"seq":2,"concept":"K4-1-u2-C56","difficulty":1,"kind":"mc","stem":"「찾지 말고, 읽으세요.」 광고를 만든 사람의 의견은 무엇인가요?","options":[{"t":"찾아보기만 하지 말고 책을 읽자","correct":true},{"t":"글자를 아예 보지 말자","mis":"K4-1-u2-X52"},{"t":"무엇이든 빨리 찾자","mis":"K4-1-u2-X52"},{"t":"책을 사서 모아 두자","mis":"K4-1-u2-X52"}],"explanation":["두 가지를 견주고 있어요.","찾기 vs 읽기","읽기를 권해요."],"asset":{"type":"passage","lines":["찾지 말고, 읽으세요.","손끝으로 찾은 것은 손끝에서 사라집니다.","한 장 한 장 읽은 것은 내 안에 남습니다."],"title":"광고 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#3','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C58',1,'mc','auto','「뿌린」과 「만큼」이 들어간 말을 바르게 띄어 쓴 것은 무엇인가요?',ARRAY['K4-1-u2-X53','K4-1-u2-X55']::text[],false,'{"seq":3,"concept":"K4-1-u2-C58","difficulty":1,"kind":"mc","stem":"「뿌린」과 「만큼」이 들어간 말을 바르게 띄어 쓴 것은 무엇인가요?","options":[{"t":"뿌린 만큼 거둔다","correct":true},{"t":"뿌린만큼 거둔다","mis":"K4-1-u2-X53"},{"t":"뿌 린만큼 거둔다","mis":"K4-1-u2-X55"},{"t":"뿌린 만 큼 거둔다","mis":"K4-1-u2-X55"}],"explanation":["「뿌린」은 「-ㄴ」으로 끝나요.","그 뒤의 「만큼」은?","띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#4','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C60',1,'mc','auto','「탈것」에 드는 낱말은 무엇인가요?',ARRAY['K4-1-u2-X56']::text[],false,'{"seq":4,"concept":"K4-1-u2-C60","difficulty":1,"kind":"mc","stem":"「탈것」에 드는 낱말은 무엇인가요?","options":[{"t":"여객선","correct":true},{"t":"참새","mis":"K4-1-u2-X56"},{"t":"갈치","mis":"K4-1-u2-X56"},{"t":"메뚜기","mis":"K4-1-u2-X56"}],"explanation":["사람이 타고 다니는 것","배도 탈것이에요.","여객선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#5','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C54',2,'mc','auto','학급 누리집에 올라온 의견 가운데 더 좋은 의견의 조건으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X50','K4-1-u2-X46']::text[],false,'{"seq":5,"concept":"K4-1-u2-C54","difficulty":2,"kind":"mc","stem":"학급 누리집에 올라온 의견 가운데 더 좋은 의견의 조건으로 알맞은 것은 무엇인가요?","options":[{"t":"모두 함께할 수 있고 까닭이 뚜렷한 의견","correct":true},{"t":"돈이 가장 많이 드는 의견","mis":"K4-1-u2-X50"},{"t":"가장 먼저 올라온 의견","mis":"K4-1-u2-X50"},{"t":"글자 수가 가장 많은 의견","mis":"K4-1-u2-X46"}],"explanation":["몇 사람만 즐거우면?","모두 함께","까닭이 뚜렷하게"],"asset":{"type":"passage","lines":["체육 대회를 해요 · 함께 운동하면 친구들과 더 가까워지기 때문입니다.","도서관 봉사를 해요 · 학교를 위한 일이고 보람도 느끼기 때문입니다.","알뜰 시장을 열어요 · 쓰지 않는 물건을 나누며 아끼는 마음을 배우기 때문입니다."],"title":"학급 누리집 — 학급의 날에 무엇을 할까요?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#6','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C59',2,'mc','auto','「형」과 「만큼」이 들어간 문장을 바르게 띄어 쓴 것은 무엇인가요?',ARRAY['K4-1-u2-X54','K4-1-u2-X55']::text[],false,'{"seq":6,"concept":"K4-1-u2-C59","difficulty":2,"kind":"mc","stem":"「형」과 「만큼」이 들어간 문장을 바르게 띄어 쓴 것은 무엇인가요?","options":[{"t":"나는 형만큼 달리기가 빠르다","correct":true},{"t":"나는 형 만큼 달리기가 빠르다","mis":"K4-1-u2-X54"},{"t":"나는 형만 큼 달리기가 빠르다","mis":"K4-1-u2-X55"},{"t":"나는 형만큼달리기가 빠르다","mis":"K4-1-u2-X55"}],"explanation":["「형」은 사람을 부르는 이름이에요.","이름 뒤에는","붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#7','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C60',2,'match','auto','넓은 무리와 그 안에 드는 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-1-u2-C60","difficulty":2,"kind":"match","stem":"넓은 무리와 그 안에 드는 낱말을 알맞게 이으세요.","pairs":[{"l":"곤충","r":"메뚜기 · 모기"},{"l":"물고기","r":"고등어 · 갈치"},{"l":"새","r":"까치 · 참새"}],"mis":"K4-1-u2-X56","explanation":["어느 무리에 드나요?","날개 · 지느러미","짝을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#8','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C55',2,'mc','auto','학급 누리집에서 의견을 결정한 뒤에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X51','K4-1-u2-X49']::text[],false,'{"seq":8,"concept":"K4-1-u2-C55","difficulty":2,"kind":"mc","stem":"학급 누리집에서 의견을 결정한 뒤에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"왜 그 의견으로 정했는지 까닭을 함께 남긴다","correct":true},{"t":"결정만 알리고 까닭은 남기지 않는다","mis":"K4-1-u2-X51"},{"t":"다른 의견을 낸 글은 모두 지운다","mis":"K4-1-u2-X49"},{"t":"찬성한 친구에게만 결과를 알린다","mis":"K4-1-u2-X49"}],"explanation":["다른 의견을 낸 친구는?","받아들일 수 있게","까닭을 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#9','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C52',2,'mc','auto','학급 누리집에서 의견을 나누는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X17','K4-1-u2-X18']::text[],false,'{"seq":9,"concept":"K4-1-u2-C52","difficulty":2,"kind":"mc","stem":"학급 누리집에서 의견을 나누는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"하고 싶은 활동과 까닭 올리기 → 친구 의견 읽고 좋은 의견 고르기 → 함께 결정하기","correct":true},{"t":"함께 결정하기 → 의견 올리기 → 친구 의견 읽기","mis":"K4-1-u2-X17"},{"t":"친구 의견 읽기 → 결정하기 → 까닭 없이 의견 올리기","mis":"K4-1-u2-X17"},{"t":"결정만 하고 의견은 올리지 않기","mis":"K4-1-u2-X18"}],"explanation":["올리고","읽고 고르고","결정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_basic#10','kor',4,1,'u2','L11','g4_1_kor_u2_L11_basic','lesson_basic','K4-1-u2-C57',3,'mc','auto','「찾지 말고, 읽으세요.」 광고의 의견과 내 의견을 견준 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X40','K4-1-u2-X07','K4-1-u2-X46']::text[],false,'{"seq":10,"concept":"K4-1-u2-C57","difficulty":3,"kind":"mc","stem":"「찾지 말고, 읽으세요.」 광고의 의견과 내 의견을 견준 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"찬성해. 책을 끝까지 읽었을 때 내용이 오래 기억에 남았기 때문이야.","correct":true},{"t":"찬성해.","mis":"K4-1-u2-X40"},{"t":"광고니까 무조건 맞아.","mis":"K4-1-u2-X07"},{"t":"광고는 글이 짧아서 반대해.","mis":"K4-1-u2-X46"}],"explanation":["찬성 · 반대 + 까닭","내 경험을 근거로","까닭까지 말해요."],"asset":{"type":"passage","lines":["찾지 말고, 읽으세요.","손끝으로 찾은 것은 손끝에서 사라집니다.","한 장 한 장 읽은 것은 내 안에 남습니다."],"title":"광고 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#1','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C56',2,'mc','auto','「틀어 놓지 말고, 받아 쓰세요.」 광고를 만든 사람의 의견으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X52']::text[],false,'{"seq":1,"concept":"K4-1-u2-C56","difficulty":2,"kind":"mc","stem":"「틀어 놓지 말고, 받아 쓰세요.」 광고를 만든 사람의 의견으로 알맞은 것은 무엇인가요?","options":[{"t":"양치할 때 물을 틀어 놓지 말고 컵에 받아 쓰자","correct":true},{"t":"양치를 하지 말자","mis":"K4-1-u2-X52"},{"t":"물을 아예 쓰지 말자","mis":"K4-1-u2-X52"},{"t":"물을 세게 틀어 빨리 끝내자","mis":"K4-1-u2-X52"}],"explanation":["두 가지를 견줘요.","틀어 놓기 vs 받아 쓰기","받아 쓰기를 권해요."],"asset":{"type":"passage","lines":["틀어 놓지 말고, 받아 쓰세요.","흘려보낸 물은 그대로 사라집니다.","컵에 받은 물은 끝까지 쓰입니다."],"title":"양치할 때 보는 광고 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#2','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C58',2,'mc','auto','밑줄 그은 곳을 바르게 띄어 쓴 것은 무엇인가요? 「선생님께서 말씀하신(대로) 줄을 섰다.」',ARRAY['K4-1-u2-X53','K4-1-u2-X55']::text[],false,'{"seq":2,"concept":"K4-1-u2-C58","difficulty":2,"kind":"mc","stem":"밑줄 그은 곳을 바르게 띄어 쓴 것은 무엇인가요? 「선생님께서 말씀하신(대로) 줄을 섰다.」","options":[{"t":"말씀하신 대로","correct":true},{"t":"말씀하신대로","mis":"K4-1-u2-X53"},{"t":"말씀하 신대로","mis":"K4-1-u2-X55"},{"t":"말씀 하신대로","mis":"K4-1-u2-X55"}],"explanation":["「말씀하신」은 「-ㄴ」","그 뒤의 「대로」는","띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#3','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C59',3,'mc','auto','「나는 (나대로) 그림을 그렸다.」에서 「나대로」를 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X54','K4-1-u2-X55']::text[],false,'{"seq":3,"concept":"K4-1-u2-C59","difficulty":3,"kind":"mc","stem":"「나는 (나대로) 그림을 그렸다.」에서 「나대로」를 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"「나」가 사람을 가리키는 말이라 「나대로」로 붙여 쓴다","correct":true},{"t":"「대로」는 언제나 띄어 써야 하니 「나 대로」로 쓴다","mis":"K4-1-u2-X54"},{"t":"「나대 로」로 띄어 쓴다","mis":"K4-1-u2-X55"},{"t":"「나」 뒤에는 「대로」를 쓸 수 없다","mis":"K4-1-u2-X54"}],"explanation":["앞말은 무엇인가요?","「나」는 사람을 가리켜요.","붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#4','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C61',3,'mc','auto','「동물 — 새 — 참새」에서 「새」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X57']::text[],false,'{"seq":4,"concept":"K4-1-u2-C61","difficulty":3,"kind":"mc","stem":"「동물 — 새 — 참새」에서 「새」를 바르게 말한 것은 무엇인가요?","options":[{"t":"「동물」 안에 들면서 「참새」를 품는 넓은 무리이다","correct":true},{"t":"「동물」보다 넓은 무리이다","mis":"K4-1-u2-X57"},{"t":"「참새」 안에 드는 말이다","mis":"K4-1-u2-X57"},{"t":"넓은 무리는 하나뿐이라서 「새」는 넓은 무리가 될 수 없다","mis":"K4-1-u2-X57"}],"explanation":["새는 동물일까요?","참새는 새일까요?","둘 다 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#5','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C60',3,'mc','auto','「악기」에 들지 않는 낱말은 무엇인가요?',ARRAY['K4-1-u2-X56']::text[],false,'{"seq":5,"concept":"K4-1-u2-C60","difficulty":3,"kind":"mc","stem":"「악기」에 들지 않는 낱말은 무엇인가요?","options":[{"t":"줄넘기","correct":true},{"t":"피아노","mis":"K4-1-u2-X56"},{"t":"리코더","mis":"K4-1-u2-X56"},{"t":"북","mis":"K4-1-u2-X56"}],"explanation":["소리를 내는 도구","줄넘기는 무엇에 드나요?","운동 도구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#6','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C53',3,'mc','auto','친구가 누리집에 「도서관 봉사를 해요」라고 올렸어요. 예의를 지켜 고칠 점을 말한 댓글은 무엇인가요?',ARRAY['K4-1-u2-X23','K4-1-u2-X49','K4-1-u2-X22']::text[],false,'{"seq":6,"concept":"K4-1-u2-C53","difficulty":3,"kind":"mc","stem":"친구가 누리집에 「도서관 봉사를 해요」라고 올렸어요. 예의를 지켜 고칠 점을 말한 댓글은 무엇인가요?","options":[{"t":"학교를 위한 일이라 좋아요. 다만 모두 한꺼번에 가면 좁을 수 있으니 모둠별로 나누어 가면 어떨까요?","correct":true},{"t":"도서관 봉사는 재미없어요.","mis":"K4-1-u2-X23"},{"t":"그런 걸 누가 해요? 다들 웃겠네요.","mis":"K4-1-u2-X49"},{"t":"제 의견이 더 좋으니 제 의견으로 해요.","mis":"K4-1-u2-X22"}],"explanation":["좋은 점 먼저","고칠 점은 부드럽게","까닭도 함께"],"asset":{"type":"passage","lines":["체육 대회를 해요 · 함께 운동하면 친구들과 더 가까워지기 때문입니다.","도서관 봉사를 해요 · 학교를 위한 일이고 보람도 느끼기 때문입니다.","알뜰 시장을 열어요 · 쓰지 않는 물건을 나누며 아끼는 마음을 배우기 때문입니다."],"title":"학급 누리집 — 학급의 날에 무엇을 할까요?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#7','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C62',3,'mc','auto','「서로 다른 의견」 단원에서 배운 것을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X05','K4-1-u2-X30','K4-1-u2-X33']::text[],false,'{"seq":7,"concept":"K4-1-u2-C62","difficulty":3,"kind":"mc","stem":"「서로 다른 의견」 단원에서 배운 것을 바르게 말한 것은 무엇인가요?","options":[{"t":"절차를 지켜 토의하고, 글쓴이의 의견을 파악해 내 의견과 견주고 평가한다","correct":true},{"t":"토의에서는 이기는 의견을 정하고, 글은 그대로 믿는다","mis":"K4-1-u2-X05"},{"t":"사실과 의견은 같은 방법으로 따진다","mis":"K4-1-u2-X30"},{"t":"글쓴이의 의견은 마지막 문장만 읽으면 찾을 수 있다","mis":"K4-1-u2-X33"}],"explanation":["말하기 · 읽기","토의 · 파악 · 비교 · 평가","모두 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#8','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C54',4,'essay','teacher','학급 누리집에 올라온 세 의견(체육 대회 · 도서관 봉사 · 알뜰 시장) 가운데 하나를 고르고, 더 좋은 의견의 조건을 들어 고른 까닭과 결정한 까닭을 남기는 글을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u2-C54","difficulty":4,"kind":"essay","stem":"학급 누리집에 올라온 세 의견(체육 대회 · 도서관 봉사 · 알뜰 시장) 가운데 하나를 고르고, 더 좋은 의견의 조건을 들어 고른 까닭과 결정한 까닭을 남기는 글을 쓰세요.","answer_guide":{"answer":"예: 알뜰 시장을 골랐다. 운동을 잘하든 못하든 모두 함께할 수 있고, 쓰지 않는 물건을 나누며 아끼는 마음을 배운다는 까닭이 뚜렷하기 때문이다. 체육 대회와 도서관 봉사도 좋은 의견이었지만 모두가 같이 참여하기 쉬운 알뜰 시장으로 정했다.","scoring_points":["한 의견을 골랐는가","모두 함께 · 까닭이 뚜렷함을 들어 썼는가","결정한 까닭을 다른 친구도 받아들일 수 있게 썼는가"]},"explanation":["하나를 골라요.","모두 · 까닭","결정한 까닭도"],"asset":{"type":"passage","lines":["체육 대회를 해요 · 함께 운동하면 친구들과 더 가까워지기 때문입니다.","도서관 봉사를 해요 · 학교를 위한 일이고 보람도 느끼기 때문입니다.","알뜰 시장을 열어요 · 쓰지 않는 물건을 나누며 아끼는 마음을 배우기 때문입니다."],"title":"학급 누리집 — 학급의 날에 무엇을 할까요?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#9','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C57',4,'essay','teacher','「틀어 놓지 말고, 받아 쓰세요.」 광고의 의견을 한 문장으로 쓰고, 그 의견에 대한 내 생각(찬성 · 반대)과 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u2-C57","difficulty":4,"kind":"essay","stem":"「틀어 놓지 말고, 받아 쓰세요.」 광고의 의견을 한 문장으로 쓰고, 그 의견에 대한 내 생각(찬성 · 반대)과 까닭을 쓰세요.","answer_guide":{"answer":"예: 의견 — 양치할 때 물을 틀어 놓지 말고 컵에 받아 쓰자. 내 생각 — 찬성한다. 물을 틀어 놓고 양치하면 쓰지도 않은 물이 그대로 흘러가 버리기 때문이다.","scoring_points":["광고의 의견을 바르게 썼는가","내 생각을 분명히 밝혔는가","까닭을 함께 썼는가"]},"explanation":["권하는 쪽","찬성 · 반대","까닭"],"asset":{"type":"passage","lines":["틀어 놓지 말고, 받아 쓰세요.","흘려보낸 물은 그대로 사라집니다.","컵에 받은 물은 끝까지 쓰입니다."],"title":"양치할 때 보는 광고 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_L11_challenge#10','kor',4,1,'u2','L11','g4_1_kor_u2_L11_challenge','lesson_challenge','K4-1-u2-C58',4,'essay','teacher','「만큼」을 띄어 쓰는 문장 하나와 붙여 쓰는 문장 하나를 만들고, 띄어 쓰거나 붙여 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u2-C58","difficulty":4,"kind":"essay","stem":"「만큼」을 띄어 쓰는 문장 하나와 붙여 쓰는 문장 하나를 만들고, 띄어 쓰거나 붙여 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 띄어 쓰기 — 먹을 만큼 덜어 먹자. 「먹을」이 「-ㄹ」로 끝나서 띄어 쓴다. 붙여 쓰기 — 동생도 형만큼 키가 컸다. 「형」은 사람을 나타내는 이름이라 붙여 쓴다.","scoring_points":["띄어 쓰는 문장을 바르게 썼는가","붙여 쓰는 문장을 바르게 썼는가","앞말을 들어 까닭을 썼는가"]},"explanation":["-ㄴ · -ㄹ 뒤","이름 뒤","까닭도"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#1','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C4',1,'mc','auto','단원을 마무리하며 물어요. 토의는 무엇을 하려는 말하기인가요?',ARRAY['K4-1-u2-X05','K4-1-u2-X04','K4-1-u2-X01']::text[],false,'{"seq":1,"concept":"K4-1-u2-C4","difficulty":1,"kind":"mc","stem":"단원을 마무리하며 물어요. 토의는 무엇을 하려는 말하기인가요?","options":[{"t":"여러 사람이 의견을 나누어 가장 알맞은 방법을 찾으려는 말하기","correct":true},{"t":"상대를 이기려는 말하기","mis":"K4-1-u2-X05"},{"t":"혼자 생각을 정리하는 말하기","mis":"K4-1-u2-X04"},{"t":"들은 말을 그대로 외우는 말하기","mis":"K4-1-u2-X01"}],"explanation":["함께 답 찾기","여러 사람이","가장 알맞은 방법"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#2','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C16',1,'mc','auto','토의 절차의 마지막 단계는 무엇인가요?',ARRAY['K4-1-u2-X17']::text[],false,'{"seq":2,"concept":"K4-1-u2-C16","difficulty":1,"kind":"mc","stem":"토의 절차의 마지막 단계는 무엇인가요?","options":[{"t":"의견 결정하기","correct":true},{"t":"토의 주제 정하기","mis":"K4-1-u2-X17"},{"t":"의견 마련하기","mis":"K4-1-u2-X17"},{"t":"의견 모으기","mis":"K4-1-u2-X17"}],"explanation":["모은 뒤에는?","기준을 세워요.","결정하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#3','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C19',1,'mc','auto','사회자가 하는 일로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X19','K4-1-u2-X20','K4-1-u2-X18']::text[],false,'{"seq":3,"concept":"K4-1-u2-C19","difficulty":1,"kind":"mc","stem":"사회자가 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"이야기가 주제에서 벗어나지 않게 한다","correct":true},{"t":"자기 의견으로 결정해 버린다","mis":"K4-1-u2-X19"},{"t":"말을 잘하는 친구만 말하게 한다","mis":"K4-1-u2-X20"},{"t":"의견 모으기를 건너뛴다","mis":"K4-1-u2-X18"}],"explanation":["사회자는 이끄는 사람","주제 안에서","벗어나지 않게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#4','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C28',1,'mc','auto','「우리 학교에는 나무가 서른 그루 있습니다.」는 사실과 의견 가운데 무엇인가요?',ARRAY['K4-1-u2-X29']::text[],false,'{"seq":4,"concept":"K4-1-u2-C28","difficulty":1,"kind":"mc","stem":"「우리 학교에는 나무가 서른 그루 있습니다.」는 사실과 의견 가운데 무엇인가요?","options":[{"t":"사실","correct":true},{"t":"의견","mis":"K4-1-u2-X29"},{"t":"사실도 의견도 아니다","mis":"K4-1-u2-X29"},{"t":"글쓴이의 바람","mis":"K4-1-u2-X29"}],"explanation":["있는 것을 알려 주나요?","세어 보면 알 수 있어요.","사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#5','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C35',1,'mc','auto','「마을에 밥집을 만들어요」의 글쓴이가 바라는 것은 무엇인가요?',ARRAY['K4-1-u2-X06','K4-1-u2-X35']::text[],false,'{"seq":5,"concept":"K4-1-u2-C35","difficulty":1,"kind":"mc","stem":"「마을에 밥집을 만들어요」의 글쓴이가 바라는 것은 무엇인가요?","options":[{"t":"사람과 동물이 함께 살아가는 마을","correct":true},{"t":"고양이가 없는 마을","mis":"K4-1-u2-X06"},{"t":"가로등이 많은 마을","mis":"K4-1-u2-X35"},{"t":"쓰레기봉투가 많은 마을","mis":"K4-1-u2-X06"}],"explanation":["⑦을 봐요.","함께 살아가는","마을을 바라요."],"asset":{"type":"passage","lines":["① 우리 마을 골목에는 주인 없는 고양이들이 살고 있습니다.","② 먹을 것을 찾아 쓰레기봉투를 헤집는 일도 자주 일어납니다.","③ 저는 마을 한쪽에 고양이 밥집을 만들었으면 좋겠습니다.","④ 정해진 곳에서 밥을 먹으면 쓰레기를 헤집는 일이 줄어듭니다.","⑤ 또 밥집을 두면 아픈 고양이를 일찍 찾아 돌볼 수 있습니다.","⑥ 동물도 사람처럼 배고픔과 아픔을 느끼는 생명입니다.","⑦ 사람과 동물이 함께 살아가는 마을을 만들었으면 좋겠습니다."],"title":"마을에 밥집을 만들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#6','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C44',1,'mc','auto','「드나들고 쓸 수 있게 여는 것」을 뜻하는 낱말은 무엇인가요?',ARRAY['K4-1-u2-X42']::text[],false,'{"seq":6,"concept":"K4-1-u2-C44","difficulty":1,"kind":"mc","stem":"「드나들고 쓸 수 있게 여는 것」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"개방","correct":true},{"t":"보존","mis":"K4-1-u2-X42"},{"t":"훼손","mis":"K4-1-u2-X42"},{"t":"토의","mis":"K4-1-u2-X42"}],"explanation":["열기","문을 열어 두어요.","개방이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
