INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#10','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C12',2,'mc','auto','「교실 뒤에 분리배출함을 두자」라는 의견에 알맞은 이유는 무엇인가요?',ARRAY['K4-1-u2-X11','K4-1-u2-X12']::text[],false,'{"seq":10,"concept":"K4-1-u2-C12","difficulty":2,"kind":"mc","stem":"「교실 뒤에 분리배출함을 두자」라는 의견에 알맞은 이유는 무엇인가요?","options":[{"t":"쓰레기를 바로 나누어 버릴 수 있기 때문에","correct":true},{"t":"분리배출함의 색깔이 예쁘기 때문에","mis":"K4-1-u2-X11"},{"t":"교실 뒤에는 게시판이 있기 때문에","mis":"K4-1-u2-X11"},{"t":"왜냐하면 분리배출함이기 때문에","mis":"K4-1-u2-X12"}],"explanation":["그렇게 하면 무엇이 좋아지나요?","쓰레기를 바로","이어지는 이유"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
