INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#13','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C36',2,'mc','auto','「㉮ 주말에는 운동장을 열어요」에서 의견을 뒷받침하는 내용은 무엇인가요?',ARRAY['K4-1-u2-X35']::text[],false,'{"seq":13,"concept":"K4-1-u2-C36","difficulty":2,"kind":"mc","stem":"「㉮ 주말에는 운동장을 열어요」에서 의견을 뒷받침하는 내용은 무엇인가요?","options":[{"t":"운동장을 열면 마을 사람들이 함께 운동할 곳이 생긴다","correct":true},{"t":"운동장은 학교 앞에 있다","mis":"K4-1-u2-X35"},{"t":"마을에는 집이 많다","mis":"K4-1-u2-X35"},{"t":"주말은 토요일과 일요일이다","mis":"K4-1-u2-X35"}],"explanation":["왜 열자는 걸까?","③을 봐요.","운동할 곳이 생겨요."],"asset":{"type":"passage","lines":["① 주말에도 학교 운동장을 마을 사람들에게 열었으면 좋겠습니다.","② 우리 마을에는 아이들이 마음 놓고 뛸 만한 넓은 터가 없습니다.","③ 운동장을 열면 마을 사람들이 함께 운동할 곳이 생깁니다.","④ 사람이 자주 드나드는 곳은 오히려 눈길이 닿아 잘 살펴집니다.","⑤ 직접 써 본 곳에는 남다른 정이 들어 아끼는 사람이 늘어납니다.","⑥ 운동장을 여는 일은 학교와 마을이 함께 사는 길입니다."],"title":"㉮ 주말에는 운동장을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
