INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#15','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C56',2,'mc','auto','광고에 담긴 의견을 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X52','K4-1-u2-X32']::text[],false,'{"seq":15,"concept":"K4-1-u2-C56","difficulty":2,"kind":"mc","stem":"광고에 담긴 의견을 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"광고가 견주는 두 가지 가운데 어느 쪽을 권하는지 살핀다","correct":true},{"t":"광고에서 가장 큰 글자만 읽는다","mis":"K4-1-u2-X52"},{"t":"광고에 나온 낱말 수를 센다","mis":"K4-1-u2-X32"},{"t":"광고는 의견이 없으니 넘긴다","mis":"K4-1-u2-X52"}],"explanation":["무엇과 무엇을 견주나요?","권하는 쪽","그곳에 의견이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#16','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C58',2,'mc','auto','급식 시간에 쓴 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?',ARRAY['K4-1-u2-X53','K4-1-u2-X55']::text[],false,'{"seq":16,"concept":"K4-1-u2-C58","difficulty":2,"kind":"mc","stem":"급식 시간에 쓴 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?","options":[{"t":"먹을 만큼 덜어 먹자","correct":true},{"t":"먹을만큼 덜어 먹자","mis":"K4-1-u2-X53"},{"t":"먹 을만큼 덜어 먹자","mis":"K4-1-u2-X55"},{"t":"먹을 만 큼 덜어 먹자","mis":"K4-1-u2-X55"}],"explanation":["「먹을」은 「-ㄹ」","「만큼」은","띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#17','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C14',3,'mc','auto','「반 친구 모두가 쉬는 시간마다 줄넘기를 백 번씩 하자」라는 의견을 「실천 가능성」으로 살핀 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X13','K4-1-u2-X11']::text[],false,'{"seq":17,"concept":"K4-1-u2-C14","difficulty":3,"kind":"mc","stem":"「반 친구 모두가 쉬는 시간마다 줄넘기를 백 번씩 하자」라는 의견을 「실천 가능성」으로 살핀 말로 알맞은 것은 무엇인가요?","options":[{"t":"다리가 아픈 친구나 줄넘기가 서툰 친구도 있으니 모두가 해낼 수 있을지 따져 봐야 한다","correct":true},{"t":"줄넘기는 건강에 좋으니 따질 필요가 없다","mis":"K4-1-u2-X13"},{"t":"백 번은 너무 적으니 이백 번으로 늘리자","mis":"K4-1-u2-X13"},{"t":"줄넘기 줄의 색깔을 먼저 정하자","mis":"K4-1-u2-X11"}],"explanation":["모두가 할 수 있나요?","서툰 친구 · 아픈 친구","실천 가능성"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#18','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C32',3,'mc','auto','「급식은 먹을 만큼만 받았으면 좋겠습니다.」가 ㉰의 첫 문장이에요. 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X33','K4-1-u2-X32']::text[],false,'{"seq":18,"concept":"K4-1-u2-C32","difficulty":3,"kind":"mc","stem":"「급식은 먹을 만큼만 받았으면 좋겠습니다.」가 ㉰의 첫 문장이에요. 바르게 말한 것은 무엇인가요?","options":[{"t":"의견은 첫 문장에도 올 수 있으니 이 문장이 글쓴이의 의견이다","correct":true},{"t":"첫 문장은 의견이 될 수 없다","mis":"K4-1-u2-X33"},{"t":"마지막 문장 ⑤가 언제나 의견이다","mis":"K4-1-u2-X33"},{"t":"가장 긴 문장이 의견이다","mis":"K4-1-u2-X32"}],"explanation":["「좋겠습니다」","자리는 정해져 있지 않아요.","첫 문장이 의견"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#19','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C39',3,'mc','auto','㉰와 ㉱를 견주었어요. 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X37','K4-1-u2-X39']::text[],false,'{"seq":19,"concept":"K4-1-u2-C39","difficulty":3,"kind":"mc","stem":"㉰와 ㉱를 견주었어요. 알맞은 것은 무엇인가요?","options":[{"t":"음식을 알맞게 받자는 점은 같고, 언제 양을 맞출지는 다르다","correct":true},{"t":"같은 점만 있다","mis":"K4-1-u2-X37"},{"t":"다른 점만 있다","mis":"K4-1-u2-X37"},{"t":"㉱가 ㉰를 이겼다","mis":"K4-1-u2-X39"}],"explanation":["둘 다 알맞게 받자고 해요.","방법은 달라요.","함께 나와요."],"asset":{"type":"passage","lines":["① 모두가 두 번씩 줄을 서면 배식대 앞이 붐빕니다.","② 그러면 늦게 받는 친구는 점심을 서둘러 먹어야 합니다.","③ 처음부터 알맞게 받을 수 있도록 양을 미리 말해 주면 좋겠습니다."],"title":"㉱ 처음부터 알맞게 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#20','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C49',3,'mc','auto','「㉱ 처음부터 알맞게 받아요」의 의견을 바르게 읽은 것은 무엇인가요?',ARRAY['K4-1-u2-X47','K4-1-u2-X06']::text[],false,'{"seq":20,"concept":"K4-1-u2-C49","difficulty":3,"kind":"mc","stem":"「㉱ 처음부터 알맞게 받아요」의 의견을 바르게 읽은 것은 무엇인가요?","options":[{"t":"처음부터 알맞은 양을 받을 수 있게 미리 말하자","correct":true},{"t":"급식을 아예 받지 말자","mis":"K4-1-u2-X47"},{"t":"음식을 남겨도 괜찮다","mis":"K4-1-u2-X47"},{"t":"두 번씩 줄을 서자","mis":"K4-1-u2-X06"}],"explanation":["③을 봐요.","무엇을 하자고 했나요?","미리 말하자예요."],"asset":{"type":"passage","lines":["① 모두가 두 번씩 줄을 서면 배식대 앞이 붐빕니다.","② 그러면 늦게 받는 친구는 점심을 서둘러 먹어야 합니다.","③ 처음부터 알맞게 받을 수 있도록 양을 미리 말해 주면 좋겠습니다."],"title":"㉱ 처음부터 알맞게 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#21','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C23',3,'mc','auto','토의에서 친구 의견이 알맞지 않다고 생각할 때 가장 알맞은 말은 무엇인가요?',ARRAY['K4-1-u2-X23','K4-1-u2-X21']::text[],false,'{"seq":21,"concept":"K4-1-u2-C23","difficulty":3,"kind":"mc","stem":"토의에서 친구 의견이 알맞지 않다고 생각할 때 가장 알맞은 말은 무엇인가요?","options":[{"t":"「좋은 생각이지만 비가 오는 날에는 하기 어려울 것 같아요.」","correct":true},{"t":"「별로예요.」","mis":"K4-1-u2-X23"},{"t":"「그건 틀렸어요!」 하고 말을 끊는다","mis":"K4-1-u2-X21"},{"t":"흠을 잡는 것 같아 아무 말도 하지 않는다","mis":"K4-1-u2-X23"}],"explanation":["까닭과 함께","흠잡기가 아니에요.","부드럽게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#22','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C61',3,'mc','auto','「탈것 — 배 — 여객선」에서 넓은 무리와 그 안에 드는 말을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X57']::text[],false,'{"seq":22,"concept":"K4-1-u2-C61","difficulty":3,"kind":"mc","stem":"「탈것 — 배 — 여객선」에서 넓은 무리와 그 안에 드는 말을 바르게 말한 것은 무엇인가요?","options":[{"t":"「배」는 「탈것」 안에 들고, 「여객선」은 「배」 안에 든다","correct":true},{"t":"「여객선」이 가장 넓은 무리이다","mis":"K4-1-u2-X57"},{"t":"「배」는 넓은 무리가 될 수 없다","mis":"K4-1-u2-X57"},{"t":"「탈것」은 「배」 안에 든다","mis":"K4-1-u2-X57"}],"explanation":["가장 넓은 것은?","배는 가운데","차례대로 품어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#23','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C8',4,'essay','teacher','「우리 반 쉬는 시간을 더 즐겁게 보내려면 무엇을 할까」가 토의 주제로 알맞은 까닭을 세 조건을 들어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u2-C8","difficulty":4,"kind":"essay","stem":"「우리 반 쉬는 시간을 더 즐겁게 보내려면 무엇을 할까」가 토의 주제로 알맞은 까닭을 세 조건을 들어 쓰세요.","answer_guide":{"answer":"예: 쉬는 시간은 우리 반 모두와 관련 있고, 놀이 · 독서 · 보드게임 같은 여러 가지 의견이 나올 수 있으며, 우리끼리 정하고 실천할 수 있어 해결 방법을 찾을 수 있기 때문이다.","scoring_points":["모두와 관련 있음을 썼는가","여러 의견이 나올 수 있음을 썼는가","우리가 해결할 수 있음을 썼는가"]},"explanation":["모두와 관련","여러 의견","해결 가능"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#24','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C29',4,'essay','teacher','「㉰ 먹을 만큼 받아요」에서 사실 문장 하나와 의견 문장 하나를 골라 번호를 쓰고, 각각 어떻게 따져 보아야 하는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u2-C29","difficulty":4,"kind":"essay","stem":"「㉰ 먹을 만큼 받아요」에서 사실 문장 하나와 의견 문장 하나를 골라 번호를 쓰고, 각각 어떻게 따져 보아야 하는지 쓰세요.","answer_guide":{"answer":"예: 사실 — ② 다 먹지 못하고 남긴 음식은 모두 버려집니다. 정말 버려지는지 맞는지 따져 본다. 의견 — ① 급식은 먹을 만큼만 받았으면 좋겠습니다. 그렇게 하는 것이 알맞은지 따져 본다.","scoring_points":["사실 문장을 골랐는가","의견 문장을 골랐는가","사실은 맞는지, 의견은 알맞은지 따진다고 썼는가"]},"explanation":["사실 · 의견 고르기","맞는지","알맞은지"],"asset":{"type":"passage","lines":["① 급식은 먹을 만큼만 받았으면 좋겠습니다.","② 다 먹지 못하고 남긴 음식은 모두 버려집니다.","③ 받은 만큼 다 먹으면 스스로 해냈다는 뿌듯함도 생깁니다.","④ 누가 그러는데 남긴 음식은 모두 바다에 버린다고 합니다.","⑤ 처음에는 조금 받고, 모자라면 더 받으러 가면 됩니다."],"title":"㉰ 먹을 만큼 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_a#25','kor',4,1,'u2','','g4_1_kor_u2_review_a','unit_review','K4-1-u2-C45',4,'essay','teacher','「㉮ 주말에는 운동장을 열어요」를 평가 기준 두 가지로 평가하고, 내 의견을 뒷받침과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u2-C45","difficulty":4,"kind":"essay","stem":"「㉮ 주말에는 운동장을 열어요」를 평가 기준 두 가지로 평가하고, 내 의견을 뒷받침과 함께 쓰세요.","answer_guide":{"answer":"예: 뒷받침이 알맞은가 — 마을에 뛸 곳이 없다는 ②는 운동장을 열어야 하는 까닭과 이어져 알맞다. 다른 문제는 없는가 — 사람이 많이 드나들면 시설이 상할 수 있다. 내 의견 — 날과 시간을 정해 열면 좋겠다. 쓸 곳도 생기고 시설도 지킬 수 있기 때문이다.","scoring_points":["평가 기준 두 가지로 평가했는가","내 의견을 밝혔는가","내 의견의 뒷받침을 썼는가"]},"explanation":["기준 둘","내 의견","뒷받침"],"asset":{"type":"passage","lines":["① 주말에도 학교 운동장을 마을 사람들에게 열었으면 좋겠습니다.","② 우리 마을에는 아이들이 마음 놓고 뛸 만한 넓은 터가 없습니다.","③ 운동장을 열면 마을 사람들이 함께 운동할 곳이 생깁니다.","④ 사람이 자주 드나드는 곳은 오히려 눈길이 닿아 잘 살펴집니다.","⑤ 직접 써 본 곳에는 남다른 정이 들어 아끼는 사람이 늘어납니다.","⑥ 운동장을 여는 일은 학교와 마을이 함께 사는 길입니다."],"title":"㉮ 주말에는 운동장을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#1','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C5',1,'mc','auto','다음 가운데 토의가 필요한 일은 무엇인가요?',ARRAY['K4-1-u2-X04','K4-1-u2-X10']::text[],false,'{"seq":1,"concept":"K4-1-u2-C5","difficulty":1,"kind":"mc","stem":"다음 가운데 토의가 필요한 일은 무엇인가요?","options":[{"t":"운동회에서 우리 반을 어떻게 응원할까","correct":true},{"t":"내가 오늘 입을 옷은 무엇일까","mis":"K4-1-u2-X04"},{"t":"내 짝의 생일은 언제일까","mis":"K4-1-u2-X10"},{"t":"내가 아침에 먹은 반찬은 무엇일까","mis":"K4-1-u2-X04"}],"explanation":["함께 정할 일인가요?","우리 반 모두의 일","응원 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#2','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C16',1,'mc','auto','「의견 마련하기」 다음에 오는 토의 절차는 무엇인가요?',ARRAY['K4-1-u2-X17','K4-1-u2-X18']::text[],false,'{"seq":2,"concept":"K4-1-u2-C16","difficulty":1,"kind":"mc","stem":"「의견 마련하기」 다음에 오는 토의 절차는 무엇인가요?","options":[{"t":"의견 모으기","correct":true},{"t":"토의 주제 정하기","mis":"K4-1-u2-X17"},{"t":"의견 결정하기","mis":"K4-1-u2-X17"},{"t":"토의 끝내기","mis":"K4-1-u2-X18"}],"explanation":["준비한 뒤에는?","차례로 말하고 들어요.","모으기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#3','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C21',1,'mc','auto','토의에서 궁금한 점이 생겼을 때 알맞은 행동은 무엇인가요?',ARRAY['K4-1-u2-X21','K4-1-u2-X23']::text[],false,'{"seq":3,"concept":"K4-1-u2-C21","difficulty":1,"kind":"mc","stem":"토의에서 궁금한 점이 생겼을 때 알맞은 행동은 무엇인가요?","options":[{"t":"친구의 말이 끝난 뒤 예의를 지켜 물어본다","correct":true},{"t":"친구의 말을 끊고 바로 묻는다","mis":"K4-1-u2-X21"},{"t":"궁금해도 참고 내 의견만 말한다","mis":"K4-1-u2-X23"},{"t":"다른 친구에게 몰래 귓속말한다","mis":"K4-1-u2-X21"}],"explanation":["말이 끝난 뒤","예의를 지켜","물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#4','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C29',1,'mc','auto','「운동장에 나무를 더 심으면 좋겠습니다.」는 사실과 의견 가운데 무엇인가요?',ARRAY['K4-1-u2-X28']::text[],false,'{"seq":4,"concept":"K4-1-u2-C29","difficulty":1,"kind":"mc","stem":"「운동장에 나무를 더 심으면 좋겠습니다.」는 사실과 의견 가운데 무엇인가요?","options":[{"t":"의견","correct":true},{"t":"사실","mis":"K4-1-u2-X28"},{"t":"사실도 의견도 아니다","mis":"K4-1-u2-X28"},{"t":"있었던 일","mis":"K4-1-u2-X28"}],"explanation":["「좋겠습니다」","글쓴이의 생각","의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#5','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C6',1,'mc','auto','알림판 글의 글쓴이가 걱정하는 것은 무엇인가요?',ARRAY['K4-1-u2-X06']::text[],false,'{"seq":5,"concept":"K4-1-u2-C6","difficulty":1,"kind":"mc","stem":"알림판 글의 글쓴이가 걱정하는 것은 무엇인가요?","options":[{"t":"공이 손에서 빠져 지나가는 친구가 다칠 수 있는 것","correct":true},{"t":"운동장에 늦게 나가는 것","mis":"K4-1-u2-X06"},{"t":"공이 더러워지는 것","mis":"K4-1-u2-X06"},{"t":"점심을 늦게 먹는 것","mis":"K4-1-u2-X06"}],"explanation":["③을 봐요.","무엇이 빠지면?","친구가 다칠까 봐요."],"asset":{"type":"passage","lines":["① 점심시간에 공을 들고 복도를 지나가는 친구들이 있습니다.","② 운동장으로 빨리 나가고 싶은 마음은 저도 잘 압니다.","③ 그렇지만 공이 손에서 빠지면 지나가는 친구가 다칠 수 있습니다.","④ 공은 가방이나 주머니에 넣고 걸어서 나갔으면 좋겠습니다."],"title":"알림판에 붙은 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#6','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C44',1,'mc','auto','「잘 보살펴 그대로 남기는 것」을 뜻하는 낱말은 무엇인가요?',ARRAY['K4-1-u2-X42']::text[],false,'{"seq":6,"concept":"K4-1-u2-C44","difficulty":1,"kind":"mc","stem":"「잘 보살펴 그대로 남기는 것」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"보존","correct":true},{"t":"개방","mis":"K4-1-u2-X42"},{"t":"훼손","mis":"K4-1-u2-X42"},{"t":"결정","mis":"K4-1-u2-X42"}],"explanation":["지키기","그대로 남겨요.","보존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#7','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C58',1,'mc','auto','「노력할」과 「뿐」이 들어간 말을 바르게 띄어 쓴 것은 무엇인가요?',ARRAY['K4-1-u2-X53','K4-1-u2-X55']::text[],false,'{"seq":7,"concept":"K4-1-u2-C58","difficulty":1,"kind":"mc","stem":"「노력할」과 「뿐」이 들어간 말을 바르게 띄어 쓴 것은 무엇인가요?","options":[{"t":"열심히 노력할 뿐이다","correct":true},{"t":"열심히 노력할뿐이다","mis":"K4-1-u2-X53"},{"t":"열심히 노력 할뿐이다","mis":"K4-1-u2-X55"},{"t":"열심히 노 력할 뿐이다","mis":"K4-1-u2-X55"}],"explanation":["「노력할」은 「-ㄹ」","그 뒤의 「뿐」","띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#8','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C60',1,'mc','auto','「꽃」에 드는 낱말은 무엇인가요?',ARRAY['K4-1-u2-X56']::text[],false,'{"seq":8,"concept":"K4-1-u2-C60","difficulty":1,"kind":"mc","stem":"「꽃」에 드는 낱말은 무엇인가요?","options":[{"t":"개나리","correct":true},{"t":"고등어","mis":"K4-1-u2-X56"},{"t":"피아노","mis":"K4-1-u2-X56"},{"t":"자전거","mis":"K4-1-u2-X56"}],"explanation":["봄에 노랗게 피어요.","개나리","꽃이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#9','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C10',2,'mc','auto','「급식 시간에 물을 마셔도 될까」를 토의 주제로 고치려고 해요. 가장 알맞게 고친 것은 무엇인가요?',ARRAY['K4-1-u2-X09','K4-1-u2-X08','K4-1-u2-X10']::text[],false,'{"seq":9,"concept":"K4-1-u2-C10","difficulty":2,"kind":"mc","stem":"「급식 시간에 물을 마셔도 될까」를 토의 주제로 고치려고 해요. 가장 알맞게 고친 것은 무엇인가요?","options":[{"t":"급식 시간을 더 즐겁게 보내려면 어떻게 할까","correct":true},{"t":"급식 시간에 물을 마셔도 되나요, 안 되나요","mis":"K4-1-u2-X09"},{"t":"우리 학교 급식실을 새로 지을 수 있을까","mis":"K4-1-u2-X08"},{"t":"내가 좋아하는 반찬은 무엇일까","mis":"K4-1-u2-X10"}],"explanation":["된다 · 안 된다만 나오면?","여러 방법이 나오게","어떻게 할까로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#10','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C12',2,'mc','auto','이유를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X12','K4-1-u2-X11','K4-1-u2-X40']::text[],false,'{"seq":10,"concept":"K4-1-u2-C12","difficulty":2,"kind":"mc","stem":"이유를 바르게 말한 것은 무엇인가요?","options":[{"t":"「쉬는 시간에 창문을 열자. 교실 공기가 맑아지기 때문이야.」","correct":true},{"t":"「쉬는 시간에 창문을 열자. 왜냐하면 창문이 네 개이기 때문이야.」","mis":"K4-1-u2-X12"},{"t":"「쉬는 시간에 창문을 열자. 창문 열기가 재미있기 때문이야.」","mis":"K4-1-u2-X11"},{"t":"「쉬는 시간에 창문을 열자.」","mis":"K4-1-u2-X40"}],"explanation":["실천하면 좋아지는 점","창문 수는?","공기가 맑아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#11','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C25',2,'mc','auto','의견을 결정하는 기준으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u2-X24']::text[],false,'{"seq":11,"concept":"K4-1-u2-C25","difficulty":2,"kind":"mc","stem":"의견을 결정하는 기준으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"의견을 낸 친구가 반에서 인기가 많은가","correct":true},{"t":"시간이나 힘이 너무 많이 들지 않는가","mis":"K4-1-u2-X24"},{"t":"모든 친구가 실천할 수 있는가","mis":"K4-1-u2-X24"},{"t":"단점보다 좋은 점이 더 큰가","mis":"K4-1-u2-X24"}],"explanation":["누가 냈는지는?","기준이 아니에요.","인기는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#12','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C30',2,'mc','auto','「우리 반 게시판에는 그림이 열 장 붙어 있습니다.」의 끝말이 알려 주는 것은 무엇인가요?',ARRAY['K4-1-u2-X31']::text[],false,'{"seq":12,"concept":"K4-1-u2-C30","difficulty":2,"kind":"mc","stem":"「우리 반 게시판에는 그림이 열 장 붙어 있습니다.」의 끝말이 알려 주는 것은 무엇인가요?","options":[{"t":"있는 일을 알려 주는 사실","correct":true},{"t":"글쓴이의 생각을 나타낸 의견","mis":"K4-1-u2-X31"},{"t":"글쓴이가 바라는 것","mis":"K4-1-u2-X31"},{"t":"해야 할 일","mis":"K4-1-u2-X31"}],"explanation":["「…있습니다」","있는 것을 알려 줘요.","사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#13','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C36',2,'mc','auto','「㉯ 준비한 뒤에 열어요」에서 의견을 뒷받침하는 내용은 무엇인가요?',ARRAY['K4-1-u2-X35','K4-1-u2-X06']::text[],false,'{"seq":13,"concept":"K4-1-u2-C36","difficulty":2,"kind":"mc","stem":"「㉯ 준비한 뒤에 열어요」에서 의견을 뒷받침하는 내용은 무엇인가요?","options":[{"t":"한번 망가진 시설을 되돌리는 데에는 많은 시간과 힘이 든다","correct":true},{"t":"운동장에는 모래가 있다","mis":"K4-1-u2-X35"},{"t":"주말에는 학교에 오지 않는다","mis":"K4-1-u2-X35"},{"t":"여는 날과 시간을 정하자","mis":"K4-1-u2-X06"}],"explanation":["왜 준비하자는 걸까?","③을 봐요.","되돌리기 어려워요."],"asset":{"type":"passage","lines":["① 주말에 학교 운동장을 함부로 열면 안 됩니다.","② 사람이 많이 드나들면 시설이 상하거나 쓰레기가 늘어납니다.","③ 한번 망가진 시설을 되돌리는 데에는 많은 시간과 힘이 듭니다.","④ 여는 날과 시간을 정하고 살필 사람을 둔 뒤에 열어야 합니다."],"title":"㉯ 준비한 뒤에 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#14','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C48',2,'mc','auto','「이 글은 길어서 좋은 의견이야.」라는 평가가 알맞지 않은 까닭은 무엇인가요?',ARRAY['K4-1-u2-X46','K4-1-u2-X41','K4-1-u2-X30']::text[],false,'{"seq":14,"concept":"K4-1-u2-C48","difficulty":2,"kind":"mc","stem":"「이 글은 길어서 좋은 의견이야.」라는 평가가 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"글의 길이는 의견이 알맞은지와 상관없기 때문에","correct":true},{"t":"짧은 글이 언제나 더 좋기 때문에","mis":"K4-1-u2-X46"},{"t":"글은 평가하면 안 되기 때문에","mis":"K4-1-u2-X41"},{"t":"긴 글은 모두 틀리기 때문에","mis":"K4-1-u2-X30"}],"explanation":["길이는 기준일까요?","세 기준을 떠올려요.","상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#15','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C55',2,'mc','auto','누리집에서 결정한 까닭을 남기면 좋은 점은 무엇인가요?',ARRAY['K4-1-u2-X51','K4-1-u2-X49']::text[],false,'{"seq":15,"concept":"K4-1-u2-C55","difficulty":2,"kind":"mc","stem":"누리집에서 결정한 까닭을 남기면 좋은 점은 무엇인가요?","options":[{"t":"다른 의견을 낸 친구도 결정을 받아들일 수 있다","correct":true},{"t":"결정을 다시 바꿀 수 없게 된다","mis":"K4-1-u2-X51"},{"t":"찬성한 친구만 볼 수 있다","mis":"K4-1-u2-X49"},{"t":"다른 의견을 지울 수 있다","mis":"K4-1-u2-X49"}],"explanation":["다른 의견을 낸 친구는?","왜 정했는지 알면","받아들여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#16','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C59',2,'mc','auto','운동회 날 쓴 일기의 한 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?',ARRAY['K4-1-u2-X54','K4-1-u2-X55']::text[],false,'{"seq":16,"concept":"K4-1-u2-C59","difficulty":2,"kind":"mc","stem":"운동회 날 쓴 일기의 한 문장이에요. 띄어쓰기가 바른 것은 무엇인가요?","options":[{"t":"동생도 형만큼 잘 달린다","correct":true},{"t":"동생도 형 만큼 잘 달린다","mis":"K4-1-u2-X54"},{"t":"동생도 형만 큼 잘 달린다","mis":"K4-1-u2-X55"},{"t":"동 생도 형만큼 잘 달린다","mis":"K4-1-u2-X55"}],"explanation":["「형」은 이름","이름 뒤에는","붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#17','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C15',3,'mc','auto','「매주 화분 당번을 정하자」는 의견에 「당번이 결석하면 물을 못 준다」는 단점이 있어요. 가장 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u2-X14','K4-1-u2-X15','K4-1-u2-X13']::text[],false,'{"seq":17,"concept":"K4-1-u2-C15","difficulty":3,"kind":"mc","stem":"「매주 화분 당번을 정하자」는 의견에 「당번이 결석하면 물을 못 준다」는 단점이 있어요. 가장 알맞은 생각은 무엇인가요?","options":[{"t":"당번 다음 번호 친구가 함께 살피자고 고친다","correct":true},{"t":"단점이 있으니 화분 당번은 없던 일로 한다","mis":"K4-1-u2-X14"},{"t":"단점은 말하지 않고 넘어간다","mis":"K4-1-u2-X15"},{"t":"결석하지 말라고 당번을 혼낸다","mis":"K4-1-u2-X13"}],"explanation":["단점은 고칠 자리","대신할 사람","고쳐서 더 좋게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#18','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C31',3,'mc','auto','제목이 없는 글에서 글쓴이의 의견을 찾을 때 가장 먼저 살필 것은 무엇인가요?',ARRAY['K4-1-u2-X32','K4-1-u2-X33']::text[],false,'{"seq":18,"concept":"K4-1-u2-C31","difficulty":3,"kind":"mc","stem":"제목이 없는 글에서 글쓴이의 의견을 찾을 때 가장 먼저 살필 것은 무엇인가요?","options":[{"t":"되풀이되는 표현과 생각을 나타내는 끝말","correct":true},{"t":"글의 줄 수","mis":"K4-1-u2-X32"},{"t":"가장 어려운 낱말","mis":"K4-1-u2-X32"},{"t":"맨 마지막 문장 하나","mis":"K4-1-u2-X33"}],"explanation":["제목이 없으면?","되풀이 · 끝말","다른 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#19','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C40',3,'mc','auto','㉮와 ㉯를 뒷받침까지 견준 것은 무엇인가요?',ARRAY['K4-1-u2-X38','K4-1-u2-X46']::text[],false,'{"seq":19,"concept":"K4-1-u2-C40","difficulty":3,"kind":"mc","stem":"㉮와 ㉯를 뒷받침까지 견준 것은 무엇인가요?","options":[{"t":"㉮는 사람이 드나들면 잘 살펴진다고 보고, ㉯는 시설이 상한다고 보아 여는 방법이 다르다","correct":true},{"t":"㉮와 ㉯는 다르다","mis":"K4-1-u2-X38"},{"t":"둘 다 운동장 이야기니 같다","mis":"K4-1-u2-X38"},{"t":"㉯가 짧으니 ㉮가 맞다","mis":"K4-1-u2-X46"}],"explanation":["같은 일, 다른 눈","사람이 드나드는 일","까닭까지 견줘요."],"asset":{"type":"passage","lines":["① 주말에 학교 운동장을 함부로 열면 안 됩니다.","② 사람이 많이 드나들면 시설이 상하거나 쓰레기가 늘어납니다.","③ 한번 망가진 시설을 되돌리는 데에는 많은 시간과 힘이 듭니다.","④ 여는 날과 시간을 정하고 살필 사람을 둔 뒤에 열어야 합니다."],"title":"㉯ 준비한 뒤에 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#20','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C50',3,'mc','auto','같은 글을 읽고 친구와 내 평가가 달라요. 가장 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u2-X48','K4-1-u2-X24']::text[],false,'{"seq":20,"concept":"K4-1-u2-C50","difficulty":3,"kind":"mc","stem":"같은 글을 읽고 친구와 내 평가가 달라요. 가장 알맞은 생각은 무엇인가요?","options":[{"t":"보는 눈에 따라 다를 수 있으니 서로 어떤 까닭으로 그렇게 보았는지 말해 본다","correct":true},{"t":"둘 가운데 하나는 반드시 틀렸다","mis":"K4-1-u2-X48"},{"t":"까닭은 말하지 않고 아무 쪽이나 정한다","mis":"K4-1-u2-X48"},{"t":"목소리가 큰 쪽을 따른다","mis":"K4-1-u2-X24"}],"explanation":["답은 하나일까요?","그래도 까닭이 있어야","까닭을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#21','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C24',3,'mc','auto','「회장이 낸 의견이니까 무조건 좋은 의견이야.」에 대해 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u2-X24','K4-1-u2-X23','K4-1-u2-X22']::text[],false,'{"seq":21,"concept":"K4-1-u2-C24","difficulty":3,"kind":"mc","stem":"「회장이 낸 의견이니까 무조건 좋은 의견이야.」에 대해 알맞은 생각은 무엇인가요?","options":[{"t":"누가 냈는지보다 주제에 알맞은지, 실천할 수 있는지 등 내용을 따져야 한다","correct":true},{"t":"회장의 의견은 언제나 알맞다","mis":"K4-1-u2-X24"},{"t":"회장의 의견은 따져 보면 안 된다","mis":"K4-1-u2-X23"},{"t":"회장의 의견은 언제나 반대해야 한다","mis":"K4-1-u2-X22"}],"explanation":["누가 아니라","무엇을","내용을 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#22','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C61',3,'mc','auto','「꽃」을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X57']::text[],false,'{"seq":22,"concept":"K4-1-u2-C61","difficulty":3,"kind":"mc","stem":"「꽃」을 바르게 말한 것은 무엇인가요?","options":[{"t":"「식물」 안에 들면서 「개나리 · 장미」를 품는 말이다","correct":true},{"t":"「장미」보다 좁은 무리이다","mis":"K4-1-u2-X57"},{"t":"「식물」보다 넓은 무리이다","mis":"K4-1-u2-X57"},{"t":"「개나리」 안에 드는 말이다","mis":"K4-1-u2-X57"}],"explanation":["꽃은 식물일까요?","장미는 꽃일까요?","가운데 자리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#23','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C16',4,'essay','teacher','「학급 책꽂이 문제」를 토의할 때 토의 절차 네 단계에서 각각 무엇을 하는지 차례대로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u2-C16","difficulty":4,"kind":"essay","stem":"「학급 책꽂이 문제」를 토의할 때 토의 절차 네 단계에서 각각 무엇을 하는지 차례대로 쓰세요.","answer_guide":{"answer":"예: 주제 정하기 — 책이 자꾸 없어지는 문제를 어떻게 해결할지로 정한다. 의견 마련하기 — 내 의견과 이유, 단점을 준비한다. 의견 모으기 — 차례로 말하고 친구 의견을 듣고 정리한다. 의견 결정하기 — 기준을 세워 가장 알맞은 의견을 고르거나 합친다.","scoring_points":["네 단계를 차례대로 썼는가","단계마다 하는 일을 썼는가","결정 단계에서 기준을 세운다고 썼는가"]},"explanation":["주제 → 마련","모으기 → 결정","단계마다 할 일"],"asset":{"type":"speech","turns":[{"who":"시온","text":"오늘 주제는 「학급 책꽂이의 책이 자꾸 없어지는 문제를 어떻게 해결할까」입니다. 유진이부터 말해 주세요."},{"who":"유진","text":"빌려 가는 사람이 공책에 이름과 날짜를 적으면 좋겠습니다. 누가 가져갔는지 알 수 있기 때문입니다."},{"who":"지민","text":"책마다 반 이름 붙임딱지를 붙이면 좋겠습니다. 다른 반에 섞여도 찾아올 수 있기 때문입니다."},{"who":"예준","text":"책꽂이를 예쁘게 칠하면 좋겠습니다. 왜냐하면 저는 초록색을 좋아하기 때문입니다."},{"who":"시온","text":"아직 말하지 않은 친구도 있으니 차례대로 더 들어 보겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#24','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C31',4,'essay','teacher','「㉮ 주말에는 운동장을 열어요」에서 글쓴이의 의견을 쓰고, 그 의견을 찾는 데 도움이 된 방법 두 가지를 들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u2-C31","difficulty":4,"kind":"essay","stem":"「㉮ 주말에는 운동장을 열어요」에서 글쓴이의 의견을 쓰고, 그 의견을 찾는 데 도움이 된 방법 두 가지를 들어 쓰세요.","answer_guide":{"answer":"예: 의견 — 주말에도 학교 운동장을 마을 사람들에게 열자. 제목 「주말에는 운동장을 열어요」에 생각이 담겨 있고, 「열다」라는 말이 첫 문장과 마지막 문장에 되풀이되기 때문이다.","scoring_points":["글쓴이의 의견을 바르게 썼는가","찾는 방법 두 가지를 들었는가","글에서 근거를 찾아 설명했는가"]},"explanation":["의견 한 문장","제목 · 되풀이","글에서 근거"],"asset":{"type":"passage","lines":["① 주말에도 학교 운동장을 마을 사람들에게 열었으면 좋겠습니다.","② 우리 마을에는 아이들이 마음 놓고 뛸 만한 넓은 터가 없습니다.","③ 운동장을 열면 마을 사람들이 함께 운동할 곳이 생깁니다.","④ 사람이 자주 드나드는 곳은 오히려 눈길이 닿아 잘 살펴집니다.","⑤ 직접 써 본 곳에는 남다른 정이 들어 아끼는 사람이 늘어납니다.","⑥ 운동장을 여는 일은 학교와 마을이 함께 사는 길입니다."],"title":"㉮ 주말에는 운동장을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_b#25','kor',4,1,'u2','','g4_1_kor_u2_review_b','unit_review','K4-1-u2-C39',4,'essay','teacher','「마을에 밥집을 만들어요」와 예준이 · 지민이 · 유진이의 생각을 견주어 같은 점과 다른 점을 쓰고, 내 의견을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u2-C39","difficulty":4,"kind":"essay","stem":"「마을에 밥집을 만들어요」와 예준이 · 지민이 · 유진이의 생각을 견주어 같은 점과 다른 점을 쓰고, 내 의견을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 같은 점 — 모두 마을의 고양이 문제를 해결하고 싶어 한다. 다른 점 — 글쓴이는 밥집이 골목을 깨끗하게 한다고 보지만, 지민이는 치울 사람이 없으면 더 지저분해진다고 본다. 내 의견 — 돌볼 사람을 정한 뒤 밥집을 두자. 걱정을 줄이면서 고양이도 돌볼 수 있기 때문이다.","scoring_points":["같은 점을 썼는가","다른 점을 뒷받침과 함께 썼는가","내 의견과 까닭을 썼는가"]},"explanation":["같은 점","다른 점과 까닭","내 의견"],"asset":{"type":"speech","turns":[{"who":"예준","text":"밥집 둘레에 고양이가 모여 밤에 시끄러울 수 있어요."},{"who":"지민","text":"밥그릇을 치울 사람이 없으면 오히려 지저분해져요."},{"who":"유진","text":"돌볼 사람을 정하고 자리를 잘 고르면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#1','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C5',1,'mc','auto','혼자 정하면 되는 일이라 토의가 필요 없는 것은 무엇인가요?',ARRAY['K4-1-u2-X04']::text[],false,'{"seq":1,"concept":"K4-1-u2-C5","difficulty":1,"kind":"mc","stem":"혼자 정하면 되는 일이라 토의가 필요 없는 것은 무엇인가요?","options":[{"t":"오늘 내 필통에 연필을 몇 자루 넣을까","correct":true},{"t":"우리 반 이름을 무엇으로 정할까","mis":"K4-1-u2-X04"},{"t":"우리 반 청소 구역을 어떻게 나눌까","mis":"K4-1-u2-X04"},{"t":"현장 체험 학습에서 모둠을 어떻게 짤까","mis":"K4-1-u2-X04"}],"explanation":["내 필통은 누구의 일인가요?","혼자 정해요.","토의가 필요 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#2','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C17',1,'mc','auto','「의견 모으기」 단계에서 하는 일은 무엇인가요?',ARRAY['K4-1-u2-X17','K4-1-u2-X18']::text[],false,'{"seq":2,"concept":"K4-1-u2-C17","difficulty":1,"kind":"mc","stem":"「의견 모으기」 단계에서 하는 일은 무엇인가요?","options":[{"t":"차례로 말하고 친구의 의견을 듣고 정리한다","correct":true},{"t":"가장 알맞은 의견 하나를 바로 고른다","mis":"K4-1-u2-X17"},{"t":"토의 주제를 처음부터 다시 정한다","mis":"K4-1-u2-X17"},{"t":"시간이 걸리니 건너뛴다","mis":"K4-1-u2-X18"}],"explanation":["모으기는","말하고 듣고","정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
