INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#5','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C34',1,'mc','auto','「오래 쓸수록 좋아요」의 글쓴이의 의견은 무엇인가요?',ARRAY['K4-1-u2-X06']::text[],false,'{"seq":5,"concept":"K4-1-u2-C34","difficulty":1,"kind":"mc","stem":"「오래 쓸수록 좋아요」의 글쓴이의 의견은 무엇인가요?","options":[{"t":"한번 산 물건을 오래 쓰자","correct":true},{"t":"여러 번 쓰는 물건을 많이 사자","mis":"K4-1-u2-X06"},{"t":"물병을 쓰지 말자","mis":"K4-1-u2-X06"},{"t":"장바구니를 여러 개 모으자","mis":"K4-1-u2-X06"}],"explanation":["제목을 봐요.","⑦의 「필요합니다」","오래 쓰자예요."],"asset":{"type":"passage","lines":["① 환경을 지키려고 우리는 여러 번 쓸 수 있는 물건을 씁니다.","② 물병이나 장바구니가 그러한 물건입니다.","③ 그런데 여러 번 쓰는 물건이라고 언제나 환경을 지키는 것은 아닙니다.","④ 사 두고 쓰지 않거나 여러 개 모으면 오히려 환경을 해칩니다.","⑤ 여러 번 쓰는 물건은 만들 때 더 많은 힘과 재료가 듭니다.","⑥ 오래 쓸수록 그만큼 환경을 지키는 힘이 커집니다.","⑦ 한번 산 물건을 오래 쓰는 버릇이 필요합니다."],"title":"오래 쓸수록 좋아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
