INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#14','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C47',2,'mc','auto','「교실에서 강아지를 기르자」라는 의견을 「그대로 했을 때 다른 문제가 생기지 않는가」로 평가하면 떠올릴 수 있는 것은 무엇인가요?',ARRAY['K4-1-u2-X45','K4-1-u2-X46','K4-1-u2-X43']::text[],false,'{"seq":14,"concept":"K4-1-u2-C47","difficulty":2,"kind":"mc","stem":"「교실에서 강아지를 기르자」라는 의견을 「그대로 했을 때 다른 문제가 생기지 않는가」로 평가하면 떠올릴 수 있는 것은 무엇인가요?","options":[{"t":"털 때문에 힘든 친구가 있을 수 있다","correct":true},{"t":"강아지는 귀엽다","mis":"K4-1-u2-X45"},{"t":"이 의견을 낸 친구와 나는 친하다","mis":"K4-1-u2-X46"},{"t":"강아지는 다리가 네 개이다","mis":"K4-1-u2-X43"}],"explanation":["그대로 하면?","생길 문제","털이 힘든 친구"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#15','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C53',2,'mc','auto','누리집 예절을 지킨 댓글은 무엇인가요?',ARRAY['K4-1-u2-X23','K4-1-u2-X22','K4-1-u2-X49']::text[],false,'{"seq":15,"concept":"K4-1-u2-C53","difficulty":2,"kind":"mc","stem":"누리집 예절을 지킨 댓글은 무엇인가요?","options":[{"t":"모두 함께할 수 있어 좋아요. 비가 오면 어디서 할지도 정하면 좋겠어요.","correct":true},{"t":"그런 걸 왜 해요?","mis":"K4-1-u2-X23"},{"t":"제 의견이 아니라서 반대예요.","mis":"K4-1-u2-X22"},{"t":"누가 쓴 거예요? 웃기네요.","mis":"K4-1-u2-X49"}],"explanation":["좋은 점 먼저","고칠 점은 부드럽게","까닭도 함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#16','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C58',2,'mc','auto','「배운(대로) 해 보자」의 밑줄 친 부분을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-1-u2-X53','K4-1-u2-X55']::text[],false,'{"seq":16,"concept":"K4-1-u2-C58","difficulty":2,"kind":"mc","stem":"「배운(대로) 해 보자」의 밑줄 친 부분을 바르게 쓴 것은 무엇인가요?","options":[{"t":"배운 대로","correct":true},{"t":"배운대로","mis":"K4-1-u2-X53"},{"t":"배 운대로","mis":"K4-1-u2-X55"},{"t":"배운 대 로","mis":"K4-1-u2-X55"}],"explanation":["「배운」은 「-ㄴ」","「대로」는","띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#17','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C13',3,'mc','auto','의견을 마련하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X16','K4-1-u2-X15','K4-1-u2-X14']::text[],false,'{"seq":17,"concept":"K4-1-u2-C13","difficulty":3,"kind":"mc","stem":"의견을 마련하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"의견 떠올리기 → 실천 가능성 생각하기 → 이유 마련하기 → 단점 생각하기","correct":true},{"t":"이유 마련하기 → 의견 떠올리기 → 단점 생각하기 → 실천 가능성 생각하기","mis":"K4-1-u2-X16"},{"t":"의견 떠올리기 → 이유 마련하기 → 끝내기","mis":"K4-1-u2-X15"},{"t":"단점 생각하기 → 의견 버리기","mis":"K4-1-u2-X14"}],"explanation":["의견부터","할 수 있나 · 왜","단점도 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#18','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C33',3,'mc','auto','글쓴이의 의견을 파악하는 것이 「비교」와 「평가」의 첫걸음인 까닭은 무엇인가요?',ARRAY['K4-1-u2-X34','K4-1-u2-X39','K4-1-u2-X41']::text[],false,'{"seq":18,"concept":"K4-1-u2-C33","difficulty":3,"kind":"mc","stem":"글쓴이의 의견을 파악하는 것이 「비교」와 「평가」의 첫걸음인 까닭은 무엇인가요?","options":[{"t":"의견을 알아야 내 의견과 견주고 알맞은지 따질 수 있기 때문에","correct":true},{"t":"의견을 외워야 시험을 잘 보기 때문에","mis":"K4-1-u2-X34"},{"t":"의견을 찾으면 글쓴이를 이길 수 있기 때문에","mis":"K4-1-u2-X39"},{"t":"의견을 찾으면 더 따질 것이 없기 때문에","mis":"K4-1-u2-X41"}],"explanation":["무엇을 견주나요?","알아야 견줘요.","파악 → 비교 → 평가"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#19','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C38',3,'mc','auto','「㉮ 주말에는 운동장을 열어요」와 다른 의견은 무엇인가요?',ARRAY['K4-1-u2-X36']::text[],false,'{"seq":19,"concept":"K4-1-u2-C38","difficulty":3,"kind":"mc","stem":"「㉮ 주말에는 운동장을 열어요」와 다른 의견은 무엇인가요?","options":[{"t":"살필 사람이 없다면 주말에는 열지 않는 편이 낫다","correct":true},{"t":"운동장을 열면 함께 운동할 곳이 생긴다","mis":"K4-1-u2-X36"},{"t":"직접 써 본 곳에는 정이 든다","mis":"K4-1-u2-X36"},{"t":"운동장을 여는 일은 함께 사는 길이다","mis":"K4-1-u2-X36"}],"explanation":["㉮는 열자고 했어요.","어긋나는 말","열지 말자예요."],"asset":{"type":"passage","lines":["① 주말에도 학교 운동장을 마을 사람들에게 열었으면 좋겠습니다.","② 우리 마을에는 아이들이 마음 놓고 뛸 만한 넓은 터가 없습니다.","③ 운동장을 열면 마을 사람들이 함께 운동할 곳이 생깁니다.","④ 사람이 자주 드나드는 곳은 오히려 눈길이 닿아 잘 살펴집니다.","⑤ 직접 써 본 곳에는 남다른 정이 들어 아끼는 사람이 늘어납니다.","⑥ 운동장을 여는 일은 학교와 마을이 함께 사는 길입니다."],"title":"㉮ 주말에는 운동장을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#20','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C49',3,'mc','auto','「주말에 운동장을 함부로 열면 안 됩니다.」라는 첫 문장만 읽고 내린 판단으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u2-X47']::text[],false,'{"seq":20,"concept":"K4-1-u2-C49","difficulty":3,"kind":"mc","stem":"「주말에 운동장을 함부로 열면 안 됩니다.」라는 첫 문장만 읽고 내린 판단으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"㉯는 운동장을 절대 열지 말자는 글이다","correct":true},{"t":"㉯는 끝까지 읽어 보아야 의견을 알 수 있다","mis":"K4-1-u2-X47"},{"t":"㉯는 「함부로」 여는 것을 걱정한다","mis":"K4-1-u2-X47"},{"t":"㉯는 준비하는 방법도 말할 것 같다","mis":"K4-1-u2-X47"}],"explanation":["「함부로」","④까지 읽어요.","절대는 지나쳐요."],"asset":{"type":"passage","lines":["① 주말에 학교 운동장을 함부로 열면 안 됩니다.","② 사람이 많이 드나들면 시설이 상하거나 쓰레기가 늘어납니다.","③ 한번 망가진 시설을 되돌리는 데에는 많은 시간과 힘이 듭니다.","④ 여는 날과 시간을 정하고 살필 사람을 둔 뒤에 열어야 합니다."],"title":"㉯ 준비한 뒤에 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#21','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C22',3,'mc','auto','모은 의견이 알맞은지 판단할 때 살필 네 가지로 알맞게 묶은 것은 무엇인가요?',ARRAY['K4-1-u2-X24','K4-1-u2-X05','K4-1-u2-X14']::text[],false,'{"seq":21,"concept":"K4-1-u2-C22","difficulty":3,"kind":"mc","stem":"모은 의견이 알맞은지 판단할 때 살필 네 가지로 알맞게 묶은 것은 무엇인가요?","options":[{"t":"주제에 알맞은가 · 모두 실천할 수 있는가 · 이유가 알맞은가 · 단점도 생각했는가","correct":true},{"t":"누가 냈는가 · 먼저 냈는가 · 크게 말했는가 · 친한가","mis":"K4-1-u2-X24"},{"t":"주제에 알맞은가 · 가장 길게 말했는가 · 재미있는가 · 이겼는가","mis":"K4-1-u2-X05"},{"t":"이유가 알맞은가 · 단점이 하나도 없는가 · 먼저 냈는가 · 크게 말했는가","mis":"K4-1-u2-X14"}],"explanation":["내용을 보는 네 가지","누가 · 언제는 아니에요.","주제 · 실천 · 이유 · 단점"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#22','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C58',3,'mc','auto','띄어쓰기가 모두 바른 문장은 무엇인가요?',ARRAY['K4-1-u2-X54','K4-1-u2-X53']::text[],false,'{"seq":22,"concept":"K4-1-u2-C58","difficulty":3,"kind":"mc","stem":"띄어쓰기가 모두 바른 문장은 무엇인가요?","options":[{"t":"나는 나대로 들은 대로 적었다","correct":true},{"t":"나는 나 대로 들은 대로 적었다","mis":"K4-1-u2-X54"},{"t":"나는 나대로 들은대로 적었다","mis":"K4-1-u2-X53"},{"t":"나는 나 대로 들은대로 적었다","mis":"K4-1-u2-X53"}],"explanation":["「나」 뒤는 붙여요.","「들은」 뒤는 띄어요.","둘 다 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#23','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C15',4,'essay','teacher','「쉬는 시간에 교실에서 공기놀이 대회를 열자」라는 의견을 마련하는 차례에 따라 이유 · 단점 · 고친 의견을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u2-C15","difficulty":4,"kind":"essay","stem":"「쉬는 시간에 교실에서 공기놀이 대회를 열자」라는 의견을 마련하는 차례에 따라 이유 · 단점 · 고친 의견을 쓰세요.","answer_guide":{"answer":"예: 이유 — 여럿이 함께 놀며 친해질 수 있기 때문이다. 단점 — 공기놀이를 못 하는 친구는 재미가 없을 수 있다. 고친 의견 — 공기놀이와 실뜨기 가운데 하고 싶은 것을 골라 하는 놀이 시간을 만들자.","scoring_points":["의견과 이어지는 이유를 썼는가","단점을 찾았는가","단점을 고친 의견을 썼는가"]},"explanation":["이유","단점","고친 의견"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#24','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C32',4,'essay','teacher','「글쓴이의 의견은 언제나 마지막 문장에 있다.」라는 말이 알맞지 않은 까닭을 이 단원에서 읽은 글을 예로 들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u2-C32","difficulty":4,"kind":"essay","stem":"「글쓴이의 의견은 언제나 마지막 문장에 있다.」라는 말이 알맞지 않은 까닭을 이 단원에서 읽은 글을 예로 들어 쓰세요.","answer_guide":{"answer":"예: 「㉰ 먹을 만큼 받아요」는 첫 문장 「급식은 먹을 만큼만 받았으면 좋겠습니다」에 의견이 있고, 「㉮ 주말에는 운동장을 열어요」도 첫 문장에 의견이 있다. 의견의 자리는 정해져 있지 않아 글 전체를 살펴야 한다.","scoring_points":["알맞지 않다고 밝혔는가","첫 문장 등에 의견이 있는 글을 예로 들었는가","글 전체를 살펴야 한다고 썼는가"]},"explanation":["예가 되는 글","첫 문장에 의견","글 전체를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_c#25','kor',4,1,'u2','','g4_1_kor_u2_review_c','unit_review','K4-1-u2-C51',4,'essay','teacher','㉰와 ㉱를 읽고 두 글의 걱정을 함께 담은 방법을 하나 제안하고, 그 방법이 두 글의 걱정을 어떻게 덜어 주는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u2-C51","difficulty":4,"kind":"essay","stem":"㉰와 ㉱를 읽고 두 글의 걱정을 함께 담은 방법을 하나 제안하고, 그 방법이 두 글의 걱정을 어떻게 덜어 주는지 쓰세요.","answer_guide":{"answer":"예: 배식대 앞에 「조금 · 보통 · 많이」 카드를 두어 처음에 받을 양을 고르게 하자. 처음부터 알맞게 받으니 음식을 덜 남기고(㉰의 걱정), 두 번씩 줄을 서지 않아도 되니 붐비지 않는다(㉱의 걱정).","scoring_points":["방법을 하나 제안했는가","㉰의 걱정을 덜어 주는 점을 썼는가","㉱의 걱정을 덜어 주는 점을 썼는가"]},"explanation":["방법 하나","㉰의 걱정","㉱의 걱정"],"asset":{"type":"passage","lines":["① 모두가 두 번씩 줄을 서면 배식대 앞이 붐빕니다.","② 그러면 늦게 받는 친구는 점심을 서둘러 먹어야 합니다.","③ 처음부터 알맞게 받을 수 있도록 양을 미리 말해 주면 좋겠습니다."],"title":"㉱ 처음부터 알맞게 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#1','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C2',1,'mc','auto','「서로 다른 의견」 단원에서 다른 의견을 보는 눈으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X02','K4-1-u2-X22']::text[],false,'{"seq":1,"concept":"K4-1-u2-C2","difficulty":1,"kind":"mc","stem":"「서로 다른 의견」 단원에서 다른 의견을 보는 눈으로 알맞은 것은 무엇인가요?","options":[{"t":"더 좋은 답을 찾는 열쇠이다","correct":true},{"t":"다투는 까닭이다","mis":"K4-1-u2-X02"},{"t":"나오지 않게 막아야 하는 것이다","mis":"K4-1-u2-X02"},{"t":"틀린 생각이다","mis":"K4-1-u2-X22"}],"explanation":["다름은 다툼일까요?","견주면 생각이 자라요.","열쇠예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#2','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C16',1,'mc','auto','토의 절차에서 첫째로 할 일은 무엇인가요?',ARRAY['K4-1-u2-X17']::text[],false,'{"seq":2,"concept":"K4-1-u2-C16","difficulty":1,"kind":"mc","stem":"토의 절차에서 첫째로 할 일은 무엇인가요?","options":[{"t":"함께 해결해야 할 일을 찾아 토의 주제를 정한다","correct":true},{"t":"기준을 세워 의견을 결정한다","mis":"K4-1-u2-X17"},{"t":"친구들의 의견을 모은다","mis":"K4-1-u2-X17"},{"t":"결정한 까닭을 남긴다","mis":"K4-1-u2-X17"}],"explanation":["무엇에 대해 말할지","주제가 먼저","주제 정하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#3','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C19',1,'mc','auto','토의에서 말이 적은 친구가 있을 때 사회자가 할 일은 무엇인가요?',ARRAY['K4-1-u2-X20','K4-1-u2-X19']::text[],false,'{"seq":3,"concept":"K4-1-u2-C19","difficulty":1,"kind":"mc","stem":"토의에서 말이 적은 친구가 있을 때 사회자가 할 일은 무엇인가요?","options":[{"t":"그 친구에게도 말할 기회를 나누어 준다","correct":true},{"t":"말이 적은 친구는 그냥 둔다","mis":"K4-1-u2-X20"},{"t":"말을 많이 한 친구에게 한 번 더 시킨다","mis":"K4-1-u2-X20"},{"t":"사회자가 대신 의견을 정해 준다","mis":"K4-1-u2-X19"}],"explanation":["기회는 고르게","모두가 말해요.","나누어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#4','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C28',1,'mc','auto','사실을 따지는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X30','K4-1-u2-X41']::text[],false,'{"seq":4,"concept":"K4-1-u2-C28","difficulty":1,"kind":"mc","stem":"사실을 따지는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"맞는지 따져 본다","correct":true},{"t":"알맞은지 따져 본다","mis":"K4-1-u2-X30"},{"t":"따지지 않고 믿는다","mis":"K4-1-u2-X41"},{"t":"좋은지 싫은지 정한다","mis":"K4-1-u2-X30"}],"explanation":["있었던 일 · 있는 일","확인할 수 있어요.","맞는지 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#5','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C6',1,'mc','auto','「㉮ 주말에는 운동장을 열어요」의 글쓴이의 의견은 무엇인가요?',ARRAY['K4-1-u2-X47','K4-1-u2-X08','K4-1-u2-X06']::text[],false,'{"seq":5,"concept":"K4-1-u2-C6","difficulty":1,"kind":"mc","stem":"「㉮ 주말에는 운동장을 열어요」의 글쓴이의 의견은 무엇인가요?","options":[{"t":"주말에도 학교 운동장을 마을 사람들에게 열자","correct":true},{"t":"주말에는 운동장을 잠그자","mis":"K4-1-u2-X47"},{"t":"운동장을 더 넓히자","mis":"K4-1-u2-X08"},{"t":"마을에 새 운동장을 짓자","mis":"K4-1-u2-X06"}],"explanation":["①을 봐요.","첫 문장에 의견이","열자예요."],"asset":{"type":"passage","lines":["① 주말에도 학교 운동장을 마을 사람들에게 열었으면 좋겠습니다.","② 우리 마을에는 아이들이 마음 놓고 뛸 만한 넓은 터가 없습니다.","③ 운동장을 열면 마을 사람들이 함께 운동할 곳이 생깁니다.","④ 사람이 자주 드나드는 곳은 오히려 눈길이 닿아 잘 살펴집니다.","⑤ 직접 써 본 곳에는 남다른 정이 들어 아끼는 사람이 늘어납니다.","⑥ 운동장을 여는 일은 학교와 마을이 함께 사는 길입니다."],"title":"㉮ 주말에는 운동장을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#6','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C44',1,'mc','auto','「옛 성벽을 잘 ( ) 하여 다음 세대에 물려주자.」의 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K4-1-u2-X42']::text[],false,'{"seq":6,"concept":"K4-1-u2-C44","difficulty":1,"kind":"mc","stem":"「옛 성벽을 잘 ( ) 하여 다음 세대에 물려주자.」의 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"보존","correct":true},{"t":"훼손","mis":"K4-1-u2-X42"},{"t":"개방","mis":"K4-1-u2-X42"},{"t":"반박","mis":"K4-1-u2-X42"}],"explanation":["물려주려면?","잘 지켜요.","보존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#7','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C59',1,'mc','auto','「선생님」과 「만큼」이 들어간 문장을 바르게 띄어 쓴 것은 무엇인가요?',ARRAY['K4-1-u2-X54','K4-1-u2-X55']::text[],false,'{"seq":7,"concept":"K4-1-u2-C59","difficulty":1,"kind":"mc","stem":"「선생님」과 「만큼」이 들어간 문장을 바르게 띄어 쓴 것은 무엇인가요?","options":[{"t":"나는 선생님만큼 키가 크다","correct":true},{"t":"나는 선생님 만큼 키가 크다","mis":"K4-1-u2-X54"},{"t":"나는 선생 님만큼 키가 크다","mis":"K4-1-u2-X55"},{"t":"나는 선생님만 큼 키가 크다","mis":"K4-1-u2-X55"}],"explanation":["「선생님」은 사람을 부르는 이름","이름 뒤에는","붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#8','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C60',1,'mc','auto','「메뚜기 · 모기 · 잠자리」를 함께 묶는 넓은 무리는 무엇인가요?',ARRAY['K4-1-u2-X57','K4-1-u2-X56']::text[],false,'{"seq":8,"concept":"K4-1-u2-C60","difficulty":1,"kind":"mc","stem":"「메뚜기 · 모기 · 잠자리」를 함께 묶는 넓은 무리는 무엇인가요?","options":[{"t":"곤충","correct":true},{"t":"새","mis":"K4-1-u2-X57"},{"t":"물고기","mis":"K4-1-u2-X56"},{"t":"탈것","mis":"K4-1-u2-X56"}],"explanation":["다리가 여섯 개","모두 작은 벌레","곤충이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#9','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C8',2,'mc','auto','토의 주제의 세 조건이 아닌 것은 무엇인가요?',ARRAY['K4-1-u2-X09']::text[],false,'{"seq":9,"concept":"K4-1-u2-C8","difficulty":2,"kind":"mc","stem":"토의 주제의 세 조건이 아닌 것은 무엇인가요?","options":[{"t":"선생님이 정해 준 일인가","correct":true},{"t":"우리 모두와 관련 있는가","mis":"K4-1-u2-X09"},{"t":"여러 가지 의견이 나올 수 있는가","mis":"K4-1-u2-X09"},{"t":"우리가 해결 방법을 찾을 수 있는가","mis":"K4-1-u2-X09"}],"explanation":["세 조건을 떠올려요.","모두 · 여러 · 해결","누가 정했는지는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#10','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C12',2,'mc','auto','「책꽂이 토의」에서 이유가 알맞지 않은 친구는 누구인가요?',ARRAY['K4-1-u2-X11','K4-1-u2-X12']::text[],false,'{"seq":10,"concept":"K4-1-u2-C12","difficulty":2,"kind":"mc","stem":"「책꽂이 토의」에서 이유가 알맞지 않은 친구는 누구인가요?","options":[{"t":"예준","correct":true},{"t":"유진","mis":"K4-1-u2-X11"},{"t":"지민","mis":"K4-1-u2-X11"},{"t":"알맞지 않은 친구는 없다","mis":"K4-1-u2-X12"}],"explanation":["초록색을 좋아하는 것과","책이 없어지는 것","이어지지 않아요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"오늘 주제는 「학급 책꽂이의 책이 자꾸 없어지는 문제를 어떻게 해결할까」입니다. 유진이부터 말해 주세요."},{"who":"유진","text":"빌려 가는 사람이 공책에 이름과 날짜를 적으면 좋겠습니다. 누가 가져갔는지 알 수 있기 때문입니다."},{"who":"지민","text":"책마다 반 이름 붙임딱지를 붙이면 좋겠습니다. 다른 반에 섞여도 찾아올 수 있기 때문입니다."},{"who":"예준","text":"책꽂이를 예쁘게 칠하면 좋겠습니다. 왜냐하면 저는 초록색을 좋아하기 때문입니다."},{"who":"시온","text":"아직 말하지 않은 친구도 있으니 차례대로 더 들어 보겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#11','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C25',2,'mc','auto','「모든 친구가 실천할 수 있는가」라는 기준으로 보았을 때 가장 알맞은 의견은 무엇인가요?',ARRAY['K4-1-u2-X13','K4-1-u2-X50']::text[],false,'{"seq":11,"concept":"K4-1-u2-C25","difficulty":2,"kind":"mc","stem":"「모든 친구가 실천할 수 있는가」라는 기준으로 보았을 때 가장 알맞은 의견은 무엇인가요?","options":[{"t":"쉬는 시간이 끝나면 자기 자리 둘레를 한 번씩 살피자","correct":true},{"t":"날마다 한 시간씩 일찍 와서 청소하자","mis":"K4-1-u2-X13"},{"t":"청소를 가장 잘하는 한 친구에게 다 맡기자","mis":"K4-1-u2-X13"},{"t":"청소 기계를 사서 쓰자","mis":"K4-1-u2-X50"}],"explanation":["모두가 할 수 있나요?","짧고 쉬운 일","자리 둘레 살피기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#12','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C30',2,'mc','auto','「…라고 생각합니다」로 끝나는 문장은 주로 무엇을 나타내나요?',ARRAY['K4-1-u2-X31']::text[],false,'{"seq":12,"concept":"K4-1-u2-C30","difficulty":2,"kind":"mc","stem":"「…라고 생각합니다」로 끝나는 문장은 주로 무엇을 나타내나요?","options":[{"t":"글쓴이의 생각(의견)","correct":true},{"t":"있었던 일(사실)","mis":"K4-1-u2-X31"},{"t":"글의 제목","mis":"K4-1-u2-X31"},{"t":"글을 쓴 날짜","mis":"K4-1-u2-X31"}],"explanation":["「생각합니다」","글쓴이의 생각","의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#13','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C36',2,'mc','auto','「㉰ 먹을 만큼 받아요」의 뒷받침 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X35','K4-1-u2-X06']::text[],false,'{"seq":13,"concept":"K4-1-u2-C36","difficulty":2,"kind":"mc","stem":"「㉰ 먹을 만큼 받아요」의 뒷받침 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"다 먹지 못하고 남긴 음식은 모두 버려진다","correct":true},{"t":"급식실은 일 층에 있다","mis":"K4-1-u2-X35"},{"t":"오늘 반찬은 생선이다","mis":"K4-1-u2-X35"},{"t":"급식은 먹을 만큼만 받자","mis":"K4-1-u2-X06"}],"explanation":["왜 먹을 만큼?","남기면 어떻게 되나요?","버려져요."],"asset":{"type":"passage","lines":["① 급식은 먹을 만큼만 받았으면 좋겠습니다.","② 다 먹지 못하고 남긴 음식은 모두 버려집니다.","③ 받은 만큼 다 먹으면 스스로 해냈다는 뿌듯함도 생깁니다.","④ 누가 그러는데 남긴 음식은 모두 바다에 버린다고 합니다.","⑤ 처음에는 조금 받고, 모자라면 더 받으러 가면 됩니다."],"title":"㉰ 먹을 만큼 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#14','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C41',2,'mc','auto','남의 의견을 평가해야 하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X39','K4-1-u2-X41']::text[],false,'{"seq":14,"concept":"K4-1-u2-C41","difficulty":2,"kind":"mc","stem":"남의 의견을 평가해야 하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"알맞은지 따져 보지 않고 따르면 일을 그르칠 수 있기 때문에","correct":true},{"t":"남의 의견은 언제나 틀리기 때문에","mis":"K4-1-u2-X39"},{"t":"평가하면 글쓴이를 이길 수 있기 때문에","mis":"K4-1-u2-X39"},{"t":"따져 보지 않고 따르는 것이 빠르기 때문에","mis":"K4-1-u2-X41"}],"explanation":["당나귀 이야기","그대로 따르면?","일을 그르쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#15','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C54',2,'mc','auto','학급의 날 활동으로 더 좋은 의견은 무엇인가요?',ARRAY['K4-1-u2-X50','K4-1-u2-X54']::text[],false,'{"seq":15,"concept":"K4-1-u2-C54","difficulty":2,"kind":"mc","stem":"학급의 날 활동으로 더 좋은 의견은 무엇인가요?","options":[{"t":"반 모두가 함께할 수 있는 알뜰 시장 — 물건을 나누며 아끼는 마음을 배운다","correct":true},{"t":"비싼 놀이공원 가기 — 가장 신나기 때문이다","mis":"K4-1-u2-X50"},{"t":"먼저 올라온 의견 — 먼저 썼기 때문이다","mis":"K4-1-u2-X50"},{"t":"축구를 잘하는 친구들끼리 시합하기 — 이기면 기쁘기 때문이다","mis":"K4-1-u2-X54"}],"explanation":["모두 함께할 수 있나요?","까닭이 뚜렷한가요?","알뜰 시장이에요."],"asset":{"type":"passage","lines":["체육 대회를 해요 · 함께 운동하면 친구들과 더 가까워지기 때문입니다.","도서관 봉사를 해요 · 학교를 위한 일이고 보람도 느끼기 때문입니다.","알뜰 시장을 열어요 · 쓰지 않는 물건을 나누며 아끼는 마음을 배우기 때문입니다."],"title":"학급 누리집 — 학급의 날에 무엇을 할까요?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#16','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C61',2,'mc','auto','「운동 — 구기 운동 — 축구」에서 「구기 운동」을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X57','K4-1-u2-X56']::text[],false,'{"seq":16,"concept":"K4-1-u2-C61","difficulty":2,"kind":"mc","stem":"「운동 — 구기 운동 — 축구」에서 「구기 운동」을 바르게 말한 것은 무엇인가요?","options":[{"t":"「운동」 안에 들면서 「축구」를 품는 넓은 무리이다","correct":true},{"t":"「운동」보다 넓은 무리이다","mis":"K4-1-u2-X57"},{"t":"「축구」 안에 드는 말이다","mis":"K4-1-u2-X57"},{"t":"「운동」과 상관없는 말이다","mis":"K4-1-u2-X56"}],"explanation":["구기 운동은 운동일까요?","축구는 구기 운동일까요?","가운데 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#17','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C13',3,'mc','auto','「실천 가능성 생각하기」 단계에서 하는 일은 무엇인가요?',ARRAY['K4-1-u2-X16','K4-1-u2-X25']::text[],false,'{"seq":17,"concept":"K4-1-u2-C13","difficulty":3,"kind":"mc","stem":"「실천 가능성 생각하기」 단계에서 하는 일은 무엇인가요?","options":[{"t":"모든 친구가 해낼 수 있는지 따져 본다","correct":true},{"t":"실천했을 때 좋아지는 점을 찾아 쓴다","mis":"K4-1-u2-X16"},{"t":"불편해지는 점은 없는지 살펴본다","mis":"K4-1-u2-X16"},{"t":"가장 먼저 의견을 말한다","mis":"K4-1-u2-X25"}],"explanation":["「실천」 = 해내기","모두 할 수 있나요?","따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#18','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C32',3,'mc','auto','「㉮ 주말에는 운동장을 열어요」에서 의견이 담긴 문장은 어디에 있나요?',ARRAY['K4-1-u2-X33','K4-1-u2-X32','K4-1-u2-X28']::text[],false,'{"seq":18,"concept":"K4-1-u2-C32","difficulty":3,"kind":"mc","stem":"「㉮ 주말에는 운동장을 열어요」에서 의견이 담긴 문장은 어디에 있나요?","options":[{"t":"첫 문장과 마지막 문장","correct":true},{"t":"마지막 문장에만","mis":"K4-1-u2-X33"},{"t":"가운데 문장에만","mis":"K4-1-u2-X32"},{"t":"어디에도 없다","mis":"K4-1-u2-X28"}],"explanation":["①과 ⑥을 봐요.","처음과 끝","두 곳이에요."],"asset":{"type":"passage","lines":["① 주말에도 학교 운동장을 마을 사람들에게 열었으면 좋겠습니다.","② 우리 마을에는 아이들이 마음 놓고 뛸 만한 넓은 터가 없습니다.","③ 운동장을 열면 마을 사람들이 함께 운동할 곳이 생깁니다.","④ 사람이 자주 드나드는 곳은 오히려 눈길이 닿아 잘 살펴집니다.","⑤ 직접 써 본 곳에는 남다른 정이 들어 아끼는 사람이 늘어납니다.","⑥ 운동장을 여는 일은 학교와 마을이 함께 사는 길입니다."],"title":"㉮ 주말에는 운동장을 열어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#19','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C42',3,'mc','auto','「㉰ 먹을 만큼 받아요」에 대한 내 의견을 바르게 세운 것은 무엇인가요?',ARRAY['K4-1-u2-X40','K4-1-u2-X07','K4-1-u2-X39']::text[],false,'{"seq":19,"concept":"K4-1-u2-C42","difficulty":3,"kind":"mc","stem":"「㉰ 먹을 만큼 받아요」에 대한 내 의견을 바르게 세운 것은 무엇인가요?","options":[{"t":"찬성해. 나도 많이 받았다가 남긴 적이 있는데 조금씩 받으니 다 먹을 수 있었기 때문이야.","correct":true},{"t":"찬성해.","mis":"K4-1-u2-X40"},{"t":"글쓴이가 그렇게 말했으니 찬성해.","mis":"K4-1-u2-X07"},{"t":"반대해. 글쓴이가 틀렸어.","mis":"K4-1-u2-X39"}],"explanation":["의견 + 뒷받침","내 경험도 근거","까닭까지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#20','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C51',3,'mc','auto','㉰와 ㉱의 좋은 점을 함께 담은 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u2-X45','K4-1-u2-X25']::text[],false,'{"seq":20,"concept":"K4-1-u2-C51","difficulty":3,"kind":"mc","stem":"㉰와 ㉱의 좋은 점을 함께 담은 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"처음에 받을 양을 말하게 하고, 더 먹고 싶은 친구는 마지막에 한 번 더 받게 한다","correct":true},{"t":"모두 두 번씩 줄을 서게 한다","mis":"K4-1-u2-X45"},{"t":"음식을 아예 조금만 준다","mis":"K4-1-u2-X45"},{"t":"먼저 쓴 ㉰만 따른다","mis":"K4-1-u2-X25"}],"explanation":["남기지 않기 + 붐비지 않기","둘 다 담아요.","함께하는 방법"],"asset":{"type":"passage","lines":["① 모두가 두 번씩 줄을 서면 배식대 앞이 붐빕니다.","② 그러면 늦게 받는 친구는 점심을 서둘러 먹어야 합니다.","③ 처음부터 알맞게 받을 수 있도록 양을 미리 말해 주면 좋겠습니다."],"title":"㉱ 처음부터 알맞게 받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#21','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C20',3,'mc','auto','「책꽂이 토의」에서 사회자 시온이가 하면 안 되는 일은 무엇인가요?',ARRAY['K4-1-u2-X19','K4-1-u2-X20']::text[],false,'{"seq":21,"concept":"K4-1-u2-C20","difficulty":3,"kind":"mc","stem":"「책꽂이 토의」에서 사회자 시온이가 하면 안 되는 일은 무엇인가요?","options":[{"t":"「제 생각엔 붙임딱지가 제일 좋으니 그걸로 정하겠습니다.」라고 말한다","correct":true},{"t":"「아직 말하지 않은 친구도 말해 주세요.」라고 말한다","mis":"K4-1-u2-X19"},{"t":"「주제에서 벗어난 이야기는 나중에 해요.」라고 말한다","mis":"K4-1-u2-X20"},{"t":"「이제 모은 의견을 기준에 따라 결정해 봅시다.」라고 말한다","mis":"K4-1-u2-X19"}],"explanation":["사회자는 이끄는 사람","혼자 정해 버리면?","안 돼요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"오늘 주제는 「학급 책꽂이의 책이 자꾸 없어지는 문제를 어떻게 해결할까」입니다. 유진이부터 말해 주세요."},{"who":"유진","text":"빌려 가는 사람이 공책에 이름과 날짜를 적으면 좋겠습니다. 누가 가져갔는지 알 수 있기 때문입니다."},{"who":"지민","text":"책마다 반 이름 붙임딱지를 붙이면 좋겠습니다. 다른 반에 섞여도 찾아올 수 있기 때문입니다."},{"who":"예준","text":"책꽂이를 예쁘게 칠하면 좋겠습니다. 왜냐하면 저는 초록색을 좋아하기 때문입니다."},{"who":"시온","text":"아직 말하지 않은 친구도 있으니 차례대로 더 들어 보겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#22','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C59',3,'mc','auto','「만큼」을 붙여 쓰는 경우와 띄어 쓰는 경우를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u2-X54','K4-1-u2-X53']::text[],false,'{"seq":22,"concept":"K4-1-u2-C59","difficulty":3,"kind":"mc","stem":"「만큼」을 붙여 쓰는 경우와 띄어 쓰는 경우를 바르게 말한 것은 무엇인가요?","options":[{"t":"「언니만큼」은 붙이고, 「노력한 만큼」은 띄운다","correct":true},{"t":"「만큼」은 언제나 띄어 쓴다","mis":"K4-1-u2-X54"},{"t":"「만큼」은 언제나 붙여 쓴다","mis":"K4-1-u2-X53"},{"t":"「언니 만큼」은 띄우고 「노력한만큼」은 붙인다","mis":"K4-1-u2-X53"}],"explanation":["앞말이 이름이면?","앞말이 「-ㄴ」이면?","두 경우가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#23','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C26',4,'essay','teacher','「일인일역 토의」의 서준이와 나윤이의 의견을 의견 결정 기준 하나로 견주어 평가하고, 두 의견을 합친 새 의견을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u2-C26","difficulty":4,"kind":"essay","stem":"「일인일역 토의」의 서준이와 나윤이의 의견을 의견 결정 기준 하나로 견주어 평가하고, 두 의견을 합친 새 의견을 쓰세요.","answer_guide":{"answer":"예: 「모든 친구가 실천할 수 있는가」로 보면 나윤이의 의견은 모두가 스스로 고른 일을 맡아 실천하기 쉽고, 서준이의 의견은 칭찬받는 친구가 몇 명뿐일 수 있다. 새 의견 — 신청을 받아 일을 맡기고, 달마다 맡은 일을 꾸준히 한 친구를 모두 칭찬하자.","scoring_points":["결정 기준 하나를 들어 견주었는가","두 의견을 모두 평가했는가","두 의견을 합친 새 의견을 썼는가"]},"explanation":["기준 하나","두 의견 견주기","합친 새 의견"],"asset":{"type":"speech","turns":[{"who":"주제","text":"학급 일인일역을 어떻게 정하면 좋을까"},{"who":"서준","text":"일인일역을 가장 열심히 한 친구를 뽑아 칭찬하면 좋겠습니다."},{"who":"서준","text":"왜냐하면 칭찬을 받으면 보람이 생겨 더 열심히 하기 때문입니다."},{"who":"나윤","text":"학급에 필요한 일을 적어 두고 신청을 받으면 좋겠습니다."},{"who":"나윤","text":"왜냐하면 모두가 스스로 고른 일을 맡을 수 있기 때문입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#24','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C30',4,'essay','teacher','사실 문장 하나와 의견 문장 하나를 「우리 반 교실」을 글감으로 만들고, 문장 끝말을 들어 각각 사실과 의견인 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u2-C30","difficulty":4,"kind":"essay","stem":"사실 문장 하나와 의견 문장 하나를 「우리 반 교실」을 글감으로 만들고, 문장 끝말을 들어 각각 사실과 의견인 까닭을 쓰세요.","answer_guide":{"answer":"예: 사실 — 우리 반 교실에는 책상이 스물네 개 있습니다. 「있습니다」로 있는 것을 알려 준다. 의견 — 우리 반 교실에 책꽂이를 하나 더 두어야 합니다. 「해야 합니다」로 글쓴이의 생각을 나타낸다.","scoring_points":["사실 문장을 만들었는가","의견 문장을 만들었는가","끝말을 들어 까닭을 썼는가"]},"explanation":["있는 일","생각","끝말이 실마리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u2_review_d#25','kor',4,1,'u2','','g4_1_kor_u2_review_d','unit_review','K4-1-u2-C43',4,'essay','teacher','「당나귀를 팔러 간 아버지와 아들」 이야기와 이 단원에서 배운 평가 기준을 이어, 글을 읽을 때 글쓴이의 의견을 어떻게 받아들여야 하는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u2-C43","difficulty":4,"kind":"essay","stem":"「당나귀를 팔러 간 아버지와 아들」 이야기와 이 단원에서 배운 평가 기준을 이어, 글을 읽을 때 글쓴이의 의견을 어떻게 받아들여야 하는지 쓰세요.","answer_guide":{"answer":"예: 아버지와 아들은 지나가는 사람의 말을 따져 보지 않고 그대로 따르다가 당나귀를 잃었다. 글을 읽을 때에도 글쓴이의 의견을 그대로 따르지 말고, 뒷받침이 알맞은지 · 믿을 수 있는지 · 다른 문제는 없는지 따져 본 뒤 받아들여야 한다.","scoring_points":["이야기의 교훈을 썼는가","평가 기준을 들었는가","따져 본 뒤 받아들여야 한다고 썼는가"]},"explanation":["당나귀 이야기","세 기준","따져 보고 받아들이기"],"asset":{"type":"passage","lines":["① 아버지와 아들이 당나귀를 끌고 장으로 가고 있었다.","② \"당나귀를 두고 걸어가다니 어리석구나.\" 지나가던 사람이 말했다.","③ 말을 들을 때마다 둘은 타고, 바꾸어 타고, 함께 타기를 되풀이했다.","④ 끝내 당나귀를 메고 다리를 건너다 당나귀를 물에 빠뜨렸다."],"title":"당나귀를 팔러 간 아버지와 아들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
